window.__CHRONICLE_CHUNK["wd-04"] = [
  {id:"world--1500--x01",track:"world",year:1500,yearApprox:false,dim:"explore",weight:3,"title":"卡布拉略到达巴西海岸","summary":"向南探险船队西转，葡萄牙人遂据美洲一角。",detail:{"background":"若望二世因达伽马那次航行之事方急，另交卡布拉略率十余条船向西南再探，想验证亚美利哥所说的那片新地。","process":"1500年4月22日他们望见今巴伊亚一带海岸，占其港口名之安全港，五月回报里斯本；这片地方在托尔德西拉斯线以内。","impact":"此海岸既取，葡萄牙在南美占住一角；后来的巴西有糖园、矿场与奴隶贸易，皆自此线开始。",figures:["佩德罗·阿尔瓦雷斯·卡布拉略","（其领航者）佩雷斯特雷洛","（葡王）若望二世"],place:"巴伊亚（今巴西东南岸）",state:"葡萄牙王国、图皮诸部",sources:["卡布拉略致葡王书信与里斯本王室账册","《葡国地理大发现史》"],tags:["航海","巴西"]},related:["world--1494--p01", "world--1498--x01"]},
  {id:"world--1501--c01",track:"world",year:1501,yearApprox:false,dim:"culture",weight:3,"title":"阿尔杜斯出版八开本古典丛书","summary":"开本变小、用上斜体新字，古典文本可以装进随身口袋。",detail:{"background":"威尼斯人阿尔杜斯·曼努提乌斯从1495年开办印刷场，延希腊学者做校勘，旧时多用大开本印书。","process":"1501年刊印维吉尔八开本，自称可以随身带着的古典书，接着出贺拉斯、奥维德与希腊各家数十种，更铸斜体字以省纸。","impact":"书价既降而读者渐广，斜体与校勘之法为欧洲沿用；人文主义遂为读书人的常学，这些小本便是其工具。",figures:["阿尔杜斯·曼努提乌斯","（其校勘者）本布斯","（其字工）格里福"],place:"威尼斯",state:"威尼斯共和国",sources:["阿尔杜版原书与其序跋、1502年致读者书","《早期印刷与人文主义研究》"],tags:["印刷","人文主义"]},related:["world--1455--s01", "world--1507--s01"]},
  {id:"world--1505--i01",track:"world",year:1505,yearApprox:false,dim:"institution",weight:3,"title":"葡王设立「印度国家」总督府","summary":"每年遣武装船队，于东方设总督与商栈。",detail:{"background":"达伽马回国后，葡王定下以炮火夺商路之策，1500年卡布拉略已设商栈，却无常设的制度。","process":"1505年若望二世以阿尔梅达为首任总督，率十五条船的武装船队东行，定下三年一任，于科钦、奎隆各港设商栈，又立「印度之家」掌货物与账目。","impact":"东方自此有常设官员、岁至之船与王家垄断的贸易，一家一姓的海路遂成国家衙门；荷兰、英吉利后来皆仿此制成立公司。",figures:["（葡王）若望二世","（首任总督）弗朗西斯科·德·阿尔梅达","（其继者）阿尔布克尔克"],place:"里斯本、科钦",state:"葡萄牙王国、马拉巴尔诸港",sources:["印度任命状与「印度之家」账册、（加斯科雷《印度史》）","《葡属印度行政制度研究》"],tags:["总督府","贸易垄断"]},related:["world--1498--x01", "world--1509--m01"]},
  {id:"world--1507--s01",track:"world",year:1507,yearApprox:false,dim:"science",weight:3,"title":"地图上第一次标出「亚美利加」","summary":"据亚美利哥之说，制图家别定新洲名。",detail:{"background":"亚美利哥·韦斯普奇1502、1504年两封信说所到之处不是亚洲，乃古人未闻之别一世界，流传甚广。","process":"1507年圣迪耶的瓦尔德泽米勒与同学刊行世界地图与《宇宙志引论》，于南方大陆标出「亚美利加」，1513年改版时又以此名标北边那片地方。","impact":"一洲之名自此定下，绘图与地理书皆沿用之；新地方先在地图上为定说、后来才归于实测，即其一例。",figures:["马丁·瓦尔德泽米勒","亚美利哥·韦斯普奇","（其赞助者）格拉克曼"],place:"圣迪耶（今洛林）",state:"洛林公国、神圣罗马帝国",sources:["1507年图之存本与《宇宙志引论》文本","《早期制图学与亚美利加之名研究》"],tags:["制图","新大陆"]},related:["world--1500--x01", "world--1513--x01"]},
  {id:"world--1509--m01",track:"world",year:1509,yearApprox:false,dim:"military",weight:4,"title":"第乌海战：葡萄牙夺印度洋制海权","summary":"船上炮火摧破马穆鲁克—古吉拉联合舰队。",detail:{"background":"阿尔梅达之子洛伦索在乔尔战死，马穆鲁克、古吉拉与卡利卡特战船会于第乌，葡王援船刚到。","process":"1509年2月初，阿尔梅达以十余条船合击，船炮与接舷战从午时打到日暮，联合舰队焚者沉者殆尽，葡人所失仅数条船。","impact":"此战定下此后一百年欧船在印度洋之势，商路与朝觐船悉归其炮口之下；马穆鲁克红海—印度一线遂不能出战。",figures:["（葡印总督）弗朗西斯科·德·阿尔梅达","（古吉拉守将）马利克·艾亚兹","（其继者）阿尔布克尔克"],place:"第乌（今古吉拉外海）",state:"葡萄牙「印度国家」、马穆鲁克苏丹国、古吉拉",sources:["阿尔梅达书札与科雷亚《印度史》、奥斯曼与古吉拉记事","《第乌与葡属印度洋海权研究》"],tags:["海战","火器"]},related:["world--1498--x01", "world--1510--p01"]},
  {id:"world--1510--p01",track:"world",year:1510,yearApprox:false,dim:"politics",weight:3,"title":"阿尔布克尔克攻取果阿","summary":"果阿三天易主，终归葡人，遂为东方之都。",detail:{"background":"阿尔梅达一心想取莫尔木忽，阿尔布克尔克接任后欲得可反复攻取的港口；果阿时属比贾普尔之阿德尔沙。","process":"1510年3月初取下、四月又弃，8月探知守军单薄，11月25日再度入城，守军尽杀而惟于居民从宽，迁市集于北岸旧果阿。","impact":"果阿为葡属印度首府与主教区，三百年间的贸易与传教皆由其总管；夺占海口、给发通行证之法，后来亦行于马六甲。",figures:["阿尔丰索·德·阿尔布克尔克","（比贾普尔苏丹）伊斯玛仪·阿德尔沙","（其副）诺罗尼亚"],place:"果阿（今印度西岸）",state:"葡萄牙「印度国家」、阿迪勒·沙阿王朝",sources:["阿尔布克尔克《评论》与其部属记事、比贾普尔方记载","《葡属果阿史研究》"],tags:["据点","征服"]},related:["world--1509--m01", "world--1511--m01"]},
  {id:"world--1511--m01",track:"world",year:1511,yearApprox:false,dim:"military",weight:4,"title":"葡人攻陷马六甲","summary":"欧洲兵数百名协助本地军，共下海峡之城。",detail:{"background":"马六甲为东南各方货物聚集之地，葡人欲断回商往来；阿尔布克尔克从果阿带来船十七、兵千二百。","process":"1511年7月围城，8月10日攻破对方的寨与苏丹宫殿，末代苏丹马哈穆德逃往柔佛；第二年筑圣地亚哥堡以守海峡。","impact":"香料、中国货与日本银子的海路皆走马六甲—果阿一线，闽商、马来人与欧洲炮口相接；东南亚从此入于殖民之世。",figures:["阿尔丰索·德·阿尔布克尔克","（马六甲末苏丹）马哈穆德沙","（其通事）皮雷斯"],place:"马六甲",state:"马六甲苏丹国、葡萄牙「印度国家」",sources:["阿尔布克尔克《评论》、皮雷斯《东方志》、《马来年谱》","《马六甲之亡与海峡贸易研究》"],tags:["征服","香料"]},related:["world--1510--p01", "world--1519--x01"]},
  {id:"world--1512--i01",track:"world",year:1512,yearApprox:false,dim:"institution",weight:3,"title":"《布尔戈斯法》定下印第安人「保护」","summary":"名虽自由，实限其劳役，教理与劳役并列。",detail:{"background":"加勒比各岛上的印第安人接连死去，1511年讲道修士与王室会议相争，斐迪南命法学家商议此事。","process":"1512年12月27日颁行《布尔戈斯法》：此辈名义上是自由而受「保护」，各庄园定其人数、限劳役之力、责与教理住所，另设判官巡行。","impact":"此为欧洲首部以文字定「被殖民者」身份之法律；委托监护之制遂行于西属美洲三世，而役死之数未减。",figures:["（主其议者）塞维利亚的玛托","（讲道修士）蒙特西诺斯","费尔南多二世"],place:"布尔戈斯（今卡斯蒂利亚）",state:"卡斯蒂利亚王国、西属印度",sources:["《布尔戈斯法》原文与王室会议记录、修士书札","《委托监护制与印度法研究》"],tags:["殖民法","劳役"]},related:["world--1492--x01", "world--1520--d01"]},
  {id:"world--1513--c01",track:"world",year:1513,yearApprox:false,dim:"culture",weight:4,"title":"马基雅维利写作《君主论》","summary":"据实际事势，不论应当如何，论取国守邦之术。",detail:{"background":"1512年美第奇家复辟，马基雅维利免职、受审之后贬居圣卡西亚诺的庄园，冬夜入小书斋读古人之书。","process":"1513年7至12月写定二十六章，论世袭与新城、本国军队与佣兵、机运与处置，说君主应当强力与权术并用，人畏惧胜过人爱戴。","impact":"这本书在他生前未刊（1532年才开始印行），却以其名命「马基雅维利主义」，成为政治论脱离道德神学的第一个标志。",figures:["尼科洛·马基雅维利","（其献书之主）洛伦佐·德·美第奇","（其友）韦托里"],place:"佛罗伦萨、圣卡西亚诺",state:"佛罗伦萨共和国、美第奇家",sources:["《君主论》原稿与1513年12月致韦托里书","《马基雅维利与佛罗伦萨政治研究》"],tags:["政治学","文艺复兴"]},related:["world--1516--c01", "world--1501--c01"]},
  {id:"world--1513--x01",track:"world",year:1513,yearApprox:false,dim:"explore",weight:3,"title":"巴尔沃亚望见「南海」","summary":"越达连山岭，欧洲人始知美洲之西有大洋。",detail:{"background":"达连圣玛丽亚的殖民者为饥荒、瘟疫与同土人战事所困，巴尔沃亚越出本分掌握这批人众。","process":"1513年9月25日他率四十人翻过山岭望见大洋，名之为南海，占取各处海湾并宣告它们归于卡斯蒂利亚。","impact":"欧洲人自此知其西边可通亚洲，地峡成两大洋之间的缝；功劳未受赏反死于冤狱，二十年后的说法遂为皮萨罗入秘鲁之向导。",figures:["巴斯克·努涅斯·德·巴尔沃亚","（引路之土酋）科马格雷","（其仇）恩西索"],place:"达连（今巴拿马地峡）",state:"卡斯蒂利亚王国、库埃瓦诸部",sources:["巴尔沃亚奏报与其讼案卷、奥维耶多记事","《南海之发现与达连研究》"],tags:["探险","地峡"]},related:["world--1507--s01", "world--1519--x01"]},
  {id:"world--1514--m01",track:"world",year:1514,yearApprox:false,dim:"military",weight:4,"title":"恰尔迪兰之战：火器击破基兹尔巴什","summary":"塞利姆以火枪大炮取胜，萨法维西界遂定。",detail:{"background":"沙阿伊斯玛仪扶持基兹尔巴什、在安纳托利亚传播什叶，塞利姆一世视为心腹之患，三次出征方成行。","process":"1514年8月23日两军在恰尔迪兰（今阿塞拜疆）会战，奥斯曼炮车与火枪兵挡住骑兵冲击，波斯军溃，辎重与技师尽为所获。","impact":"阿塞拜疆与东安纳托利亚并入奥斯曼，萨法维从此转向东边经营；安纳托利亚什叶乱事平定，两个帝国边界二百多年未改。",figures:["塞利姆一世","沙阿伊斯玛仪","（其将）阿赫苏·汗"],place:"恰尔迪兰（今伊朗西北）",state:"奥斯曼帝国、萨法维波斯",sources:["奥斯曼军报与编年、波斯与亚美尼亚方记载","《恰尔迪兰与两帝国之争研究》"],tags:["火器","会战"]},related:["world--1517--p01", "world--1402--m01"]},
  {id:"world--1515--m01",track:"world",year:1515,yearApprox:false,dim:"military",weight:3,"title":"马里尼亚诺：炮列击破瑞士长矛","summary":"野战炮连发，瑞士佣兵之威遂止。",detail:{"background":"教宗、威尼斯、瑞士与斯福扎结盟抗拒法国、反手要夺回米兰，新王弗朗索瓦一世越过阿尔卑斯山而来。","process":"1515年9月13、14日两军在马里尼亚诺（今米兰东）会战，法军以轻便野炮横列连射，瑞士三次进攻皆被打退，第二天订和约。","impact":"瑞士从此不复出兵意大利，1516年与法国订「永久之和」，其佣兵之业转为守中立；炮为野战主力，全欧洲皆见及此。",figures:["弗朗索瓦一世","（瑞士指挥）（无名之州使）","（米兰公爵）马克西米利亚诺·斯福扎"],place:"马里尼亚诺（今伦巴第）",state:"法兰西王国、瑞士诸州、米兰公国",sources:["法军记事、瑞士诸州编年与1516年和约抄件","《意大利战争与火器研究》"],tags:["火炮","佣兵"]},related:["world--1516--p01", "world--1525--m01"]},
  {id:"world--1516--c01",track:"world",year:1516,yearApprox:false,dim:"culture",weight:3,"title":"莫尔《乌托邦》刊行","summary":"借海岛公产之制，讥讽「羊吃人」。",detail:{"background":"都铎初期圈地、严刑与贫富之争方烈，莫尔趁出使佛兰德的空隙以拉丁文写成此书。","process":"1516年刊行于鲁汶，分两卷：前卷写与人论文士谈欧罗巴弊病，后卷记乌托邦共产、六时的劳役、容纳各教与选任官员。","impact":"这本书立「空想」一体，公产与共学之说自此有了式样；其名本为「无有之邦」，后世谈乌托邦者皆循此格套。",figures:["托马斯·莫尔","（其友）伊拉斯谟","（其言之由）希斯拉德"],place:"鲁汶、伦敦",state:"英格兰王国",sources:["《乌托邦》1516年原本与莫尔书札","《都铎初期社会与乌托邦研究》"],tags:["空想","人文主义"]},related:["world--1516--p01", "world--1513--c01"]},
  {id:"world--1516--p01",track:"world",year:1516,yearApprox:false,dim:"politics",weight:3,"title":"斐迪南去世：卡洛斯入承西班牙","summary":"两个王国归同一外孙，哈布斯堡氏君临伊比利亚。",detail:{"background":"伊莎贝拉1504年卒，斐迪南再娶而无子嗣，女胡安娜因病被废、居托德西亚斯。","process":"1516年1月23日斐迪南去世，外孙佛兰德的卡洛斯以母与己之名并领卡斯蒂利亚与阿拉贡，枢机希梅内斯起初摄政。","impact":"西班牙、尼德兰、南意大利与（1519）帝冠自此归于一姓，四面皆敌；西属美洲的金银也开始供给其兵费。",figures:["卡洛斯一世（查理五世）","阿拉贡的斐迪南二世","（摄政）希梅内斯"],place:"马达利亚、布鲁塞尔",state:"卡斯蒂利亚与阿拉贡、尼德兰",sources:["斐迪南遗嘱与王室文书、希梅内斯传记事","《哈布斯堡西班牙之起源研究》"],tags:["王朝","并合"]},related:["world--1512--i01", "world--1519--p01"]},
  {id:"world--1517--c01",track:"world",year:1517,yearApprox:false,dim:"culture",weight:5,"title":"路德发表《九十五条论纲》","summary":"对赎罪券提出质问，印刷术替他传布辞说。",detail:{"background":"美因茨的阿尔伯特借富格家债款售赎罪券，特策尔行于选侯边境布道，路德出于牧职责任起而质问。","process":"1517年10月31日前后提出拉丁文论纲九十五条（相传贴于维滕贝格各圣堂门上，此事是否确凿今犹有争论），说教宗无赦罪之权、炼狱之说不清。","impact":"论纲在两个月之间译印遍及德意志，赎金与教宗权力同时受质疑；1520年教宗诏书至而路德焚之，西方教会自此不复为一。",figures:["马丁·路德","（售券之主）美因茨的阿尔伯特","（其敌）特策尔"],place:"维滕贝格",state:"萨克森选侯国、教廷",sources:["《九十五条论纲》原本与1517—1518年诸印本、路德书信","《路德与宗教改革研究》"],tags:["改革","赎罪券"]},related:["world--1520--c01", "world--1455--s01"]},
  {id:"world--1517--p01",track:"world",year:1517,yearApprox:false,dim:"politics",weight:4,"title":"奥斯曼消灭马穆鲁克并领有麦加","summary":"一战破其苏丹，哈里发称号北移。",detail:{"background":"马穆鲁克援助速非耶党和波斯，塞利姆一世以红海与安纳托利亚之故东征。","process":"1517年1月22日里达尼亚之战破图曼贝伊，4月进入开罗；麦加的谢里夫先前已献城门钥匙与正统称号，冬天图曼贝伊绞死在其门上。","impact":"奥斯曼得埃及粮食与赋税、红海港口与两圣寺保护之权，苏丹兼「两圣寺之仆」；马穆鲁克退为埃及当地的地头蛇，其地遂成土邦。",figures:["塞利姆一世","（末马穆鲁克苏丹）图曼贝伊","（麦加谢里夫）巴拉卡特"],place:"开罗、麦加",state:"奥斯曼帝国、马穆鲁克苏丹国、麦加埃米尔",sources:["伊本·伊亚斯《巧园》、奥斯曼卷宗与欧洲使报","《1517年与中东之局研究》"],tags:["征服","哈里发"]},related:["world--1514--m01", "world--1258--m01"]},
  {id:"world--1519--f01",track:"world",year:1519,yearApprox:false,dim:"figure",weight:3,"title":"达·芬奇卒于昂布瓦兹","summary":"六十七岁客死法国宫廷，留手稿数千页于后世。",detail:{"background":"达·芬奇晚年离开米兰、罗马，1516年应弗朗索瓦一世之招越过阿尔卑斯山，带着《圣母子与圣安妮》等作品。","process":"1519年5月2日他卒于昂布瓦兹的别庄，葬于当地修院教堂；弟子梅尔齐得到他手稿的托付，笔记抄本遂散落意大利与法国。","impact":"手稿论解剖、水力、飞行器具与地质，为技艺与测量未分者的最高范本；后世视其图为工技之祖，亦惜散佚。",figures:["列奥纳多·达·芬奇","（其弟子）梅尔齐","弗朗索瓦一世"],place:"昂布瓦兹",state:"法兰西王国",sources:["梅尔齐手稿序、1519年法廷记事与笔记抄本","《达·芬奇与手稿传统研究》"],tags:["技艺","手稿"]},related:["world--1516--c01", "world--1543--s01"]},
  {id:"world--1519--p01",track:"world",year:1519,yearApprox:false,dim:"politics",weight:4,"title":"查理五世当选罗马人的国王","summary":"以富格家金子当选，四世之后此姓并立。",detail:{"background":"马克西米利安于1519年1月去世，查理凭西班牙的富有与债家金钱，同法王弗朗索瓦争选位。","process":"1519年6月28日七大选帝侯举其当选，所偿选举费八十五万古尔登多出富格；10月在亚琛加冕，1520年与法国于西部边界开战。","impact":"他并有西班牙、尼德兰、南意大利与帝冠，法兰西遂处其包围之中；「一君之天下过广」是当时人语，后来的分治判奥地利与西班牙为两支。",figures:["查理五世","（选帝者）美因茨的阿尔伯特","（其债家）雅各布·富格"],place:"法兰克福、亚琛",state:"神圣罗马帝国、西班牙、尼德兰",sources:["选帝之协议与选举 capitulatio 文本、富格账房文书","《查理五世与帝国之局研究》"],tags:["选帝","哈布斯堡"]},related:["world--1516--p01", "world--1521--p01"]},
  {id:"world--1519--x01",track:"world",year:1519,yearApprox:false,dim:"explore",weight:4,"title":"麦哲伦奉命启程向西航行","summary":"五条船二百七十人，南行求入南海航路。",detail:{"background":"麦哲伦在葡王麾下不见用，乃转事西王，与法利罗上言云有海峡可通香料群岛，其地正当托氏线之西。","process":"1519年9月20日他以五条船二百七十余人从圣卢卡尔出港，1520年10月至今麦哲伦海峡，十一月底入南海，此时已失两条船。","impact":"此航得两大洋之间的路，香料群岛界分遂成两国争讼（1524、1529）；西人自此可以关岛、菲律宾为据点而东向航行。",figures:["斐迪南·麦哲伦","（其随员）皮加费塔","（其通事之奴）恩里刻"],place:"圣卢卡尔、麦哲伦海峡",state:"西班牙、香料群岛诸苏丹",sources:["皮加费塔行纪、西班牙与葡国航海文书","《麦哲伦环航研究》"],tags:["环航","海峡"]},related:["world--1492--x01", "world--1521--f01"]},
  {id:"world--1520--c01",track:"world",year:1520,yearApprox:false,dim:"culture",weight:4,"title":"路德三大论著与焚教宗诏","summary":"以信徒皆祭司立说，冬夜投教宗诏于火。",detail:{"background":"1520年教宗诏书《兴起》斥其四十条为异端，限期六月；德意志的廷臣与大学两边相持不下。","process":"同年路德成《德意志民族之教改》《教会被掳于巴比伦》《论基督徒之自由》，言圣洗在于信、祭司唯一；12月10日焚教宗诏书于维滕贝格。","impact":"唯信与信徒皆祭司之说自此为纲领，诸侯财产与世俗礼仪皆随此议而动；第二年沃尔姆斯对质，所争者是他本人。",figures:["马丁·路德","（宣诏者）教宗使节阿尔滕堡","（其护者）萨克森的弗里德里希"],place:"维滕贝格",state:"萨克森选侯国、教廷",sources:["三大论著原本、1520年教宗诏与路德书信","《1520年：路德改革之年研究》"],tags:["教改","信仰"]},related:["world--1517--c01", "world--1521--p01"]},
  {id:"world--1520--d01",track:"world",year:1520,yearApprox:false,dim:"disaster",weight:4,"title":"天花传入特诺奇蒂特兰","summary":"疫自一船北传，数月间死十分之四五。",detail:{"background":"纳瓦雷斯船自古巴来，船上有患天花的黑人，此疫随战事与人群北传入谷地。","process":"1520年9至12月城中大疫，新立的苏丹（希特劳阿特拉）以下死者相继，诸记载都说死了十分之四五，尸不及埋、食物吃尽。","impact":"围城之前守御之力已然先毁，1521年被破遂易；谷地各邦相继染疫，中部美洲人口与祭司、书图传承俱丧。",figures:["（染疫而卒者）希特劳阿特拉","（疫所自至者）纳瓦雷斯船众","（记其事者）贝尔塔尔"],place:"特诺奇蒂特兰、墨西哥谷地",state:"墨西加（阿兹特克）及诸土邦",sources:["《佛罗伦萨抄本》土著一面之记、贝尔塔尔《历书志》","《新世界之疫与征服研究》"],tags:["天花","人口"]},related:["world--1512--i01", "world--1521--m01"]},
  {id:"world--1521--f01",track:"world",year:1521,yearApprox:false,dim:"figure",weight:3,"title":"麦哲伦卒于马克坦","summary":"率五十人登小岛，为土人长矛所刺。",detail:{"background":"船队入南海后得关岛与菲律宾诸岛，麦哲伦欲以武力胁迫马克坦的首领奉西班牙与一神。","process":"4月27日清晨率五十人涉水登岸，土人围而刺之，他死于滩上，同死者七人；两艘船被焚，余三艘继续西行。","impact":"他的死使环球航行的功业归到接任者身上，1522年一条船得以归还；西人占菲律宾之议因此暂辍，到1565年才又起来。",figures:["斐迪南·麦哲伦","（马克坦首领）拉普拉普","（其通事之奴）恩里刻"],place:"马克坦（今菲律宾宿务外岛）",state:"西班牙、菲律宾诸部",sources:["皮加费塔行纪、1522年归后之审讯录","《马克坦之殁与菲律宾初遇研究》"],tags:["环航","阵亡"]},related:["world--1519--x01", "world--1522--x01"]},
  {id:"world--1521--m01",track:"world",year:1521,yearApprox:false,dim:"military",weight:5,"title":"特诺奇蒂特兰城陷落","summary":"堤堵水路、船绝粮道，八十多日城遂毁。",detail:{"background":"科尔特斯借各土邦之怨与特拉斯卡拉的兵力再入谷地；1520年六月夜败（所谓悲伤之夜）之后，收拾人众再来。","process":"1521年5月起自陆路围之，筑堤堵水渠、造战船十三艘以绝城中淡水与粮食，疫病与饥荒俱至；8月13日末王奎察尔科阿特尔被擒，城旋焚毁。","impact":"谷地邦国、贡赋与书图尽毁，新西班牙总督府即以此石建于原址；西班牙由是定中美，传教与役使百姓的制度随之俱来。",figures:["埃尔南·科尔特斯","（末王）奎察尔科阿特尔","（其译人）马林切"],place:"特诺奇蒂特兰",state:"墨西加（阿兹特克）、卡斯蒂利亚",sources:["科尔特斯奏书、《佛罗伦萨抄本》与贝尔塔尔记事","《阿兹特克之亡研究》"],tags:["围城","征服"]},related:["world--1520--d01", "world--1428--p01"]},
  {id:"world--1521--p01",track:"world",year:1521,yearApprox:false,dim:"politics",weight:4,"title":"沃尔姆斯会议与路德拒绝","summary":"敕书宣布其违法，选侯匿之城堡。",detail:{"background":"查理五世始至德意志主事，欲以帝国的法律处置路德一事，诸侯则各以上诉与教产为辞。","process":"1521年4、5月在沃尔姆斯议事，路德至而拒撤诉；5月3日下敕禁其书并禁其身，归途中为选侯所劫，匿于瓦特堡。","impact":"敕书终不行而改革亦未止：其所译新约刊行（1522），诸侯接连结盟，帝国的宗教程序至1555年方有法律定案。",figures:["查理五世","马丁·路德","（其护者）萨克森的弗里德里希"],place:"沃尔姆斯、瓦特堡",state:"神圣罗马帝国、萨克森选侯国",sources:["沃尔姆斯敕书文本、路德到议供词与当时记事","《路德与帝国会议研究》"],tags:["宗教改革","帝国"]},related:["world--1520--c01", "world--1519--p01"]},
  {id:"world--1522--m01",track:"world",year:1522,yearApprox:false,dim:"military",weight:3,"title":"苏莱曼攻取罗得岛","summary":"围城六个月而许其去，骑士团西迁。",detail:{"background":"医院骑士团据罗得岛，屡掠往来的商船，又曾挟国王之弟为质，苏莱曼刚即位即志取此岛。","process":"1522年6月起以大炮与地道攻城，12月守军请求投降，1523年元旦团长带人乘船离岛，其军有数万而死的也不少。","impact":"东爱琴海之路尽开，士麦那（1534）与希腊诸港相继入其手；骑士团从此流泊西方，1530年得马耳他，与奥斯曼为世仇。",figures:["苏莱曼一世","（团长）维利耶·德·利勒—亚当","（其炮工）（无名）"],place:"罗得岛",state:"奥斯曼帝国、医院骑士团",sources:["奥斯曼军报、骑士团记事与欧洲诸使报","《罗得与马耳他之围研究》"],tags:["围城","骑士团"]},related:["world--1517--p01"]},
  {id:"world--1522--x01",track:"world",year:1522,yearApprox:false,dim:"explore",weight:4,"title":"「维多利亚」号环球航行归来","summary":"一船十八个人归还，地球尺寸始有实测。",detail:{"background":"麦哲伦死后船队内乱，塞拉诺留在香料群岛死去，罗艾萨与埃尔卡诺分乘船只西归。","process":"1522年9月6日「维多利亚」入圣卢卡尔，存活者十八人，船载丁香而归；失船三条，死二百余人，而所历一路皆在西半边。","impact":"地球大小、太平洋广狭与日界线之奇，从此有实测之据；环球航路遂成可行，后世测经度之说皆循此头绪。",figures:["胡安·塞巴斯蒂安·埃尔卡诺","（同归之存者）十八名舟人","查理五世"],place:"圣卢卡尔—德—巴拉梅达",state:"西班牙",sources:["1522年归航之讯问录与船账、同时代书札","《第一次环航研究》"],tags:["环航","实测"]},related:["world--1519--x01", "world--1529--p01"]},
  {id:"world--1523--c01",track:"world",year:1523,yearApprox:false,dim:"culture",weight:3,"title":"慈运理主持苏黎世第一次辩论","summary":"市议会认其六十七款，圣像之敬就此废。",detail:{"background":"1522年瑞士斋期与印书之争方急，慈运理在圣母堂讲道，渐及弥撒与圣徒之祈祷。","process":"1523年1月29日市会集于座堂，审他所陈六十七款，谓教会只以圣经为根据、圣餐不是再献祭；市会从其议，许他照常讲道。","impact":"苏黎世从此为改革第二个中心，并立以市会议宗教之例；1524年废弥撒、去圣像，巴塞尔与伯尔尼相继效行。",figures:["乌尔里希·慈运理","（其对手）康斯坦茨主教之使","（其继者）布林格"],place:"苏黎世",state:"苏黎世市、瑞士诸州",sources:["1523年辩论记录与六十七款文本、慈运理著作集","《瑞士改革与慈运理研究》"],tags:["改革","市议"]},related:["world--1531--m01", "world--1517--c01"]},
  {id:"world--1524--c01",track:"world",year:1524,yearApprox:false,dim:"culture",weight:2,"title":"伊拉斯谟发表《论自由意志》","summary":"以人性未全坏难路德，两种说法自此分界。",detail:{"background":"路德在1520年论意志为罪所捆，人文主义一派恐善恶之功由此俱废，伊拉斯谟久持中和之论。","process":"1524年夏刊《论自由意志》，言人受洗之后尚有择善的力量，恩典与己力并行，圣经难明处当以谦和释之。","impact":"路德在1525年以《论意志之束缚》答复他，谓非此即彼；改革宗与人文主义之别，由此书定界。",figures:["德西德里乌斯·伊拉斯谟","马丁·路德","（其争之主）萨克森的弗里德里希"],place:"巴塞尔",state:"神圣罗马帝国、教廷",sources:["《论自由意志》原本与1526年诸印本、伊拉斯谟书信集","《伊拉斯谟与路德之争研究》"],tags:["人文主义","意志"]},related:["world--1520--c01", "world--1516--c01"]},
  {id:"world--1525--m01",track:"world",year:1525,yearApprox:false,dim:"military",weight:4,"title":"帕维亚之战：法国国王就擒","summary":"火绳枪与方阵击破骑兵冲击，法王落入西班牙之手。",detail:{"background":"1524年法军入伦巴第围帕维亚，查理五世的军队（西班牙方阵与德意志佣兵）来解围，欠饷而士气愈愤。","process":"1525年2月24日清晨雾中合战，法骑破对方辎重深入，西班牙火绳手与方阵伏林间横击之，波旁公爵战死，法军溃，法王负伤被擒。","impact":"法王囚于马德里约半年，遂弃对意大利的志向；1526年马德里之约旋被背弃，而意大利归哈布斯堡之势自此不可改。",figures:["弗朗索瓦一世","（其将）波旁公爵夏尔","（西军将）阿瓦洛斯"],place:"帕维亚（今伦巴第）",state:"法兰西王国、西班牙、神圣罗马帝国",sources:["西军战报、意大利诸邦使报与圭恰尔迪尼记事","《帕维亚与意大利战争研究》"],tags:["火器","被擒"]},related:["world--1515--m01", "world--1527--m01"]},
  {id:"world--1525--p01",track:"world",year:1525,yearApprox:false,dim:"politics",weight:4,"title":"德意志农民战争与《十二条款》","summary":"以文书约定申冤，诸侯合兵屠之。",detail:{"background":"1524年秋，士瓦本各村抗拒捐役，贵族、城市与改革之言相激；教产、狩猎与继承的诉讼百端并起。","process":"1525年《十二条款》刊行（谓以圣经为断、废人身之劳役），联众数万；弗龙茨贝格合诸侯之兵，5月15日破图林根人众于弗兰肯豪森，闵采尔被斩。","impact":"几个月之内死者以万计，农民之约废而领主之权愈固；路德以严词劝诸侯急速讨伐，诸侯从此独掌改革之事。",figures:["（诸侯将）格奥尔格·冯·弗龙茨贝格","托马斯·闵采尔","马丁·路德"],place:"士瓦本、图林根、弗兰肯",state:"神圣罗马帝国诸邦",sources:["《十二条款》诸印本、各邦审讯与编年记事","《德意志农民战争研究》"],tags:["民变","条约"]},related:["world--1524--c01", "world--1521--p01"]},
  {id:"world--1525--p02",track:"world",year:1525,yearApprox:false,dim:"politics",weight:2,"title":"条顿骑士团世俗化为普鲁士公国","summary":"大团长向波兰称臣，其地始为世袭邦国。",detail:{"background":"条顿团长年与波兰相争，骑士屡败而军饷用尽；大团长阿尔布雷希特从路德之劝。","process":"1525年4月10日克拉科夫之约，他以普鲁士之地受封于波兰王，改行路德之教，铸自己的钱币，其后开学于柯尼斯贝格。","impact":"波罗的海东岸从此无骑士团之国，一姓普鲁士渐强；波兰保有其臣属之名，此后一百年反倒为其祸患。",figures:["（末大团长）勃兰登堡的阿尔布雷希特","（波兰王）齐格蒙特一世","（其劝者）马丁·路德"],place:"柯尼斯贝格、克拉科夫",state:"普鲁士公国、波兰王国",sources:["克拉科夫之约文本与普鲁士账册、当时书札","《条顿团世俗化研究》"],tags:["世俗化","普鲁士"]},related:["world--1525--p01", "world--1242--m01"]},
  {id:"world--1526--m01",track:"world",year:1526,yearApprox:false,dim:"military",weight:4,"title":"摩哈赤之战：匈牙利王一次会战而亡","summary":"土军以大炮、骑兵破敌军，匈牙利一分为三。",detail:{"background":"苏莱曼东征既毕转向西方，拉约什二世在各邦之兵未集时轻率进军，联军遂离散。","process":"1526年8月29日至30日在摩哈赤开战，奥斯曼炮车与西帕希骑兵两面包抄，匈牙利军溃，国王溺于沼泽；土军入布达即引还。","impact":"匈牙利从此三分：土军据中部与布达，哈布斯堡得其西北，特兰西瓦尼亚为其藩属；奥斯曼常驻多瑙河，维也纳背后受逼。",figures:["苏莱曼一世","（匈牙利王）拉约什二世","（土将）帕尔加勒·易卜拉欣"],place:"摩哈赤（今匈牙利南部）",state:"奥斯曼帝国、匈牙利与波希米亚",sources:["奥斯曼军报、匈牙利与哈布斯堡方记事","《摩哈赤与匈牙利之亡研究》"],tags:["会战","火器"]},related:["world--1529--m01", "world--1389--m01"]},
  {id:"world--1527--m01",track:"world",year:1527,yearApprox:false,dim:"military",weight:4,"title":"罗马遭劫","summary":"欠饷军围罗马，抢掠一个多月不止。",detail:{"background":"查理五世的军有数万人而无饷（西班牙兵与德意志佣兵），南向罗马索积存；教宗克雷门七世方与法国及各邦结盟抗帝。","process":"1527年5月6日攻城，波旁公爵中炮而死；城破后烧杀延至六月末，居民死者以万计，教宗匿圣天使堡，至12月乃出降。","impact":"教宗的世俗权受此大辱，亨利八世婚案遂无人敢判；1530年查理五世在博洛尼亚由教宗加冕，罗马与皇帝相依益深。",figures:["（教宗）克雷门七世","（攻者之将）波旁公爵夏尔","（其继帅）奥尔西尼"],place:"罗马",state:"教廷、西班牙、神圣罗马帝国",sources:["亲历者记事、罗马城之簿册与佣兵之书札","《1527年罗马之劫研究》"],tags:["劫城","教廷"]},related:["world--1525--m01", "world--1530--c01"]},
  {id:"world--1527--p01",track:"world",year:1527,yearApprox:false,dim:"politics",weight:3,"title":"韦斯特罗斯议会定瑞典教产","summary":"许还教产于贵族，王权自任主教。",detail:{"background":"古斯塔夫·瓦萨借力得位，与教会议会争岁入与特权，1527年三次以退位相要挟。","process":"1527年6月议会开会于韦斯特罗斯，定国王与贵族分取归还教会的田产与什一，修道院财产多入王室，教会的司法权大为削弱。","impact":"瑞典从此有王室主导之教会而无诸侯抗命，此财足以供军费与行政；北欧各国遂成王室教会之类型。",figures:["（瑞典王）古斯塔夫·瓦萨","（其辅）劳伦提乌斯·安德烈","（其敌）（无名之主教）"],place:"韦斯特罗斯",state:"瑞典王国",sources:["议会决议抄件、瓦萨与主教书信、编年记事","《瓦萨与瑞典宗教改革研究》"],tags:["教产","王权"]},related:["world--1530--c01", "world--1523--c01"]},
  {id:"world--1529--i01",track:"world",year:1529,yearApprox:false,dim:"institution",weight:3,"title":"施派尔会议与「抗议者」之名","summary":"暂缓议论之令一撤，诸侯与城市上抗议状。",detail:{"background":"1526年施派尔会议许各邦暂行其是，候公会再定；1529年帝国会议以多数票撤先前所许。","process":"1529年4月19至25日，萨克森选侯等诸侯与各城市联名上抗议状，说信仰的事不能断以多数，惟圣经与良心可据。","impact":"「新教」之名从此而始；诸侯与城市之上诉为其法理凭据，1531年遂有施马尔卡尔登联盟。",figures:["（上状之主）萨克森选侯","（其状之笔）布吕克","（其敌）帝国会议之多数"],place:"施派尔",state:"神圣罗马帝国诸邦",sources:["1529年会议记录与抗议状文本","《施派尔之议与新教之名研究》"],tags:["上诉","帝国会议"]},related:["world--1530--c01", "world--1521--p01"]},
  {id:"world--1529--m01",track:"world",year:1529,yearApprox:false,dim:"military",weight:4,"title":"第一次围攻维也纳","summary":"秋雨陷其辎重，奥斯曼锋锐止于城下。",detail:{"background":"摩哈赤之后三年，苏莱曼自贝尔格莱德北进；费尔迪南德的守兵少而援军不至，德意志诸侯方自相猜疑。","process":"1529年9月27日至10月15日围城，土军携轻炮在雨中穿行，以地穴与火炮轰裂城墙而不得入；秋雪、疫病与粮食俱尽，乃解围。","impact":"此为其西进锋锐止住之处，哈布斯堡因是自居基督教之盾；1532年苏莱曼复来而以和约定之，两个皇帝的边界就此而成。",figures:["苏莱曼一世","（守者）奥地利费尔迪南德一世","（其将）萨尔姆"],place:"维也纳",state:"奥斯曼帝国、奥地利与神圣罗马帝国",sources:["守城之记、奥斯曼军报与德意志诸邦书札","《维也纳之围与两帝之界研究》"],tags:["围城","气候"]},related:["world--1526--m01", "world--1532--m02"]},
  {id:"world--1529--p01",track:"world",year:1529,yearApprox:false,dim:"politics",weight:3,"title":"萨拉戈萨条约：两国瓜分太平洋","summary":"以三十五万达卡卖摩鹿加之名，东线遂定。",detail:{"background":"麦哲伦之后两国都争香料群岛的归属，当时无法精确测定其经度，使节再议于阿拉贡。","process":"1529年4月22日订约，查理五世以三十五万达卡斯托金币（大多出自富格家的债款）将权利让于葡萄牙，定界线于摩鹿加以东十七度。","impact":"此约以太平洋东半归葡萄牙，为荷兰、英吉利后来的争夺留下口实；经度无法确定，直至测时器具出现才算完。",figures:["查理五世","（葡王）若望三世","（议界之宇宙志家）（无名）"],place:"萨拉戈萨",state:"西班牙、葡萄牙",sources:["约本原文与两国宇宙志会议状","《萨拉戈萨约与香料群岛之争研究》"],tags:["分界","经度"]},related:["world--1522--x01", "world--1494--p01"]},
  {id:"world--1530--c01",track:"world",year:1530,yearApprox:false,dim:"culture",weight:4,"title":"奥格斯堡信纲呈到御前","summary":"以二十八条陈其信仰，诸侯宗教始有定式。",detail:{"background":"查理五世想用帝国会议平息信仰之争，命各邦陈述己方信理；梅兰希顿集路德的说法为草稿。","process":"1530年6月25日路德宗诸侯呈《奥格斯堡信纲》于御前，前二十一条论信理，后七条论当改之礼仪；御前以其违背公会议的决定而拒绝。","impact":"信纲此后成为路德宗的标准文书（1540年的修订本也一样），诸侯宗教遂有可见界线；帝国宗教程序直到1555年才有和解。",figures:["菲利普·梅兰希顿","马丁·路德","（呈之者）萨克森选侯"],place:"奥格斯堡",state:"神圣罗马帝国诸邦",sources:["信纲原本（德、拉丁两式）、呈词与1530年会议记录","《奥格斯堡信纲研究》"],tags:["信纲","宗派"]},related:["world--1529--i01", "world--1555--p01"]},
  {id:"world--1531--m01",track:"world",year:1531,yearApprox:false,dim:"military",weight:3,"title":"第二次卡佩尔之战：慈运理阵亡","summary":"山林州兵乘雾夜至，改革派之城失主帅。",detail:{"background":"五个山林州不许改革派城市共征什一与安置难民的权力，两党争执不下，旧盟亦坏。","process":"1531年10月11日山州兵乘雾夜至卡佩尔，苏黎世的军队未及集结即败；慈运理身披甲胄，死于野战，尸首陈列两天。","impact":"瑞士的改革此后以各邦自定其信为限，共夺教会土地之议遂止；苏黎世得布林格接续，反为改革神学外传的枢纽。",figures:["乌尔里希·慈运理","（其继者）布林格","（山州之帅）（无名）"],place:"卡佩尔（今瑞士）",state:"瑞士诸州",sources:["两州之战报、市志与布林格书札","《卡佩尔之役与瑞士改革研究》"],tags:["内战","瑞士"]},related:["world--1523--c01", "world--1536--c01"]},
  {id:"world--1532--c01",track:"world",year:1532,yearApprox:false,dim:"culture",weight:1,"title":"《君主论》开始印行","summary":"作者死后五年书始出，其言为权术之名。",detail:{"background":"马基雅维利1527年去世，其书靠抄本流传于士人之间，献书的打算未成。","process":"1532年罗马、佛罗伦萨相继刊行，题名《君主论》；不久巴黎亦印出，他死后的毁誉遂靠印本传播。","impact":"此书刊成之后，「马基雅维利主义」成为欧洲人的常语；1559年列入禁书目录而读者更多，政治论说之独立自此有书名可据。",figures:["尼科洛·马基雅维利","（其刊者）（罗马之印匠）","（其后之批者）反马基之诸家"],place:"罗马、佛罗伦萨",state:"教廷、意大利诸城",sources:["1532年诸印本与1559年禁目、同时代批注","《马基雅维利之流传研究》"],tags:["出版","政治学"]},related:["world--1513--c01", "world--1501--c01"]},
  {id:"world--1532--m01",track:"world",year:1532,yearApprox:false,dim:"military",weight:5,"title":"卡哈马尔卡：阿塔瓦尔帕就擒","summary":"一百六十多人设伏，一战而得印加国。",detail:{"background":"皮萨罗自巴拿马南行，探知印加的内战甫定、阿塔瓦尔帕驻军卡哈马尔卡，遂带少量兵力深入。","process":"1532年11月16日他以骑兵、火铳与伏兵呐喊而进，左右乱成一团，土人被杀几千而欧兵无一人战死，国王就擒于轿中。","impact":"赎金虽已凑足（装满一屋金银，到1533年夏天才交完），国王竟以弑兄、偶像等罪被处死；塔万廷苏尤的驿道、仓库与矿山遂归西班牙。",figures:["弗朗西斯科·皮萨罗","阿塔瓦尔帕","（其译人）费利佩"],place:"卡哈马尔卡（今秘鲁北部）",state:"印加（塔万廷苏尤）、卡斯蒂利亚",sources:["（在场者与土著之两记）会战诸记与赎金之账","《卡哈马尔卡与印加之亡研究》"],tags:["伏击","征服"]},related:["world--1533--p01", "world--1521--m01"]},
  {id:"world--1532--m02",track:"world",year:1532,yearApprox:false,dim:"military",weight:3,"title":"苏莱曼再次围攻维也纳未成而订和","summary":"大军西进未遇会战，两个皇帝以条约讲和。",detail:{"background":"1529年的围攻未成，1532年苏莱曼带着大炮与辎重再次北进，查理五世亦聚诸侯军队于多瑙河。","process":"1532年5至8月两军在维也纳与格兰之间彼此寻战，土军取格兰而不攻维也纳，皇帝军队不敢冲其营垒；入秋订约回师。","impact":"此约使哈布斯堡守住地盘而每年纳贡，奥斯曼的威势在中欧维持二十多年；1541年土军再入布达并设行省。",figures:["苏莱曼一世","查理五世","（其帕夏）（无名）"],place:"格兰、维也纳一带",state:"奥斯曼帝国、奥地利与神圣罗马帝国",sources:["两军之记、1533年之约抄件与使报","《苏莱曼与查理五世之争研究》"],tags:["对峙","和约"]},related:["world--1529--m01", "world--1541--p01"]},
  {id:"world--1533--p01",track:"world",year:1533,yearApprox:false,dim:"politics",weight:3,"title":"亨利八世婚案与《限制上诉之令》","summary":"以国法断其婚姻，王权自任教会首领。",detail:{"background":"国王求与阿拉贡的卡塔琳娜离婚而娶布林家的女儿，罗马久不判决；1532年教士会议已自认英格兰教会不依赖外部权力。","process":"1533年3月《限制上诉之令》禁止向罗马上诉；克兰默于5月23日判决前婚无效，国王的新婚办成，9月7日伊丽莎白出生。","impact":"英格兰教产权此后归国王，罗马的税收与任命全行断绝；1536年起修道院财产入王室库藏，北方叛乱因此而起。",figures:["亨利八世","（其大主教）克兰默","（其妻）安妮·布林"],place:"伦敦、格林尼治",state:"英格兰王国",sources:["国会法案原文、克兰默判定之记录与诸使报","《亨利八世与改革之始研究》"],tags:["王权","婚姻"]},related:["world--1534--i01", "world--1527--m01"]},
  {id:"world--1534--c01",track:"world",year:1534,yearApprox:true,dim:"culture",weight:2,"title":"罗耀拉等七人发愿于蒙马特","summary":"以神贫贞洁结社，志往圣城与异域。",detail:{"background":"罗耀拉由军人改行，在巴黎与几位读书人同学，渐有结社、守产、赴耶路撒冷之议。","process":"1534年8月15日前后，罗耀拉与沙勿略、莱内尔等六七人于蒙马特小堂发神贫与贞洁的愿，并约定次年至威尼斯、前往圣城。","impact":"这个打算至1540年得教宗批准而成耶稣会；会士四出传教、办学并做王公之师，成为天主教方面反改革最大的力量。",figures:["依纳爵·罗耀拉","（其伴）沙勿略","（其伴）莱内尔"],place:"巴黎蒙马特",state:"法兰西王国、教廷影响之下",sources:["会史、诸会士自传与早期书札、《会宪》前文","《罗耀拉与耶稣会之始研究》"],tags:["修会","誓愿"]},related:["world--1540--i01", "world--1549--c01"]},
  {id:"world--1534--i01",track:"world",year:1534,yearApprox:false,dim:"institution",weight:4,"title":"英格兰《至尊令》：国王为教会首领","summary":"议会定此称号，拒宣誓者以叛国论处。",detail:{"background":"1533年法令已断上诉，王室更需一篇法律以定首领的称号；教士会议屈服，罗马绝罚亦至。","process":"1534年11月议会通过《至尊令》，认国王为这一教会与英格兰的最高首领，百姓须宣誓承认他，公然否认者以叛国罪论处。","impact":"以法律立政教合一之制自此始；1535年7月托马斯·莫尔以不肯宣誓被杀，1536年又并威尔士入其法律，王权与良心之争遂成诉讼案件。",figures:["亨利八世","（其谋主）克伦威尔","（拒誓者）托马斯·莫尔"],place:"伦敦西敏",state:"英格兰王国",sources:["《至尊令》原案、克伦威尔文件与当时审讯记","《都铎法制与至尊之誓研究》"],tags:["立法","教国一体"]},related:["world--1536--i01", "world--1535--f01"]},
  {id:"world--1535--f01",track:"world",year:1535,yearApprox:false,dim:"figure",weight:3,"title":"托马斯·莫尔以不肯宣誓伏法","summary":"前大法官沉默不答，塔丘刀落。",detail:{"background":"1534年《至尊令》要求宣誓承认国王为首领，莫尔认同其中的道理却顾虑自身名分，长期系于塔中、写书自遣。","process":"1535年7月1日受庭讯，他始终不肯明言此誓可遵与否；7月6日殁于塔丘，年纪五十七岁，其首与费舍尔主教之首同悬于桥上。","impact":"其死成为天主教方面殉道凭证（1886年封圣），亦为都铎以叛国法束住言论的例子；《乌托邦》的作者终死于本国法律之下。",figures:["托马斯·莫尔","（同死者）罗切斯特的费舍尔","亨利八世"],place:"伦敦塔",state:"英格兰王国",sources:["1535年审讯记录、（鲁多夫）书札与殉道者传诸本","《莫尔与至尊之誓研究》"],tags:["殉死","法制"]},related:["world--1534--i01", "world--1516--c01"]},
  {id:"world--1535--x01",track:"world",year:1535,yearApprox:false,dim:"explore",weight:2,"title":"卡蒂尔溯圣劳伦斯河至霍切拉加","summary":"两条船逆水行十日，抵山上的栅寨城。",detail:{"background":"1534年卡蒂尔已入其河口而西，1535年率三条船再到，土人引导逆水上行。","process":"1535年9至10月溯圣劳伦斯河抵上游的霍切拉加（今蒙特利尔之山），其地有栅栏围护的村庄与可耕之田，然急滩不可越过，只好返回。","impact":"此行成为法兰西占据圣劳伦斯流域的凭据，1608年建立魁北克即循此路；皮毛之路此后进入欧洲人的眼界。",figures:["雅克·卡蒂尔","（其导）多马古阿","（其报之主）弗朗索瓦一世"],place:"圣劳伦斯河、霍切拉加",state:"法兰西王国、圣劳伦斯与易洛魁诸部",sources:["卡蒂尔航纪诸本与王室账册、土人口述之转记","《卡蒂尔与加拿大之发见研究》"],tags:["探险","河路"]},related:["world--1497--x01", "world--1608--x01"]},
  {id:"world--1536--c01",track:"world",year:1536,yearApprox:false,dim:"culture",weight:4,"title":"加尔文《基督教要义》初版刊行","summary":"以六章立其体系，改革派自此有书。",detail:{"background":"加尔文自巴黎危难逃至巴塞尔，1535年书写成，为法兰西遭难的弟兄而作。","process":"1536年3月巴塞尔刊行初版六章（论律法、信经、祷文、圣事、人的自由与罗马的权力），篇幅短而辞气激烈，附录致法王书一封。","impact":"此书反复再版，至1559年扩为八十章，成为改革宗的标准神学；其预定论与教会制度自日内瓦北至苏格兰、南至荷兰。",figures:["约翰·加尔文","（其印者）（巴塞尔之书商）","（其上者）法王弗朗索瓦一世"],place:"巴塞尔",state:"瑞士诸城、法兰西之信徒",sources:["《基督教要义》1536年初版与1559年定本、加尔文书信集","《加尔文与其书之流传研究》"],tags:["神学","改革宗"]},related:["world--1541--p02", "world--1531--m01"]},
  {id:"world--1536--i01",track:"world",year:1536,yearApprox:false,dim:"institution",weight:3,"title":"威尔士并入英格兰令","summary":"威尔士诸郡行同一法，代表始入议会。",detail:{"background":"亨利八世想并入边地来统一法律，威尔士各边区的自立与领主诉讼久为王政之患。","process":"1536年《并入令》废除威尔士各边区的自立，分其地为郡、行英格兰法律与治安官，许其选代表入议会。","impact":"英格兰与威尔士此后同一法律同一制度，王室西境政务变简；语言与律俗的差异没有消亡，此制至十九世纪仍有争执。",figures:["亨利八世","（其主稿者）克伦威尔","（其受者）威尔士诸郡士绅"],place:"西敏、威尔士诸郡",state:"英格兰王国、威尔士",sources:["《并入令》原案与枢密院边郡之卷","《都铎并合威尔士研究》"],tags:["并合","郡制"]},related:["world--1534--i01", "world--1533--p01"]},
  {id:"world--1537--c01",track:"world",year:1537,yearApprox:true,dim:"culture",weight:3,"title":"《伟大事》诏论印第安人本性","summary":"教宗称这些人有理性，不当以奴隶待之。",detail:{"background":"征服者以土人为「自然之奴」，塞维利亚与萨拉曼卡的神学家争辩其当否，拉斯·卡萨斯屡次向朝廷上书。","process":"1537年（这道诏书的年月与传本尚有争论）保罗三世发出《伟大事》诏，谓印第安人乃具理性之人，当以讲道与榜样引其信仰，不得以军队与奴役胁迫。","impact":"此诏未能止住矿役与监护之实情，却为后世以人道论殖民者立一名目；1550年巴利亚多利德的辩论即循此问题而开。",figures:["（教宗）保罗三世","（其上书者）拉斯·卡萨斯","（其敌者）塞普尔维达"],place:"罗马",state:"教廷、西属印度",sources:["诏文之诸传本、拉斯·卡萨斯上书与萨拉曼卡之论","《印第安人之性与殖民法研究》"],tags:["人论","传教"]},related:["world--1512--i01", "world--1550--c01"]},
  {id:"world--1540--i01",track:"world",year:1540,yearApprox:false,dim:"institution",weight:4,"title":"教宗批准成立耶稣会","summary":"凭神贫、贞洁与赴异域之愿，结为越过国界之会。",detail:{"background":"罗耀拉与几位同伴自1537年起在罗马行医、讲教理，请求立会作为朝觐与听命之所。","process":"1540年9月27日教宗以诏书《为治理教会》批准其会，初限会士六十人，罗耀拉为首任会长；第二年取消人数的限制。","impact":"此会以办学、为王公神师与越洋传教为业，半个世纪内使欧洲大半土地重归罗马的宗教，且东入印度、日本与中国。",figures:["依纳爵·罗耀拉","（教宗）保罗三世","（其东行者）沙勿略"],place:"罗马",state:"教廷、耶稣会",sources:["1540年准会诏、《会宪》与罗耀拉书信、自传","《耶稣会之立与其初年研究》"],tags:["修会","教育"]},related:["world--1534--c01", "world--1549--c01"]},
  {id:"world--1541--p01",track:"world",year:1541,yearApprox:false,dim:"politics",weight:4,"title":"土军取布达，匈牙利中部为其行省","summary":"以平乱为名留兵，中部即为土人行省。",detail:{"background":"1526年以后匈牙利中部属约翰·扎波亚一党，他死了以后子嗣年幼，诸侯与哈布斯堡互相攻战不休。","process":"1541年8月苏莱曼进入布达，留其军队，借「定乱」的名义废约翰朝廷，设中部各郡为布达省，由土耳其帕夏治理。","impact":"匈牙利的三分自此定型（土、哈布斯堡与特兰西瓦尼亚），一百五十年之间，多瑙河中游成为两家用兵之地。",figures:["苏莱曼一世","（其幼主）约翰·西吉斯蒙德","（其母）伊斯贝拉"],place:"布达",state:"奥斯曼帝国、匈牙利、特兰西瓦尼亚",sources:["奥斯曼省制之卷、扎波亚宫廷与哈布斯堡记事","《布达省与匈牙利三分研究》"],tags:["设省","三分"]},related:["world--1526--m01", "world--1532--m02"]},
  {id:"world--1541--p02",track:"world",year:1541,yearApprox:false,dim:"politics",weight:3,"title":"加尔文回日内瓦，定下教仪制度","summary":"以四等职分与教务法庭定一城规矩。",detail:{"background":"1536年加尔文初在日内瓦立章程却行不下，遭驱逐后寓斯特拉斯堡五年。","process":"1541年9月他回应城中的邀请而返，重上《教会之制》：以牧师、博士、长老与执事四种职分治理教会，另设教务法庭考察风俗与信理。","impact":"日内瓦此后成为改革宗的样板与遭难者之城，其制度随苏格兰、荷兰与法兰西会众外传；讲经与印书亦成工具。",figures:["约翰·加尔文","（其敌党）（日内瓦之自由的党）","（其同事）（无名之牧师）"],place:"日内瓦",state:"日内瓦共和国",sources:["1541年《教会之制》与教务法庭之卷、法雷尔书札","《加尔文治下的日内瓦研究》"],tags:["教会制","城市"]},related:["world--1536--c01", "world--1553--c01"]},
  {id:"world--1541--x01",track:"world",year:1541,yearApprox:false,dim:"explore",weight:2,"title":"德索托军至密西西比河","summary":"自佛罗里达北行三年，抵大河而止。",detail:{"background":"1539年德索托率五百余人自哈瓦那登佛罗里达，寻内陆的城与金子。","process":"1541年5月他的队伍越过今美国东南而至巨河，命名圣灵河，土人聚船阻其渡河；逆水不能上，1542年5月德索托病死于河岸。","impact":"此为欧洲人首次深入密西西比流域的记录，记事亦北美内陆最早条目；余者1543年顺河出海而返，此地遂为西人口实。",figures:["埃尔南多·德·索托","（其继将）路易斯·德·莫斯孔索","（记其事者）所谓埃尔瓦斯绅士"],place:"佛罗里达、密西西比河",state:"卡斯蒂利亚、密西西比诸部",sources:["所谓埃尔瓦斯绅士之记事、1557年刊之诸记与王室文书","《德索托之役与北美东南研究》"],tags:["远征","大河"]},related:["world--1542--x01", "world--1521--m01"]},
  {id:"world--1542--x01",track:"world",year:1542,yearApprox:false,dim:"explore",weight:3,"title":"奥雷亚纳沿亚马孙河下行入海","summary":"自安第斯山以东顺水而下，数月乃至大洋。",detail:{"background":"奥雷亚纳与皮萨罗的弟弟逆阿科河上行，饥饿疲惫而返，遂舍山路改循水路，沿一条支流（后来叫纳波河）向东下行。","process":"1542年夏其船抵大河，与善战的「女族」相遇，遂以此河名亚马孙；8月下旬入大洋，绕特立尼达回西班牙，1544年到。","impact":"此行确定亚马孙有入海的口子与其水量之大，南美内陆此后见于欧洲人的地图；所说多夸，亦开此后一百年探河之役。",figures:["弗朗西斯科·德·奥雷亚纳","（其牧伴）卡巴尔纳","（其命之主）贡萨洛·皮萨罗"],place:"亚马孙河、安第斯山东麓",state:"卡斯蒂利亚、沿河诸土邦",sources:["奥雷亚纳航纪与卡巴尔纳之续记、贡萨洛之役记事","《亚马孙之发见史研究》"],tags:["大河","探险"]},related:["world--1541--x01", "world--1513--x01"]},
  {id:"world--1543--s01",track:"world",year:1543,yearApprox:false,dim:"science",weight:5,"title":"哥白尼《天体运行论》印成","summary":"徙太阳于近中心处，改地球位置，历算另立。",detail:{"background":"哥白尼自意大利归来，在弗龙堡积数十年观测与推算，谓地动之说可解历算家未明之处。","process":"1543年春纽伦堡刊行《天体运行论》六卷，徙太阳于近中心处，令地球与各行星绕之；那篇序言（并非作者本人同意）称此仅为便于推算的设定。","impact":"此后历算的难处不复专归于本轮；第谷、开普勒与伽利略皆循此书别立新说，宇宙图像因此两度改变。",figures:["尼古拉·哥白尼","（其刊者）雷蒂库斯","（其序者）奥西安德尔"],place:"纽伦堡、弗龙堡",state:"波兰王领之普鲁士、神圣罗马帝国",sources:["1543年原本与其改稿、雷蒂库《首说》","《哥白尼革命之形成研究》"],tags:["日心","历算"]},related:["world--1543--s02", "world--1551--s01"]},
  {id:"world--1543--s02",track:"world",year:1543,yearApprox:false,dim:"science",weight:4,"title":"维萨里《人体构造》刊于巴塞尔","summary":"以亲验尸首正盖伦之误，解剖自成一艺。",detail:{"background":"医家教学生仍以背诵古方为主，解剖以旧图为凭；维萨里在帕多瓦自验尸、自绘图，年纪二十八岁。","process":"1543年巴塞尔刊行《人体构造》七卷，对开本，木刻的图精妙（相传出其画坊），即以所验定骨、肉、脉之次序，纠正旧说百处失误。","impact":"此后解剖以动手验看为根本，学者亦上案台执刀；此书一版即卖完，1555年重订而稍微收敛了锋锐，然体例不再改动。",figures:["安德烈亚斯·维萨里","（其图工）（传为凡·卡尔卡尔）","（其师）（帕多瓦之旧医派）"],place:"巴塞尔、帕多瓦",state:"神圣罗马帝国、威尼斯领之帕多瓦",sources:["1543年原本与1555年二版、维萨里之校勘书","《维萨里与解剖学之新证研究》"],tags:["解剖","实证"]},related:["world--1543--s01", "world--1519--f01"]},
  {id:"world--1543--x01",track:"world",year:1543,yearApprox:true,dim:"explore",weight:2,"title":"葡萄牙船初至日本种子岛","summary":"一舟载火绳枪，欧洲人第一次出现在九州南边。",detail:{"background":"葡人东航已抵中国沿海，风暴与商路使其船偶至九州南边，当时日本的各家互相攻战。","process":"1543年（此年有1542、1544的不同说法）葡船至种子岛，船载火绳枪，岛主时尧购其器令匠人仿造；未过数年各家皆用之。","impact":"「铁炮」此后为日本各家所重，城战与合战之法因之而变；1549年沙勿略亦自葡人航路入鹿儿岛，欧洲与日本的商、教遂始。",figures:["（种子岛主）种子岛时尧","（其舟之葡商）（无名）","（记其事者）（日本军记之家）"],place:"种子岛（今日本九州南）",state:"日本诸家、葡萄牙「印度国家」",sources:["《铁炮记》与其后日本军记、葡国东航之报","《南蛮贸易与火器传入日本研究》"],tags:["火绳枪","初遇"]},related:["world--1549--c01", "world--1511--m01"]},
  {"id": "world--1545--e01", "track": "world", "year": 1545, "yearApprox": false, "dim": "economy", "weight": 5, "title": "波托西银矿始采", "summary": "一山出银，米塔役与汞齐法成全球流通。", "detail": {"background": "印加驿道旁有利托山（克丘瓦语叫「银峰」）。1545年4月一个土人牧人在山坡发现露天富矿，西属秘鲁殖民者遂弃高原旧城聚到这里。", "process": "1545年起矿主以「米塔」轮役制派安第斯村社丁夫下井，起初用熔炉炼；十六世纪后期改行汞齐法（1564年后万卡韦利卡的水银继至），山脚的炼池千百。这些银走两条路运出：一经利马、巴拿马至塞维利亚，一经阿卡普尔科至马尼拉。", "impact": "自1545年至十七世纪中叶，此山所出以万吨计（学界估计二万至四万余吨，模型不同而出入很大）。此银供西班牙兵费、换中国丝与瓷、助长欧洲物价，为早期全球贸易的血脉。", "figures": ["瓜尔帕·阿纳尔奎（土人牧者）", "（其矿之督府官）（无名）"], "place": "波托西（今玻利维亚西南高原）", "state": "西班牙印度（秘鲁总督区）、高原诸部", "sources": ["波托西矿籍与市政会议卷、1603年王室矿政之报", "《剑桥拉丁美洲史》第一卷、《波托西与安第斯之银》"], "tags": ["白银", "矿业", "米塔役"]}, "related": []},
  {"id": "world--1545--c01", "track": "world", "year": 1545, "yearApprox": false, "dim": "culture", "weight": 4, "title": "特伦托大公会议开幕", "summary": "以大公会议定信理并自整其弊，罗马的界线由此画出。", "detail": {"background": "路德难起二十多年，罗马早欲以一次公会议定信理并革弊端；法王与皇帝相持，会址乃选于帝国北境的特伦托。", "process": "1545年12月13日第一会期集于圣玛利亚大堂，到会主教起初仅三十多人；会期断续历三任教宗（保罗三世、儒略三世、庇护四世），至1563年12月4日方毕，定下有关信理与改革的法令数百条。", "impact": "此会判定圣事七品、圣经与圣传并行、变体之说，以「唯信称义」为非，又命造修院、教区册籍、主教须住本教区；天主教方面的学与界自此定，此后三百年的教政皆循此轨。", "figures": ["（教宗）保罗三世", "（其会之使）山托利奥", "（与会者）波尔扎"], "place": "特伦托（今意大利北部）", "state": "教廷、神圣罗马帝国诸邦", "sources": ["《特伦托公会会典》之决议与法度文本、会议记录", "《剑桥近代早期欧洲史》反改革诸章"], "tags": ["公会议", "反改革"]}, "related": []},
  {"id": "world--1545--d01", "track": "world", "year": 1545, "yearApprox": false, "dim": "disaster", "weight": 3, "title": "新西班牙「恶疾」大疫", "summary": "谷地复有大疫，高热出血死者不绝。", "detail": {"background": "墨西哥谷地自1520年天花之后，麻疹与伤寒灾累不断。1545年起高地又起一种待考的疫，土人谓之「科科利茨特利」（恶疾）。", "process": "此疫以1545至1548年最重，谷地与米却肯各处皆有。病状为高热、黄疸与口鼻出血。修道院与王室的报告皆称街上尸首相枕、田地无人垦，医家放血诸法不见效。近年有人测古人骨的基因，谓其或属沙门氏菌一类，此说今仍有争论。", "impact": "这一期死者学界估计自二百万到一千五百万不等，数目依模型出入甚大，遂无定说；谷地土邦的赋役、祭司与书图传承因此更衰，役民之制日益依靠非洲奴隶。", "figures": ["（记疫者）托尔迪斯塔", "（其时医者）（无名）"], "place": "墨西哥谷地（今墨西哥中部高原）", "state": "新西班牙（墨西加故地诸土邦）", "sources": ["托尔迪斯塔《印度事物志》与王室档案之疫报", "《新世界之疫与人口崩溃研究》、近年古人骨基因之测"], "tags": ["瘟疫", "人口崩溃"]}, "related": []},
  {"id": "world--1546--f01", "track": "world", "year": 1546, "yearApprox": false, "dim": "figure", "weight": 2, "title": "路德卒于艾斯莱本", "summary": "六十三岁卒于生处，葬座堂讲台之下。", "detail": {"background": "路德晚年与诸侯、再洗礼派及教宗三面相争，家业与讲席皆在维滕贝格；1546年冬应曼斯菲尔德诸伯之请，往解其兄弟诉讼。", "process": "1546年2月18日清晨卒于生处艾斯莱本，六十三岁；2月22日葬于维滕贝格座堂讲台之下。他1544年自撰的拉丁墓碑尚存。死前几天仍论经不绝，遗书中自称一生「客居他人之田」。", "impact": "其死不到一年，皇帝即带兵入德意志。路德的教不因一人存亡而改，赖德文新约（1522、1534）、大小教理问与德语唱圣诗的制度行于诸侯之家，1555年和约遂承认其教。", "figures": ["马丁·路德", "（其妻）卡塔琳娜·冯·博拉", "（其继者）梅兰希顿"], "place": "艾斯莱本、维滕贝格", "state": "萨克森选侯国以下诸路德邦", "sources": ["1546年死所之记事与维滕贝格丧葬之文", "路德《桌谈》与书信集、《路德传》通行本"], "tags": ["人物", "路德宗"]}, "related": []},
  {"id": "world--1547--p01", "track": "world", "year": 1547, "yearApprox": false, "dim": "politics", "weight": 4, "title": "伊凡四世加冕为沙皇", "summary": "莫斯科大君改称凯撒，自定其国典礼。", "detail": {"background": "莫斯科的君主久称大君；伊凡三岁丧父、1533年继位而由两家贵族摄政，至1547年春自行此礼。", "process": "1547年1月16日他在克里姆林圣母升天座堂加冕，都主教马卡里行礼，称号为「沙皇与全罗斯之主」。同年六月莫斯科大火，民怨归于后族，1549年召集「精会议」、定新律书与衙门的制度。", "impact": "此号使莫斯科君主上接1453年以前之罗马，「第三罗马」的自负遂成定制；1552年取喀山、1556年取阿斯特拉罕与1580年代东向之役，皆用新定的沙皇名义号令。", "figures": ["伊凡四世（雷帝）", "（行礼之都主教）马卡里", "（其劝者）西尔维斯特"], "place": "莫斯科克里姆林", "state": "俄罗斯沙皇国", "sources": ["1547年加冕之礼仪书与1549年律书、罗斯诸编年", "《伊凡四世与俄国制度之变研究》"], "tags": ["加冕", "沙号"]}, "related": []},
  {"id": "world--1547--m01", "track": "world", "year": 1547, "yearApprox": false, "dim": "military", "weight": 3, "title": "米尔贝格之战：诸侯军溃败", "summary": "一日破联盟人众，擒选侯于阵地。", "detail": {"background": "施马尔卡尔登联盟与皇帝在信仰及帝国法庭之事上相持数年；1546年秋皇帝与巴伐利亚之兵北来，联盟各军分驻而不能合。", "process": "1547年4月24日战于易北河之米尔贝格（今萨克森境）：萨克森选侯的骑兵先冲击对方辎重，反为人趁势掩杀，黑森伯人众随之溃败；选侯约翰·弗里德里希被擒，腓力出逃。", "impact": "皇帝乘胜强行颁下《临时敕令》，而法王的援助与诸侯抗命未停，1552年对方军队再起，皇帝几乎不免。此役为皇帝最后一次以大兵定德意志之宗教，1555年不得不与对方共立一法。", "figures": ["查理五世", "（被擒者）萨克森的约翰·弗里德里希", "（其盟）黑森的腓力"], "place": "米尔贝格（今萨克森，易北河畔）", "state": "神圣罗马帝国、施马尔卡尔登联盟", "sources": ["皇帝之战报、当时诸邦书报与编年", "《施马尔卡尔登战争与帝国之局研究》"], "tags": ["会战", "宗教战争"]}, "related": []},
  {"id": "world--1548--i01", "track": "world", "year": 1548, "yearApprox": false, "dim": "institution", "weight": 2, "title": "《临时敕令》与马格德堡抗拒", "summary": "皇帝以会战定两个教派，一城抗命不受。", "detail": {"background": "米尔贝格取胜之后，皇帝欲以一时敕令止争论，1548年在奥格斯堡颁「临时」敕令，谓公会议未集之前一律照其判断而行。", "process": "1548年5月（十二月增订）的敕令许教士娶妻、暂任圣餐两形，其余礼制悉归旧教会，并还部分教产。马格德堡首先抗拒，1550年刊《论真教理之辩护》，称「当顺神不顺人」，许下级官抗拒上位。", "impact": "这道敕令反使「抗辩之权」成为路德宗的一条学理，马格德堡此后为新教抗命之城；其令终未行于各邦，1555年和约便是它实际作废的凭据。", "figures": ["查理五世", "（拒命者）马格德堡诸牧师", "（其敌）萨克森的莫里茨"], "place": "奥格斯堡、马格德堡", "state": "神圣罗马帝国诸邦", "sources": ["《临时敕令》文本与马格德堡《辩护》1550年印本", "《帝国敕令与抗辩说之起源研究》"], "tags": ["敕令", "抗辩"]}, "related": []},
  {"id": "world--1549--c01", "track": "world", "year": 1549, "yearApprox": false, "dim": "culture", "weight": 3, "title": "沙勿略入鹿儿岛传教", "summary": "一舟自果阿北来，日本始有天主之说。", "detail": {"background": "耶稣会凭1540年的批准东行，沙勿略自果阿经马六甲与安博纳；1547年于马六甲遇日本人弥次郎，闻其乡土可设坛讲道，遂决北行。", "process": "1549年8月15日他同弥次郎等三人入鹿儿岛（岛津氏的领地），赖译语人讲教、为病者施洗。他在信中说到此教法渐入大友、山口之地，又叹佛像与「自然之教」不能遽破，须凭书籍与学者辩论胜过它。", "impact": "日本的天主教自此有堂与信众（1579年的报告估计信者数万，数目未必可核）。其后有天正遣欧使（1582）与「伴天连之逐」；丰臣、德川两次禁教后，此信仰以「隐密」的名义存至十九世纪。", "figures": ["方济各·沙勿略", "（其导）弥次郎（安日禄）", "（其报之主）罗耀拉"], "place": "鹿儿岛（今日本九州南）", "state": "日本诸家（岛津氏领）、耶稣会日本传教区", "sources": ["沙勿略1549至1552年诸书信、日本方《十字圣号之记》", "《耶稣会在日本与中国研究》"], "tags": ["传教", "日本"]}, "related": []},
  {"id": "world--1550--a01", "track": "world", "year": 1550, "yearApprox": false, "dim": "art", "weight": 3, "title": "瓦萨里《艺苑名人传》刊行", "summary": "以三个时期叙名人，定艺术史格局，文艺复兴始有条目。", "detail": {"background": "瓦萨里在佛罗伦萨从事艺术、为美第奇家管事，久辑前辈行事与作品目录，并以亲见亲闻补其缺漏。", "process": "1550年刊行《最杰出之画家、雕刻家与建筑师传》两卷，自契马布埃叙至米开朗琪罗，分三个时期讲艺术的渐进；1568年重订增入「现代」部分，并及同时艺者与少数女艺者。", "impact": "此书定下「用名人与分期来写艺术史」的格式，后世所谓「文艺复兴」的史纲实承其格局；米开朗琪罗与达·芬奇轶事多赖以录，其以佛罗伦萨为中枢之见亦为今人所争。", "figures": ["乔尔乔·瓦萨里", "（其所传者）米开朗琪罗", "（其护者）科西莫·德·美第奇"], "place": "佛罗伦萨", "state": "佛罗伦萨公国（美第奇家）", "sources": ["《艺苑名人传》1550年与1568年两版原本", "《瓦萨里与艺史体裁研究》"], "tags": ["艺史", "传记"]}, "related": []},
  {"id": "world--1550--c01", "track": "world", "year": 1550, "yearApprox": false, "dim": "culture", "weight": 2, "title": "巴利亚多利德辩论", "summary": "以亚里士多德与教诏互诘，判断久而无成。", "detail": {"background": "1549年拉斯·卡萨斯入朝廷，请以神学与法律止秘鲁的役使；塞普尔维达1547年撰《论正义之战争》（1550年呈上），谓土人生而为奴、当以武力使之服从。", "process": "1550年8月起，奉命审员在巴利亚多利德会议，两造据「自然之奴」一章、1537年《伟大事》诏与征服实情互相质问；1551年移塞哥维亚再辩，此次审问未下判。", "impact": "此辩虽无成说，而「用人理来断征服该不该」自此为西属印度的常问；1542年新律、1573年征伐令与保护官之设，皆承其一半议论。", "figures": ["（多明我会士）拉斯·卡萨斯", "塞普尔维达", "（其审员）（无名之法学家）"], "place": "巴利亚多利德、塞哥维亚", "state": "卡斯蒂利亚王国、西属印度", "sources": ["塞普尔维达《论正义之战争》、拉斯·卡萨斯《辩论》之辑本", "《萨拉曼卡学派与印度人之权利研究》"], "tags": ["辩论", "殖民法"]}, "related": []},
  {"id": "world--1551--s01", "track": "world", "year": 1551, "yearApprox": false, "dim": "science", "weight": 3, "title": "《普鲁士天文表》刊行", "summary": "哥白尼学说始有可用数字，历算家得新表。", "detail": {"background": "哥白尼1543年的书虽已刊行而数字未备，欲用其法者先苦无表；学生雷蒂库斯在莱比锡传其算法，维滕贝格的莱因霍尔德（佩尔巴赫）整理编定。", "process": "1551年（序言署此年正月）维滕贝格刊《普鲁士表》三十四开，日、月与五颗行星的经纬毕具，附用表之法则；其算法未尽去本轮，而日心之设定自此可推、可测、可教。", "impact": "此表在欧洲行用八十多年，为第谷、开普勒实测的靶子：两人之学皆自校此表之误起步。历算家此后不能专守托勒密旧说，日心说由书斋转入算盘。", "figures": ["埃拉斯穆斯·莱因霍尔德", "尼古拉·哥白尼", "（其传之者）雷蒂库斯"], "place": "维滕贝格、莱比锡", "state": "萨克森选侯国、神圣罗马帝国", "sources": ["1551年《普鲁士表》原本与其序、后世诸印本", "《哥白尼后历算之流传研究》"], "tags": ["历算", "日心"]}, "related": []},
  {"id": "world--1552--m01", "track": "world", "year": 1552, "yearApprox": false, "dim": "military", "weight": 4, "title": "俄军攻破喀山汗国", "summary": "筑堡垒绝援兵，以炮轰塌城墙，伏尔加中游归俄国。", "detail": {"background": "喀山汗国据伏尔加中游，屡侵莫斯科的边境；1545、1547、1549年三次征讨皆不成，1552年夏沙皇以大军与水陆转运并进，围其城。", "process": "1552年8月起围喀山：筑营垒绝其援兵与粮食，造攻城炮与坑道，并移营寨于城后。10月2日内城破，末汗叶迪格尔·穆罕默德被擒，清真寺与市集多焚，居民遭屠者甚众。", "impact": "伏尔加中游自此入俄，鞑靼各部相继为藩属。这片地方遂为1556年取阿斯特拉罕与1580年代入西伯利亚的门户；俄有这两个汗国的故地之后，遂兼跨欧亚。", "figures": ["伊凡四世", "（末汗）叶迪格尔·穆罕默德", "（其军之砲工）（无名）"], "place": "喀山（今俄罗斯鞑靼斯坦）", "state": "俄罗斯沙皇国、喀山汗国", "sources": ["十六世纪俄文《喀山之史》辑本与沙皇军报、喀山方之纪", "《喀山汗国与俄国东向研究》"], "tags": ["攻城", "东扩"]}, "related": []},
  {"id": "world--1553--c01", "track": "world", "year": 1553, "yearApprox": false, "dim": "culture", "weight": 3, "title": "塞尔维特焚于尚佩尔", "summary": "以反三位一体触法，官家焚之于日内瓦。", "detail": {"background": "西班牙人塞尔维特刊《基督教的恢复》（1553年初，里昂），谓三位一体与婴孩洗礼皆非圣经道理，又论灵魂与血气。其时加尔文方设教务法庭于日内瓦，两派相激。", "process": "1553年2月维也纳印所被人告发，8月逃进日内瓦，被认出拿住；10月27日焚于尚佩尔，书与其像同焚。贝尔斯与卡斯特利奥1554年刊《论异端者》，批评此事。", "impact": "此火令「用官刑处信理的罪」于改革宗内部起大讼：卡斯特利奥之议为后来良心自由说之引子，日内瓦「样板之城」之名从此受损。", "figures": ["米格尔·塞尔维特", "约翰·加尔文", "（其争者）卡斯特利奥"], "place": "日内瓦（尚佩尔）", "state": "日内瓦共和国、萨伏依边境", "sources": ["1553年审讯卷与处刑之记、加尔文之答辩、卡斯特利奥《论异端者》", "《塞尔维特与良心自由之讼研究》"], "tags": ["火刑", "良心"]}, "related": []},
  {"id": "world--1555--p01", "track": "world", "year": 1555, "yearApprox": false, "dim": "politics", "weight": 5, "title": "奥格斯堡宗教和约", "summary": "以「教随国定」认两个教并存，帝国统一告终。", "detail": {"background": "1552年新教诸侯联法王亨利二世用兵逼皇帝，因斯布鲁克之约暂许其请求；皇帝连年对法与土用兵，德意志的教争不能再以气力来定。", "process": "1555年9月25日帝国会议于奥格斯堡定下和约：承认奉《奥格斯堡信纲》之教为合法，诸侯各定其邦之教、百姓跟从君主；1552年后的教产听凭现状，只有教会领邦领主改教须让位（「声明限制」）。", "impact": "此为西方教会分裂的法律承认，帝国宗教统一之念遂告终结；「谁统治即谁的宗教」为一邦主权之种，而教会领邦与教产之争又埋下百年乱源，直到1648年两教并立。", "figures": ["查理五世", "（其弟主持者）费尔迪南德", "（诸侯之主）萨克森的莫里茨"], "place": "奥格斯堡", "state": "神圣罗马帝国诸邦", "sources": ["1555年《奥格斯堡和约》会议决议文本与其后执行之卷", "《剑桥近代早期欧洲史》帝国诸章"], "tags": ["和约", "教随国定"]}, "related": []},
  {"id": "world--1555--p02", "track": "world", "year": 1555, "yearApprox": false, "dim": "politics", "weight": 2, "title": "阿马西亚和约定土波分界", "summary": "两个帝国第一次以条约划分边界，麦加之路许与波斯。", "detail": {"background": "1514年恰尔迪兰后两国相攻四十多年：苏莱曼三次征波斯、取大不里士与巴格达（1534），萨法维则扰其在安纳托利亚后方。", "process": "1555年五六月间（约的月日各记稍异）于阿马西亚订约：奥斯曼得两伊拉客与巴格达之地，萨法维守住阿塞拜疆与高原，麦加朝路许与波斯人；此线与今天土耳其—伊朗的边界差不多。", "impact": "此为两个帝国第一次以文字定界，此后约二十年不再大举用兵；萨法维遂得专心对付东边（乌兹别克与坎达哈尔），奥斯曼的西线也因此松缓。", "figures": ["苏莱曼一世", "（萨法维沙阿）塔赫玛斯普一世", "（其议约者）（无名之贝勒贝伊）"], "place": "阿马西亚（今安纳托利亚北）", "state": "奥斯曼帝国、萨法维波斯", "sources": ["约本之两方抄件、奥斯曼卷宗与波斯编年", "《土波之争与两帝国之界研究》"], "tags": ["和约", "两帝国"]}, "related": []},
  {"id": "world--1556--d01", "track": "world", "year": 1556, "yearApprox": false, "dim": "disaster", "weight": 4, "title": "嘉靖关中大地震", "summary": "除夕前后陕西山西地裂，死者数目各记悬殊。", "detail": {"background": "山西、陕西高原东缘一向多地震；嘉靖三十四年十二月夜，华县、渭南一带山崩泉涌，陵谷改换，住窑洞的百姓受害最重。", "process": "1556年1月23日（嘉靖三十四年十二月壬寅）夜地震，震中在今天陕西渭南—华县一带。陕西、山西、河南数百县皆报城郭、官署、学宫与渠堰毁坏。当时正腊月严寒，尸首埋不了，冻饿接着而来。", "impact": "《明实录》与各州县志所记死者数目互相出入（一说八十三万，今天学界估为数十万级，说法至今不一），是有史以来死亡最多的地震之一；此后窑居与城筑之制、赈济与蠲免之议屡次有人陈说。", "figures": ["（其时之君）明世宗（嘉靖）", "（记灾之官）（无名之巡按御史）"], "place": "陕西渭南、华县一带（今关中东部）", "state": "明（陕西、山西等省）", "sources": ["《明实录·嘉靖朝》、嘉靖《陕西通志》与诸州县志", "《中国历史地震图集》、《中国强地震目录》之今定"], "tags": ["地震", "明代灾荒"]}, "related": ["cn--1556--d01"]},
  {"id": "world--1556--m01", "track": "world", "year": 1556, "yearApprox": false, "dim": "military", "weight": 4, "title": "第二次帕尼帕特之战", "summary": "象倒而军乱，九岁莫卧儿皇帝复位。", "detail": {"background": "胡马雍1554年重得德里，1556年1月坠阶而死。子阿克巴才九岁，比拉姆·汗摄政。喜穆（赫穆）带阿富汗各部的众人东取阿格拉与德里，自称「维克拉马吉特」。", "process": "1556年11月5日两军于帕尼帕特开战：喜穆用战象与步队当前锋，一头象中弹发狂、反践己阵。比拉姆·汗骑兵自两翼合击并射其象舆，人众溃散，喜穆在巴罗哈野外被擒，不久斩于德里门前。", "impact": "此战定莫卧儿在恒河—亚穆纳河平原之基，阿克巴四十年基业从此而始；拉杰普特诸邦与阿富汗首领相继落进其势力范围，北印度重新归一个官府。", "figures": ["（莫卧儿摄政）比拉姆·汗", "（幼主）阿克巴", "（其敌）赫穆（喜穆）"], "place": "帕尼帕特（今印度哈里亚纳）", "state": "莫卧儿帝国、赫穆之阿富汗联盟", "sources": ["《阿克巴本纪》与比拉姆一方之纪、当时波斯文之报", "《莫卧儿建国与拉杰普特之盟研究》"], "tags": ["会战", "摄政"]}, "related": []},
  {"id": "world--1556--p01", "track": "world", "year": 1556, "yearApprox": false, "dim": "politics", "weight": 3, "title": "查理五世逊位，两哈布斯堡分家", "summary": "历数月让尽各块领地，奥西两支自此分为二。", "detail": {"background": "皇帝自1554年起因病体和三个方向的战事（法、土、德意志）不济，屡次议论退隐；子腓力长年在尼德兰与西班牙代行其事。", "process": "自1555年10月25日至1556年1月、9月历次逊位：尼德兰与弗朗什孔泰、西班牙连同海外领地与南意大利归腓力二世；奥地利各领与帝冠的实际权力归弟费尔迪南德。1558年2月退居尤斯特修道院，9月21日去世。", "impact": "哈布斯堡自此分为西班牙与奥地利两支，「一王之天下过广」之叹化为分治之制。西属美洲银与尼德兰税同供一库而常不足兵费，其后八十年叛乱与1588年舰队的费用都伏于此。", "figures": ["查理五世", "（其子）腓力二世", "（其弟）费尔迪南德一世"], "place": "布鲁塞尔、尤斯特（今西班牙）", "state": "西班牙、尼德兰、奥地利哈布斯堡", "sources": ["逊位之诏与金羊毛议事会之纪、1556至1558年书札", "《查理五世退位与两哈布斯堡研究》"], "tags": ["逊位", "分家"]}, "related": []},
  {"id": "world--1557--i01", "track": "world", "year": 1557, "yearApprox": false, "dim": "institution", "weight": 3, "title": "葡人定驻澳门并设议事会", "summary": "岁纳租银自治，欧洲久驻中华自此始。", "detail": {"background": "葡商自十五世纪末进中国南头、浪白各澳晒货，1553、1554年得以进濠镜澳；那地方水深可泊船、离香山不远，遂有久驻的打算。", "process": "1557年前后（学界以其入居定在1530至1570年间，定驻多取1557）葡人于当地设「议事会」自治，每年向香山县交地租银五百两，刑名由华官与其会两头分管。果阿—澳门之线既成，日本的银与生丝也聚这里。", "impact": "此为欧洲在华最早的永久据点，明朝以租银与县官羁縻而不派流官来治；此后二百多年，澳门为丝—银—茶之缝，亦传教、印书与历法入中国之口。", "figures": ["（议事会之长）（无名之葡商）", "（其地官）香山县知县", "（其后入澳者）利玛窦"], "place": "濠镜澳（今澳门）", "state": "明（广东）、葡萄牙「印度国家」之商驻", "sources": ["香山县租银之档与《澳门纪略》、葡国议事会之录", "《澳门与明清之际的海路研究》"], "tags": ["商驻", "澳门"]}, "related": ["cn--1557--p01"]},
  {"id": "world--1557--e01", "track": "world", "year": 1557, "yearApprox": false, "dim": "economy", "weight": 2, "title": "西班牙王室初次停付", "summary": "新银未至而兵费不解，债家受其拖延。", "detail": {"background": "皇帝与西班牙的兵费自1520年代起专靠德意志债；波托西银刚到，尼德兰、法国边境与土海战事不解，库藏常空。", "process": "1557年11月到1558年，王室以「停付」令债家的钱延迟偿还（奥格斯堡的富格与热那亚各家一同受累），并整顿币制，定佛兰德银钱则例；不久1560年又停付一次。", "impact": "1557、1560、1575、1596年几度停付，西班牙国王利息滚起而信用失，热那亚与佛罗伦萨商人遂代富格掌其汇兑；尼德兰起事与1588年舰队的费用，源头都伏在这类不足里。", "figures": ["腓力二世", "（其债家）富格之家", "（其代者）热那亚之银行家"], "place": "马德里、布鲁塞尔、奥格斯堡", "state": "西班牙王国、尼德兰", "sources": ["王室停付之诏与债案卷、富格账房文书", "《西属帝国之债与热那亚之金研究》"], "tags": ["王室债", "币制"]}, "related": []},
  {"id": "world--1559--p01", "track": "world", "year": 1559, "yearApprox": false, "dim": "politics", "weight": 3, "title": "卡托—康布雷齐和约签订", "summary": "六十五年意大利战争至此收束，意属归西班牙，法国陷内乱。", "detail": {"background": "自1494年以来意大利诸邦轮番做法、西两国的争场；1556年两哈布斯堡分家后，法王亨利二世连攻其佛兰德与意大利境内，两边库藏俱空。", "process": "1559年4月3日法、西于卡托与康布雷齐之间订约：法国交还萨伏依与勃里萨克等地，承认意属诸邦封地归西班牙王，放弃其在意大利的几个据点。和约刚成，亨利二世六月末比武中枪、7月10日死。", "impact": "此约为意大利战争六十五年之终局：西班牙在半岛与弗朗什孔泰的支配已定，驻军费反成尼德兰重负；法国则以国王死、两教嫌隙，重陷三十多年内战。", "figures": ["亨利二世", "腓力二世", "（其受益者）萨瓦的埃马努埃莱·菲利贝托"], "place": "卡托、康布雷齐（今法属埃诺边境）", "state": "法兰西王国、西班牙", "sources": ["约本之两国原本与1559年会议之纪、当时使报", "《剑桥近代早期欧洲史》意大利战争诸章"], "tags": ["和约", "意大利战争"]}, "related": []},
  {"id": "world--1559--i01", "track": "world", "year": 1559, "yearApprox": false, "dim": "institution", "weight": 2, "title": "保罗四世刊《禁书目录》", "summary": "印本书愈行愈广，罗马乃以目录禁之。", "detail": {"background": "1555年以来异端审问与书籍检查渐严，威尼斯1547年已有当禁书目；坎帕尼亚出身的教宗保罗四世以严刻自任，其时印本流传一天广似一天。", "process": "1559年3月刊行《保禄目录》，列出当禁的书与其作者（含伊拉斯谟各本、薄伽丘和几种国语圣经的译本），并定下印书须先经检阅之规，由罗马官掌管此目录。", "impact": "书籍检查从此成为通行的制度，意、西、尼德兰印坊皆受其约束；1564年《特伦托目录》稍宽而规矩不改，禁书目录与奉行之官吏延至十八世纪。", "figures": ["（教宗）保罗四世", "（被列者）伊拉斯谟", "（掌其目者）（罗马之校书官）"], "place": "罗马", "state": "教廷、意大利诸城", "sources": ["1559年《保禄目录》原本与1564年《特伦托目录》之校、威尼斯1549年目录", "《早期印刷、书检与禁目研究》"], "tags": ["书检", "印刷"]}, "related": []},
  {"id": "world--1560--i01", "track": "world", "year": 1560, "yearApprox": false, "dim": "institution", "weight": 3, "title": "果阿设立宗教裁判所", "summary": "欧洲审判机构移到亚洲，果阿新设裁判官。", "detail": {"background": "葡属印度旧教徒、新受洗者与欧人杂处，果阿主教与耶稣会屡请派裁判官吏察其「背教」之事；1557、1559年的请求至此时获准。", "process": "1560年果阿宗教裁判所成立，审问新受洗的印度人、犹太裔与当地欧人，按其家祭、饮食与婚俗定「异端」；罪重者于「信仪」之礼中公开处刑，案卷一年年积在果阿官署。", "impact": "此机构一直行到1812年，为欧洲审判制度于亚洲最久的一次移植；果阿旧礼社群与清真寺因此流散，案卷于今为研究葡属社会最重要的文书。", "figures": ["（其请设者）（果阿之会长）", "（其时之葡王）塞巴斯蒂安", "（其首任裁判官）（无名之托钵修士）"], "place": "果阿（今印度西岸）", "state": "葡萄牙「印度国家」及果阿诸社群", "sources": ["果阿裁判所之案卷与十六世纪末「信仪」之记录、耶稣会书信", "《葡属果阿宗教裁判所与社会研究》"], "tags": ["裁判所", "殖民社会"]}, "related": []},
  {"id": "world--1562--p01", "track": "world", "year": 1562, "yearApprox": false, "dim": "politics", "weight": 3, "title": "瓦西屠杀：法国首次内战", "summary": "一城聚会遭士兵屠杀，八次内战自此起。", "detail": {"background": "1559年以后法国朝廷由摄政与吉斯一家主持教政，加尔文宗的会众渐遍布南北；1561年圣日耳曼会议、1562年1月《一月诏书》暂许其在城外聚礼。", "process": "1562年3月1日吉斯之兵在瓦西（今香槟）杀做礼拜的新教徒几十人，两边相继起兵：吉斯结西班牙，孔代一支招德意志骑兵，又借英吉利奥港。法兰西第一次宗教战争开始。", "impact": "自1562至1598年法国共八次用兵；此乱以圣巴托罗缪的屠杀（1572）最惨，赖《南特敕令》（1598）暂得平息，两教城镇与教产之讼久为王权之累。", "figures": ["吉斯公爵弗朗索瓦", "（其敌）孔代亲王路易", "（摄政）凯瑟琳·德·美第奇"], "place": "瓦西（今法国香槟）", "state": "法兰西王国", "sources": ["瓦西之事之两造纪载、1562年王室诏书与当时书报", "《法兰西宗教战争与瓦卢瓦之末研究》"], "tags": ["宗教战争", "法兰西"]}, "related": []},
  {"id": "world--1563--c01", "track": "world", "year": 1563, "yearApprox": false, "dim": "culture", "weight": 2, "title": "特伦托公会闭会", "summary": "十八年三次集会乃毕，信理与纪律两条轨道俱定。", "detail": {"background": "公会历十八年、三次集议（1545、1551、1562），末期法国与西班牙的主教力争会议自主，与教使权力相持不下。", "process": "1563年12月4日于圣玛利亚大堂诵谢恩之词而散会。最后几次会期定下经书修订、修院训育格式、婚礼仪式与讲道之责，决议由1564年的诏书强行令各邦天主教会通行。", "impact": "信理与纪律两条轨道自此俱备，天主教的教育、讲道与书籍检查循此而行。所谓「特伦托的教会」成其体制，弥撒经书与要理行了三百多年，到二十世纪改动之后才变。", "figures": ["（教宗）庇护四世", "（末期主持）冈扎加", "（与会之记）（其史家）帕莱奥蒂"], "place": "特伦托（今意大利北部）", "state": "教廷、意西法诸国主教", "sources": ["1562至1563年会期记录与决议文本、1564年颁行之诏", "《特伦托公会与近代天主教会之形成研究》"], "tags": ["公会议", "礼书"]}, "related": []},
  {"id": "world--1564--f01", "track": "world", "year": 1564, "yearApprox": false, "dim": "figure", "weight": 3, "title": "加尔文卒于日内瓦", "summary": "遗命不立碑，其学问制度遍及西北欧。", "detail": {"background": "加尔文自1541年回日内瓦，以讲经、著述与教务法庭察一城的风俗信理；与城里执事诸家诉讼经年，与伯尔尼的边界议论亦久不决。", "process": "1564年5月27日他死在日内瓦，遗命不立碑、葬于公共坟地。他的讲章赖速记传下（讲经之日学者围听抄录），书信一千多通与《基督教要义》1559年定本为后学所守。", "impact": "他死后改革宗无主而愈广：法国的会众、尼德兰、苏格兰（1647年信纲本其例）、波兰与匈牙利诸会皆循其制度与学问。「加尔文主义」之名遂为其学之称，反抗君主之说亦从此而出。", "figures": ["约翰·加尔文", "（其继者）贝扎", "（其敌）（日内瓦执事之党）"], "place": "日内瓦", "state": "日内瓦共和国、欧洲诸改革宗教会", "sources": ["1564年死事之纪、贝扎所撰其传、加尔文书信集", "《加尔文与改革宗之流传研究》"], "tags": ["人物", "改革宗"]}, "related": []},
  {"id": "world--1565--e01", "track": "world", "year": 1565, "yearApprox": false, "dim": "economy", "weight": 5, "title": "大帆船东归之路始成", "summary": "顺海潮北行再东渡，太平洋的岁航自此可常行。", "detail": {"background": "1565年4月黎牙实比取宿务，永据其岛，而自亚洲东归美洲海路一直没寻着（1542年比利亚洛博斯西航不返），新西班牙总督府每年为这件事的粮饷叫苦。", "process": "1565年6至10月奥古斯丁会士乌尔达内塔与埃斯皮诺萨顺黑潮北行再东向，抵阿卡普尔科并以此航路报回。自1568年起每年用一、两条船载中国的丝瓷与香料东运，美洲与日本的银西进马尼拉。", "impact": "太平洋从此有常年航路，「返航之道」联环球为一环：美洲银换亚洲货，此银又为明中叶以后「折银于役」的来路。学界多合此线与日本、印度之线而观，谓大交换至此始成双向。", "figures": ["安德烈斯·德·乌尔达内塔", "（其命者）腓力二世", "（征菲之帅）黎牙实比"], "place": "马尼拉—阿卡普尔科（太平洋航线）", "state": "新西班牙、西属菲律宾、明（漳泉之商）", "sources": ["乌尔达内塔之航纪与1560年代王室令旨、马尼拉关课之档", "《马尼拉帆船与太平洋之白银》、《剑桥拉丁美洲史》"], "tags": ["白银", "太平洋航路", "大交换"]}, "related": []},
  {"id": "world--1565--m01", "track": "world", "year": 1565, "yearApprox": false, "dim": "military", "weight": 3, "title": "马耳他之围", "summary": "两个月连攻而岛不下，西方海上锋锐遂止。", "detail": {"background": "1530年骑士团得马耳他为藩地，其船屡扰北非与希腊的商船。苏莱曼恨老团长瓦莱特，1565年春以大艘战船北来。", "process": "1565年5月18日至9月8日围攻圣埃尔莫堡与比尔古：炮台、地道与「火环」连攻，守方几百名欧兵与本地人守御伤亡过半，圣埃尔莫失守。西西里的西班牙兵登岛，围始解，土军载尸而归。", "impact": "此为奥斯曼在西地中海推进最前沿的止处，骑士团与西班牙威望大涨。围事记述传遍意、西，成反改革的宣传与画题，亦后世「以少守多」常引之例。", "figures": ["（团长）让·德·瓦莱特", "（土军帅）拉拉·穆斯塔法", "（其水师）皮亚利帕夏"], "place": "马耳他（比尔古、圣埃尔莫）", "state": "奥斯曼帝国、医院骑士团、西班牙", "sources": ["骑士团与西西里之守城诸记、土军之纪与欧洲使报", "《马耳他之围与十六世纪地中海研究》"], "tags": ["围城", "海权"]}, "related": []},
  {"id": "world--1566--p01", "track": "world", "year": 1566, "yearApprox": false, "dim": "politics", "weight": 3, "title": "苏莱曼卒于西盖特瓦尔军前", "summary": "六十九岁亲征，卒于营中，死讯匿不发。", "detail": {"background": "1541年匈牙利三分以来，哈布斯堡守其西北边界。1566年夏苏莱曼以六十九岁亲征，取西盖特瓦尔外围的几座堡垒。", "process": "1566年8至9月围西盖特瓦尔（今匈牙利西），克罗地亚的兹里尼·米克洛什守内城战死。9月7日苏丹死在军帐，大维齐尔索科卢匿不发丧，全军循原路而还，第二年才公布其死。", "impact": "他在位四十六年「立法者」的格局遂终。塞利姆二世立而索科鲁掌权，奥斯曼将帅与财政入长期守成。1571年勒班陀与1573年单独媾和皆伏于此。", "figures": ["苏莱曼一世", "（大维齐尔）索科卢·穆罕默德帕夏", "（守城者）兹里尼·米克洛什"], "place": "西盖特瓦尔（今匈牙利西部）", "state": "奥斯曼帝国、匈牙利边郡（哈布斯堡）", "sources": ["奥斯曼军报与1567年之书札、匈牙利与哈布斯堡方之纪", "《苏莱曼与索科卢时代研究》"], "tags": ["阵殁", "秘丧"]}, "related": []},
  {"id": "world--1567--i01", "track": "world", "year": 1567, "yearApprox": false, "dim": "institution", "weight": 4, "title": "隆庆开海：月港给引", "summary": "闽海禁令一开，漳泉商人始出洋运银。", "detail": {"background": "明初以来片板不许下番之令，至嘉靖时漳泉海商与倭患相激，朱纨的肃清与王直之案相继而起。", "process": "1567年（隆庆元年）福建巡抚涂泽民请求开海禁，许漳、泉商船自月港（今福建龙海）出东西二洋，发给船引、设饷官并按「洋税」征它的入口税，用这笔钱饷兵。铜山各处的战氛因此稍敛。", "impact": "东南从此有合法出海之路，生丝、糖与瓷器换日本、美洲之银。月港—马尼拉此线与后来广州一口皆循其式，学界多认作1570年代以后白银大量入口的关键一环。", "figures": ["（福建巡抚）涂泽民", "（其地之商头）（漳泉海商）", "（其税之司）（饷馆之官）"], "place": "月港（今福建龙海）", "state": "明（福建漳州府）", "sources": ["《明实录·穆宗朝》、张燮《东西洋考》与《闽书》税课之文", "《剑桥中国明代史》、《白银与明末经济之变研究》"], "tags": ["海禁", "白银", "明代制度"]}, "related": []},
  {"id": "world--1568--p01", "track": "world", "year": 1568, "yearApprox": false, "dim": "politics", "weight": 4, "title": "阿尔瓦入尼德兰与什一之请", "summary": "一座监狱、一种税、两颗首领之头，八十年战事由此始。", "detail": {"background": "1566年图像风暴毁许多教堂，1567年宽赦的请求不被采纳。腓力二世召阿尔瓦公爵带西班牙兵北来，于布鲁塞尔设「勘狱」审问各城。", "process": "1568年勘狱的杀戮一天天扩大，5月于布鲁塞尔集市斩埃格蒙特与霍恩两位伯爵。同年「济贫什一」之议起（谓卖产者亦输十分之一），奥兰治的威廉逃往德意志，借佣兵与债款南下。", "impact": "税与首领两件事激成八十年的兵事（1568—1648）。阿尔瓦去职（1573）亦未能止，1576年「西班牙之怒」与北方的立国相继而起，勘狱案卷遂为尼德兰后世常据之材。", "figures": ["（西王之将）阿尔瓦公爵", "（奥兰治亲王）沉默者威廉", "（被斩者）埃格蒙特伯爵"], "place": "布鲁塞尔、安特卫普", "state": "尼德兰诸省、西班牙", "sources": ["勘狱案卷、「什一」之议与诸省文告、当时书报", "《尼德兰八十年战争与低地诸邦研究》"], "tags": ["征税", "起事"]}, "related": []},
  {"id": "world--1569--s01", "track": "world", "year": 1569, "yearApprox": false, "dim": "science", "weight": 3, "title": "墨卡托投影世界地图", "summary": "经纬线皆直，角度不失，船队可循直线定向。", "detail": {"background": "墨卡托在鲁汶制仪器与地图，1538年已有两半球图。其时航海苦于斜驶之线在旧图上画不成直线，量方向与算纬度两样都难。", "process": "1569年他以十九幅刊出世界地图，使经线纬线尽成直线，任一点的角度与地面相同（后世称「墨卡托投影」），图边附宇宙志考证，兼用磁偏为引。此图由其家人与阿姆斯特丹书商续印。", "impact": "从此船队能以直尺量向并校正位置，成为大航海的常用器具，荷兰海路尤赖之。此投影至今为海图与屏上之式，唯高纬度面积放大一点，亦为今人所争。", "figures": ["赫拉尔杜斯·墨卡托", "（其刻版者）（安特卫普之刻工）", "（其继印者）洪迪乌斯之家"], "place": "杜伊斯堡、阿姆斯特丹", "state": "神圣罗马帝国诸邦、低地", "sources": ["1569年图之存本与其《宇宙志》、后世校印本", "《早期制图学与投影法研究》"], "tags": ["制图", "航海"]}, "related": []},
  {"id": "world--1570--x01", "track": "world", "year": 1570, "yearApprox": false, "dim": "explore", "weight": 3, "title": "第一本地图集《地球舞台》", "summary": "合诸家地图为一册，制图乃成可传之业。", "detail": {"background": "地图散页长久以来在市上零卖，合订成册无定规。安特卫普的奥泰利乌斯与仕人、主教交友，积二十多年辑诸家图并校其地。", "process": "1570年5月在安特卫普刊《地球舞台》五十三图，每图著其作者与出处，别立目录与年表。不久增入今地志篇章与诸图，1575年后出法文、德文、荷兰文诸本。", "impact": "此为头一部以统一格式合诸家地图为一册的地图集，辑存诸家图说以遗后世。1570至1612年间印数十版，布劳家接着编，制图从此成一家之学、一业之传。", "figures": ["亚伯拉罕·奥泰利乌斯", "（其刻版者）科克", "（其续者）布劳之家"], "place": "安特卫普", "state": "西属尼德兰", "sources": ["1570年原本与其序、版权与印数之记、诸文种之本", "《早期地图集与低地制图业研究》"], "tags": ["地图集", "制图"]}, "related": []},
  {"id": "world--1571--m01", "track": "world", "year": 1571, "yearApprox": false, "dim": "military", "weight": 4, "title": "勒班陀海战", "summary": "圣日会战，沉焚对方一半战船，帆桨时代胜果未久。", "detail": {"background": "1570年土军取塞浦路斯，法马古斯塔的守将布拉加丁被剥皮殉难。教宗庇护五世合威尼斯、西班牙与意大利各邦战船为「神圣同盟」，同盟于1571年5月成议。", "process": "1571年10月7日两支舟师在勒班陀湾（今希腊西）相遇：同盟桨帆船二百多只与乌卢奇·阿里船二百三十多只横列相接，中央与右翼接舷自午至暮，土船沉焚被夺过半，水手弓手死者众。", "impact": "此为帆船代桨船以前地中海最大的一次水战，奥斯曼海军一时复元而失工匠与兵。然1573年威尼斯单独媾和、塞浦路斯终归于土，同盟胜果未成持久制海。", "figures": ["（同盟帅）奥地利的唐·约翰", "（土军将）乌卢奇·阿里帕夏", "（其左翼）韦尼耶", "（在场之兵）塞万提斯"], "place": "勒班陀（今希腊纳夫帕克托斯）", "state": "奥斯曼帝国、神圣同盟（教廷、威尼斯、西班牙）", "sources": ["两军之报、威尼斯与西班牙之纪及亲历者之书", "《勒班陀与十六世纪地中海之局研究》"], "tags": ["海战", "桨帆船"]}, "related": []},
  {"id": "world--1571--i01", "track": "world", "year": 1571, "yearApprox": false, "dim": "institution", "weight": 3, "title": "马尼拉定都吕宋", "summary": "于河港设官署，为菲律宾首府，华人商市在城东。", "detail": {"background": "黎牙实比1565年进宿务之后，遣戈伊特与萨尔门托北上探吕宋。1570年征马尼拉湾的土邦，其酉长先降后拒。", "process": "1571年5至6月西军入马尼拉河的港口，焚聚落并其地，设市政厅、王库、审判官署与托钵会教堂，定为菲律宾诸岛首府。对岸涧内一带为华人商人的市场。", "impact": "马尼拉自此为太平洋之枢：华人丝瓷与美洲、日本之银会于此，税与兵饷皆出于此。1603、1639、1662年几度华人被逐被杀之祸，亦起于此格局。", "figures": ["（其帅）黎牙实比", "（其将）马丁·德·戈伊特", "（其地酋长）拉贾·苏莱曼"], "place": "马尼拉（今菲律宾吕宋西岸）", "state": "西属菲律宾、吕宋诸土邦与华人商市", "sources": ["马尼拉市政会议之卷、王室令旨与涧内华人商市之记", "《西属菲律宾与太平洋之商研究》"], "tags": ["设都", "华人商市"]}, "related": []},
  {"id": "world--1572--p01", "track": "world", "year": 1572, "yearApprox": false, "dim": "politics", "weight": 4, "title": "圣巴托罗缪之杀", "summary": "婚仪人众遭屠，巴黎血流及诸省。", "detail": {"background": "1570至1573年两教和战交替。1572年4月纳瓦拉的亨利娶玛格丽特，新教诸侯与上流许多人入巴黎，海军提督科利尼正主其谋。", "process": "1572年8月22日科利尼遇刺受伤，24日清晨城中钟尽响，吉斯的部众与瑞士的兵按名分头杀新教之人。巴黎死者自二千到万余不等，八九月间屠杀延及鲁昂、波尔多、图卢兹诸城，各省合计学界估计数万。", "impact": "这场杀使「为良心而反抗上位者」在加尔文宗中成政论，法国的乱延二十六年。遭难者出逃与1685年离法相接续，成改革宗「分散之众」两潮。", "figures": ["（其命者）凯瑟琳·德·美第奇与查理九世", "（其始因）科利尼", "（其存者）纳瓦拉的亨利"], "place": "巴黎与法兰西诸城", "state": "法兰西王国", "sources": ["1572年王室之诏与两造之纪、当时外使之报", "《圣巴托罗缪之杀研究》（近人于其数与主谋尚有争）"], "tags": ["屠杀", "宗教战争"]}, "related": []},
  {"id": "world--1578--m01", "track": "world", "year": 1578, "yearApprox": false, "dim": "military", "weight": 4, "title": "马哈赞河三王会战", "summary": "一次会战三个王俱死，葡萄牙王统绝于外孙之手。", "detail": {"background": "摩洛哥前苏丹穆塔瓦基勒被弟弟阿卜杜勒-马利克赶走，借土耳其与葡萄牙求复位。少年葡王塞巴斯蒂安以讨异教、报恩人之名，聚众东渡。", "process": "1578年8月3日会战于马哈赞河的旷野（今凯比尔堡近旁，欧人谓之阿尔卡扎尔基比尔）：葡军以火绳与骑兵冲其阵地，土军与摩洛哥骑兵自两翼合击，葡军溃于河滨。塞巴斯蒂安、穆塔瓦基勒与阿卜杜勒-马利克三个王都死于是战。", "impact": "此战使萨阿德王朝得葡国赎金与火器而强，北非之局因此而定。两年后腓力二世借口继承断绝，兼并葡萄牙及其海外领地；荷兰、英吉利因被他敌视，转投东方商路。", "figures": ["（葡王）塞巴斯蒂安", "（萨阿德苏丹）阿卜杜勒-马利克", "（废王）穆塔瓦基勒"], "place": "马哈赞河（今摩洛哥北部）", "state": "葡萄牙王国、摩洛哥萨阿德王朝、奥斯曼", "sources": ["两方之军报、被虏欧人之赎单与摩洛哥方之纪", "《1578年马哈赞河与摩洛哥之局研究》"], "tags": ["会战", "王位继承"]}, "related": []},
  {"id": "world--1579--p01", "track": "world", "year": 1579, "yearApprox": false, "dim": "politics", "weight": 3, "title": "乌得勒支同盟", "summary": "北方五省合兵合财，共和国之基始立。", "detail": {"background": "1576年的根特和解欲合两教诸省以拒西班牙兵，可帕尔马公爵在1577、1578年用计拆散其党，南方诸城相继复附于西，北方改教之省愈发自危。", "process": "1579年1月23日荷兰、泽兰、乌得勒支、海尔德与格罗宁根诸城订乌得勒支同盟：并其兵马、钱粮与外交，各邦自定其教而互不侵犯，以省会议为常设之权。1581年下了断绝之令。", "impact": "此同盟为荷兰共和国的基础：联合各省却无共主，海省与土省主持政务，商、税与兵皆由会议出。八十年兵事至1648年才完，此制于十七世纪欧洲为一异例。", "figures": ["（奥兰治亲王）沉默者威廉", "（同盟之笔）奥尔登巴内费尔特", "（其敌）帕尔马公爵亚历山德罗"], "place": "乌得勒支", "state": "尼德兰北方诸省", "sources": ["同盟约文与诸省批准之卷、1581年断绝令之文", "《荷兰共和国之起源与制度研究》"], "tags": ["同盟", "共和国"]}, "related": []},
  {"id": "world--1580--p01", "track": "world", "year": 1580, "yearApprox": false, "dim": "politics", "weight": 4, "title": "腓力二世兼并葡萄牙", "summary": "两顶王冠归于一君，两洋守备反不能支。", "detail": {"background": "1578年塞巴斯蒂安无后嗣而死，叔父枢机恩里克1580年1月亦去世。克拉图的安托尼奥起事于里斯本，腓力二世凭母系与外兵来争王位。", "process": "1580年6月阿尔瓦之子带西军越境，8月25日亚尔萨拉之战打垮安托尼奥，1581年托马尔的会议许葡人保住自有法律、官吏与海外贸易，用其法律、其国自行治理。其海外遂同日归一君主。", "impact": "西、葡的海外合归一君，战线长到守不住。从1580年起，荷、英因西王敌视其商路，葡属东方（果阿、马六甲、摩鹿加）遂成两国攻击之靶，1602年荷兰东印度公司的谋划即由此而起。", "figures": ["腓力二世", "（其争位者）克拉图的安托尼奥", "（其将）（阿尔瓦公爵之子）"], "place": "里斯本、托马尔、亚尔萨拉", "state": "西班牙、葡萄牙及其海外", "sources": ["托马尔会议之记录、1580至1581年军报与诸城宣誓之卷", "《伊比利亚联盟与葡萄牙海外之局研究》"], "tags": ["并国", "两洋帝国"]}, "related": []},
  {"id": "world--1580--a01", "track": "world", "year": 1580, "yearApprox": false, "dim": "art", "weight": 2, "title": "蒙田《随笔集》增益本", "summary": "以己身为人学材料，「尝试」一体始立。", "detail": {"background": "蒙田自1571年辞公职，退处塔楼，藏书一千多册，用古人的话校核自身。自1572年起笔，1580年以前已经写成第一、二卷。", "process": "1580年巴黎刊行增益的《随笔集》，益以第三卷（含《论骑马》《论学童之教》诸篇）。同年9月起携仆行经洛林、瑞士与意大利十八个月，为访矿泉并验其说，别成《旅行日记》。", "impact": "他的书以「尝试」为名，自我观察的格局遂成后世随笔之体。《论食人者》举新大陆风俗以难欧洲之「文明」，为十七、十八世纪论风俗与教育者常引之篇。", "figures": ["米歇尔·德·蒙田", "（其亡友）拉博埃西", "（其校者）（1588年本之抄手）"], "place": "波尔多、巴黎、意大利", "state": "法兰西王国（吉耶内）", "sources": ["1580年增益本与《旅行日记》、1588与1595年本之校", "《蒙田与随笔之体研究》"], "tags": ["随笔", "自察"]}, "related": []},
  {"id": "world--1581--p01", "track": "world", "year": 1581, "yearApprox": false, "dim": "politics", "weight": 3, "title": "七省下令断绝同西王之统属", "summary": "一纸废一君称号，主权之说自此南传。", "detail": {"background": "1579年同盟之后，北方诸省仍奉腓力二世称号，同时要求他改政。1580年并国之后，西班牙用异国法官与兵来治其地，各省的冤抑无处可诉。", "process": "1581年7月26日荷兰、泽兰等省集会于海牙，颁下「断绝之状」，逐条列出他违背宣誓、以外国议事行于本国、放兵屠城的罪状，遂废其君号，另求他主（先请安茹的弗朗索瓦，后请莱斯特）。", "impact": "一省众人用文字废掉所奉的君主，可称显例；文中拿君民盟约作根据，开后世「政本于众」之说。1584年威廉遇刺后各省不再立共主，成为「无伯之邦」的共和国。", "figures": ["（奥兰治亲王）沉默者威廉", "（其敌）腓力二世", "（其议之主）荷兰省会议"], "place": "海牙、德尔菲特", "state": "尼德兰北方诸省、西班牙", "sources": ["《断绝之状》原文与省会议之记录、当时书报", "《荷兰共和国之起与王权之废研究》"], "tags": ["断绝", "主权"]}, "related": []},
  {"id": "world--1582--m01", "track": "world", "year": 1582, "yearApprox": false, "dim": "military", "weight": 3, "title": "本能寺之变：信长死", "summary": "一场晨火焚其未竟之业，天下遂易主。", "detail": {"background": "织田信长以火绳与马回之建制破各寺院及浅井、朝仓，1582年命诸将分道向西攻毛利与本愿寺显如；羽柴秀吉在备中以水攻高松城。", "process": "1582年6月21日清晨（天正十年六月二日），明智光秀带数千人众围京都本能寺，信长死在火里，尸首竟未寻到；秀吉即刻同毛利议和赶回，几天后山崎一战打垮光秀，光秀逃走而死。", "impact": "信长未成的天下归了秀吉：1585年任关白、1587年下国之令、1590年取小田原。「下克上」的势头与检地、刀狩之制相沿不断，到德川手里才见结果。", "figures": ["织田信长", "明智光秀", "（其继者）丰臣秀吉"], "place": "京都本能寺、山崎", "state": "日本（织田政权）", "sources": ["《信长公记》与京都诸日记、当时耶稣会之风说书", "《安土桃山与日本统一之局研究》"], "tags": ["政变", "战国"]}, "related": []},
  {"id": "world--1582--s01", "track": "world", "year": 1582, "yearApprox": false, "dim": "science", "weight": 3, "title": "格里高利改历", "summary": "春分归复原日，欧洲记日自此分两条轨道。", "detail": {"background": "儒略历一年以三百六十五日又四分之一计，一千六百多年后春分已提前至三月十一日，复活节等节期的确定皆受干扰；特伦托公会故下令讨论改历。", "process": "1582年2月颁诏，定十月四日的第二天为十月十五日，春分回到三月二十一日；其法是整百年不闰、四百年再闰（1700、1800不闰，2000闰），并命克拉维乌斯校核算法、刊行历书考证。", "impact": "天主教各国当年改历，英国、瑞典与东正教各国以教会与政权之故拖到十八、二十世纪，欧洲记日从此有新旧两历之别；今日公历即此制，而这次改动不独是历法计算，亦一家教会权力所及。", "figures": ["（教宗）格里高利十三世", "（其历之议）利利乌斯", "（主其算者）克拉维乌斯"], "place": "罗马", "state": "教廷、天主教诸国", "sources": ["1582年改历之诏《严重之务》与其《历书之考》、诸国执行之文", "《历法改革与新旧历之争研究》"], "tags": ["历法", "天文"]}, "related": []},
  {"id": "world--1585--e01", "track": "world", "year": 1585, "yearApprox": false, "dim": "economy", "weight": 3, "title": "安特卫普陷落与商人北迁", "summary": "一港封死，南方市场遂迁于阿姆斯特丹。", "detail": {"background": "安特卫普是北方大市集，港经斯海尔德通海，布匹、粮食与各国货物都靠它；1576年「西班牙之怒」后该城入和解之盟，改信新教的人日多，帕尔马公爵渐次攻取南方诸城，志在此港。", "process": "1584年夏始围攻：以浮桥与两座堡垒断斯海尔德水路，围城绝援；1585年8月17日订约投降，许一年之内装货离去，不肯改信的人必须离城。此后数年手工业者与商户接连北迁（人数诸记载出入很大）。", "impact": "斯海尔德从此长期封闭，安特卫普的出海口遂废；北方因以大盛，1609年阿姆斯特丹汇兑银行与1602年东印度公司皆以此地资本为本。一城易主，低地南北分治之局形成。", "figures": ["帕尔马公爵亚历山德罗", "（其守城者）安特卫普市之长老", "（北迁之工）佛兰德与瓦隆之织工"], "place": "安特卫普、阿姆斯特丹、米德尔堡", "state": "西属尼德兰、北方诸省", "sources": ["1585年降约之文与市之账籍、当时迁出与户口之记", "《安特卫普之陷与荷兰黄金时代之起研究》"], "tags": ["围城", "商路之移"]}, "related": []},
  {"id": "world--1587--i01", "track": "world", "year": 1587, "yearApprox": false, "dim": "institution", "weight": 3, "title": "丰臣秀吉下令驱逐传教士", "summary": "教会与商贸分置：逐传教士，留商船。", "detail": {"background": "秀吉自1583年后主宰天下，建大阪城并接受朝廷任命；耶稣会与托钵修会的教务已入畿内、九州，有教堂、田地和寺院的施舍，消息亦传到长崎港。", "process": "1587年6月19日（天正十五年五月一日）于肥后久留米发出「伴天连追放之文」，责其「用巧言诱人、毁坏神社佛寺、破坏先王制度」，限期二十日令传教士离境，而许葡、西商船前来；命令初未即行，1596年的船事冤案与1597年二十六人于长崎被处死为转折点。", "impact": "教禁与商路分行之局从此定下，家康沿用；至1614年大举驱逐传教士、1637年岛原之乱后禁令尤严，「隐匿的基督徒」将其礼仪私存至十九世纪方公开。", "figures": ["丰臣秀吉", "（殉者之一）保罗·三木", "（其时之会长）范礼安"], "place": "肥后久留米、长崎", "state": "日本（丰臣政权）、耶稣会日本传教区", "sources": ["《伴天连追放文》原文与教会之年报、朝鲜与葡国之报", "《禁教与南蛮贸易之局研究》"], "tags": ["禁教", "日本"]}, "related": []},
  {"id": "world--1588--m01", "track": "world", "year": 1588, "yearApprox": false, "dim": "military", "weight": 4, "title": "无敌舰队战败", "summary": "长炮边行边击，风暴继于北岸收拾残局。", "detail": {"background": "1585年法兰西吉斯党与西班牙国王结盟，援军遂断；腓力二世合卡斯蒂利亚与葡萄牙的船为大队，拟渡海峡、恢复英吉利旧教，并约帕尔马陆军会合。", "process": "1588年7月29日至8月8日经过海峡：英船以长炮边航边击，不跟它接舷；8月7日夜用火船乱其锚位，8日在格拉沃兰外海阵形散开北撤，绕爱尔兰、苏格兰海岸遇风暴礁石，又沉几十船，死亡生病的处处可见。", "impact": "英吉利从此无登陆之患，西班牙十年后才复船只与兵力；而1589年英国「反舰队」打卡迪斯亦大败，海权并未因此一并转移。英西海上相持六十年，荷、英东方的商路反而因此更方便。", "figures": ["（西舰队帅）西多尼亚公爵", "（英舟帅）霍华德勋爵", "（其将）德雷克、弗罗比舍"], "place": "英吉利海峡、格拉沃兰、爱尔兰外海", "state": "西班牙、英格兰王国", "sources": ["两军之报与事后之鞫、荷兰与法兰西使之书报", "《1588年舰队之役与英西海上之争研究》"], "tags": ["海战", "炮舰"]}, "related": []},
  {"id": "world--1589--f01", "track": "world", "year": 1589, "yearApprox": false, "dim": "figure", "weight": 2, "title": "亨利三世遇刺于圣克卢", "summary": "一刀而瓦卢瓦血绝，波旁氏入承王位。", "detail": {"background": "1580年代亨利三世与吉斯家族互相猜忌，1588年12月下令于布卢瓦杀吉斯两人；巴黎十六人委员会拒其进城，国王外出避难，与纳瓦拉的亨利合兵围首都。", "process": "1589年7月30日，多明我会士雅克·克莱门借奏事近御前，用短刀刺入其腹；8月1日至2日，国王当面以继位之权交付妻子的弟弟纳瓦拉的亨利，说他应当接替自己，不久去世。", "impact": "瓦卢瓦的血统从此断绝，波旁氏入承：亨利四世再攻首都，1590年伊维之役、1594年入巴黎、1598年南特敕令，皆起于这两天。", "figures": ["亨利三世", "（其刺客）雅克·克莱门", "（其受命者）纳瓦拉的亨利"], "place": "圣克卢（今巴黎西郊）", "state": "法兰西王国、纳瓦拉", "sources": ["1589年王室记事与当时书报、克莱门案之纪", "《三亨利之年与瓦卢瓦之末研究》"], "tags": ["弑君", "王统"]}, "related": []},
  {"id": "world--1591--m01", "track": "world", "year": 1591, "yearApprox": false, "dim": "military", "weight": 3, "title": "丁迪比之战：摩洛哥击破桑海", "summary": "数千人越沙漠，火枪大破其骑兵。", "detail": {"background": "桑海阿斯基亚·穆罕默德据尼日尔河中游，掌黄金、盐与书籍之路；萨阿德的艾哈迈德·曼苏尔以不得当地黄金，谋议南征，1590年遣朱达尔率数千火枪兵与辎重越撒哈拉。", "process": "1591年3月13日战于丁迪比（今加奥以西）：摩洛哥军以车载火炮与火枪抵挡对方众多骑兵，桑海军溃败；4月进加奥，再取廷巴克图与杰内，几城学者与商人中有被掳北去的。", "impact": "尼日尔河流域从此无统一政权，城市与诸部各自立；廷巴克图的学术与商业仍续，撒哈拉金路渐移北岸，塞内加尔河与几内亚海岸遂为十六世纪末以后欧洲人争夺市场之地。", "figures": ["（萨阿德苏丹）艾哈迈德·曼苏尔", "（其将）朱达尔帕夏", "（桑海君）阿斯基亚·穆罕默德"], "place": "丁迪比、加奥、廷巴克图（今尼日尔河大弯之北）", "state": "摩洛哥萨阿德王朝、桑海帝国", "sources": ["《塔里赫·苏丹》（萨迪）与《塔里赫·菲什提亚》之辑本、摩洛哥方之纪", "《撒哈拉之火枪与西苏丹之局研究》"], "tags": ["火器", "西非"]}, "related": []},
  {"id": "world--1592--m01", "track": "world", "year": 1592, "yearApprox": false, "dim": "military", "weight": 5, "title": "平壤陷落：壬辰役开始", "summary": "十来日三座都城尽失，义兵与水师起于后。", "detail": {"background": "秀吉1590年取小田原统一本国，以「假道入明」之说为难朝鲜，而朝鲜的回书不合其意，遂发八道人马与水师东渡。", "process": "1592年4月（旧历十三日）在釜山登陆，东莱、庆州相继失守，4月底入汉城，5月下平壤，宣祖北逃至义州；义兵起于湖南、僧兵起于金刚山，李舜臣水师在玉浦、闲山等战断其海上运粮。", "impact": "明朝出兵援朝（1592年冬沈惟敬、祖承训，1593年李如松取平壤），两国兵力俱敝，至1598年秀吉死才并撤。东亚秩序与属国请援之制经此战而定，朝鲜的残破、明朝辽东兵费的消耗，皆1619年以后新局面之由来。", "figures": ["（其命者）丰臣秀吉", "（水师之将）李舜臣", "（北奔之君）朝鲜宣祖"], "place": "釜山、汉城、平壤（今朝鲜半岛）", "state": "朝鲜王朝、日本（丰臣政权）、明", "sources": ["《朝鲜王朝实录·宣祖实录》与义兵状、明人之纪与日本军记", "《壬辰倭乱与东亚秩序之变研究》"], "tags": ["入侵", "东亚秩序"]}, "related": []},
  {"id": "world--1596--x01", "track": "world", "year": 1596, "yearApprox": false, "dim": "explore", "weight": 3, "title": "荷兰首批船东抵万丹", "summary": "四艘船绕好望角而来，荷兰人自为其商。", "detail": {"background": "1592年霍特曼从葡萄牙逃回，林斯霍滕刊所见所闻为《旅行志》与《航海记》，备言东方利润与葡萄牙的虚实；阿姆斯特丹商人遂合股派船东行。", "process": "1595年4月四船出港，绕好望角，1596年6月至万丹（今爪哇西北）：霍特曼与葡萄牙人互相猜疑，又与当地王公争执礼节，货物卖得不多即回；1598年第二、第三次航行接着到，1601年范·内克的船在摩鹿加以火炮败葡船。", "impact": "荷兰人从此不借葡萄牙属印度，自取其商路；1602年各省船合为东印度公司，1619年据巴达维亚，胡椒与香料运输渐脱葡人之手，欧洲与东亚贸易另开一门。", "figures": ["（其帅）科内利斯·德·霍特曼", "（其导）林斯霍滕", "（其出资者）阿姆斯特丹之商股"], "place": "万丹（今爪哇西北外港）", "state": "荷兰诸省、万丹苏丹国、葡属印度", "sources": ["霍特曼之航纪、林斯霍滕之书与荷兰、葡国文书", "《荷兰东向航路与葡属香料之衰研究》"], "tags": ["东印度", "香料"]}, "related": []},
  {"id": "world--1598--i01", "track": "world", "year": 1598, "yearApprox": false, "dim": "institution", "weight": 3, "title": "南特大敕令", "summary": "一道敕令定两种宗教并存之国，战乱息四十多年。", "detail": {"background": "1589至1598年间，联盟的十六人、西班牙军队与国王改宗诸事接连发生；1594年亨利四世入巴黎，1595、1596年数胜西班牙军，1598年初克昂布雷，双方俱困乏。", "process": "1598年4月13日在南特颁行大敕：定天主教会为国教，同时许改革宗信徒于指定城镇与贵族领地信仰、行礼，给以安全城市与兵饷（期限后定为八年），并许其民事、学校、医院与司法上的平等。", "impact": "「一国两教但两者地位不平等」之局从此形成，法兰西战乱停止于四十多年之内；其秘密条款与后来的撤销（1685年）成对照，常被后世论宽容、国教与臣民权利者引用。", "figures": ["亨利四世", "（其后之理财臣）叙利公爵", "（其敌之党）巴黎联盟诸城"], "place": "南特", "state": "法兰西王国", "sources": ["《南特敕令》原文与诸省议会登录之文、两教之诵读者", "《南特敕令与一国之两教研究》"], "tags": ["敕令", "信仰宽容"]}, "related": []},
  {"id": "world--1598--p01", "track": "world", "year": 1598, "yearApprox": false, "dim": "politics", "weight": 2, "title": "秀吉死与诸将放弃朝鲜", "summary": "讳死讯而撤军，东亚战事七年后解。", "detail": {"background": "1597年兵端再起（丁酉之役），明朝、朝鲜共拒之，西路军停在蔚山城下，海上水师数失利；1598年秋秀吉病重，幼子尚未立定。", "process": "1598年9月18日秀吉死，顾命五大老、五奉行匿其丧，令在朝鲜诸将依次西归；11月露梁海战中明船与朝船断其归路，李舜臣与明邓子龙战死，部众渡海西归。", "impact": "七年的战事至此结束，日本不复有对外征讨之令，家康凭论功行赏及对马、萨摩与朝鲜、琉球的往来另立规矩；明朝辽东与朝鲜残破，为1619年后建州兴起与丙子之役留下空隙。", "figures": ["丰臣秀吉", "（其继者）德川家康", "（战殁者）李舜臣"], "place": "大阪、顺天、露梁（今朝鲜南海）", "state": "日本、朝鲜、明", "sources": ["《宣祖实录》与撤兵诸役之纪、日本军记与明人之报", "《庆长之世与东亚之余局研究》"], "tags": ["撤兵", "东亚"]}, "related": ["cn--1597--m01"]},
  {"id": "world--1600--f01", "track": "world", "year": 1600, "yearApprox": false, "dim": "figure", "weight": 2, "title": "布鲁诺焚于罗马花场", "summary": "八年审讯不易其说，一火并其宇宙观焚之。", "detail": {"background": "多明我会士布鲁诺1576年离会后，辗转日内瓦、维滕贝格、法兰克福、牛津与巴黎，写了宇宙论，说恒星都是太阳、世界数不清、万物皆有灵魂。", "process": "1592年为威尼斯异端审判所拘捕，1593年解至罗马；审讯八年，所追究者有三位一体与基督神性、圣事、魔法及其宇宙诸说；1600年2月17日焚于花场，据载其口被绑。", "impact": "他的死为官方火刑处置宇宙论案中最著名一件，1889年于焚烧处立像；但近代学者多认为定罪根本在神学而非哥白尼学说，这案为何如此判决至今仍有争论。", "figures": ["焦尔达诺·布鲁诺", "（审其案者）（教廷之审官）", "（其说所自）尼古拉·哥白尼"], "place": "罗马（花场）", "state": "教廷", "sources": ["1593至1600年审案之卷与告词、裁判所之记录", "《布鲁诺案与宇宙论之禁研究》"], "tags": ["火刑", "宇宙论"]}, "related": []},
  {"id": "world--1600--m01", "track": "world", "year": 1600, "yearApprox": false, "dim": "military", "weight": 3, "title": "关原之战", "summary": "晨间倒戈，东、西两方诸侯易主。", "detail": {"background": "1598年后家康与石田三成两党因封赏、婚约与「私誓之争」互相激化；1600年夏家康以征讨上杉为名在大阪会合诸将，三成便在西国起兵抵挡。", "process": "1600年10月21日（庆长五年九月十五日）战于美浓关原：西军小早川秀秋诸队据山不动，午后东军以铁炮队逼其阵，秀秋倒戈，西军溃逃；三成于近江伏见被执见斩，家康十二月入大阪城。", "impact": "胜者以大规模封地迁调安置诸侯，外样徙边远而亲藩据要地；「一国一城」与《武家诸法度》（1615）定君臣规格，1603年的幕府即此役之果，二百六十年之制从此打底。", "figures": ["德川家康", "（其敌）石田三成", "（倒戈者）小早川秀秋"], "place": "美浓关原（今岐阜县一带）", "state": "日本（德川与石田两党）", "sources": ["庆长诸军记、江户之《德川实纪》与平户荷兰商馆之风说书", "《关原之役与幕藩体制之始研究》"], "tags": ["会战", "幕藩"]}, "related": []},
  {"id": "world--1601--c01", "track": "world", "year": 1601, "yearApprox": false, "dim": "culture", "weight": 3, "title": "利玛窦进入京师", "summary": "以地图器物为介，西方之教与士大夫相通。", "detail": {"background": "利玛窦自1583年入居肇庆、韶州，以世界图、自鸣钟与计算器具结交士大夫，渐脱僧侣服色改穿儒衣；1598年一次北上遇朝鲜战事，退回留在南京。", "process": "1600年携方物与器物北上，1601年入京师（入京年份在1600、1601之间，诸记载略有异同），得居宣武门一带建堂讲学；与徐光启、李之藻论几何、历算与教理，信教的人日增。", "impact": "「合儒、补儒」的策略从此推行，其译述（《几何原本》前六卷1607、《同文算指》《乾坤体义》）为士大夫开一门西学；教友人数于十七世纪中叶渐增，学界多估计明末在十万上下，相关争论亦开礼仪之争。", "figures": ["利玛窦", "（其徒）徐光启", "（其同会）庞迪我"], "place": "京师（今北京）", "state": "明（万历朝）、耶稣会中国传教区", "sources": ["《利玛窦中国札记》（金尼阁辑）与《明实录》、士大夫之文集", "《耶稣会士与中西学术之相遇研究》"], "tags": ["传教", "中西学术"]}, "related": ["cn--1602--x01"]},
  {"id": "world--1602--i01", "track": "world", "year": 1602, "yearApprox": false, "dim": "institution", "weight": 5, "title": "荷兰东印度公司获特许", "summary": "公司拥宣战、铸币之权，商业与军队合而为一。", "detail": {"background": "1594年后各省船队竞相赴东方，荷兰、泽兰诸市场的船价、运货成本与保险相乱；执政奥尔登巴内费尔特与诸商人议并为一家公司，以垄断、缔约、守堡为职。", "process": "1602年3月20日联各省东方贸易为「联合东印度公司」，授二十一年的独占权（此后多次延长），许其筑垒、缔约、宣战、铸币与任免总督；在阿姆斯特丹设「十七人」议事会，1619年据巴达维亚为首府。", "impact": "其以商业与国家之事集于一身：股份在阿姆斯特丹市场日日交易（后世多谓最早的公开上市股票），以香料垄断、班达屠杀（1621）与中国—日本—台湾一线支息；荷兰的商业、军事、地图与绘画皆赖之而立。", "figures": ["（其主谋）奥尔登巴内费尔特", "（首任东印度总督）彼得·科恩", "（其议之司）十七人委员会"], "place": "阿姆斯特丹、代尔夫特诸商会厅；巴达维亚", "state": "荷兰共和国、爪哇与东亚诸港", "sources": ["1602年特许状原文、「十七人」议事会之录与公司账册", "《荷兰东印度公司与十七世纪亚洲之商研究》"], "tags": ["公司", "垄断特许"]}, "related": []},
  {"id": "world--1603--p01", "track": "world", "year": 1603, "yearApprox": false, "dim": "politics", "weight": 4, "title": "江户幕府开设", "summary": "两个都城并立：朝廷命官，幕府执权柄。", "detail": {"background": "关原之后家康挟大坂丰臣与西国外样两头制局，屡增领地数目与江户街区；1603年春受朝廷任命，而幕府设在江户。", "process": "1603年2月（庆长八年十二月改元之初）任征夷大将军，筑江户城与府署，定旗本、御家人的领地数目与诸国普请劳役；1605年让名号于继子秀忠而自居大御台，开「二代并立」之例。", "impact": "「京都的朝廷、江户的幕府」两都制从此定下：天子有任官之名而无实际政事，诸侯有封国而必赴江户；此后二百六十年兵祸几息，世称「元和偃武」之局。", "figures": ["德川家康", "（其嗣）德川秀忠", "（其僧）天海"], "place": "江户、京都", "state": "日本（德川幕府）", "sources": ["《德川实纪》与幕府文书、京都五山僧录与公家之日记", "《幕藩体制与二都之制研究》"], "tags": ["幕府", "二元之政"]}, "related": []},
  {"id": "world--1607--i01", "track": "world", "year": 1607, "yearApprox": false, "dim": "institution", "weight": 3, "title": "詹姆斯敦与弗吉尼亚永久驻扎", "summary": "一座小岛堡垒初立，烟草起，切萨皮克格局遂成。", "detail": {"background": "1606年英王詹姆士一世以两家公司的执照许其于北温带海岸建「永久驻地」；1607年春三只船西行，择詹姆斯河上易守之岛筑堡。", "process": "1607年5月14日建詹姆斯敦：起初专做寻金与货载的事，不务耕种，与波瓦坦各部一面交易一面打仗；1610至1611年盖茨、戴尔整顿耕种的法规，1612年始种烟草，1614年与当地大酋议和。", "impact": "此为英国在美洲最早的永久殖民点，1619年始有代议会议；烟草园开「头权」之制及后来契约仆与非洲劳役，与波瓦坦界议终致1622、1644年大战。", "figures": ["（其照之主）詹姆士一世", "（其殖民之长）约翰·史密斯", "（其邻之部）波瓦坦联盟"], "place": "詹姆斯敦（今美国弗吉尼亚）", "state": "英格兰王国、波瓦坦诸部", "sources": ["史密斯《弗吉尼亚志》与公司之报、1607年前后之信札", "《切萨皮克之起与波瓦坦之遇研究》"], "tags": ["殖民", "烟草"]}, "related": []},
  {"id": "world--1608--x01", "track": "world", "year": 1608, "yearApprox": false, "dim": "explore", "weight": 3, "title": "尚普朗建魁北克据点", "summary": "据圣劳伦斯河收窄处立营寨，新法兰西之端始此。", "detail": {"background": "1603年尚普朗随人溯圣劳伦斯河上行，记下这段河岸可立足；法国既要毛皮，也要一条通亚洲的路，1608年再派他西行。", "process": "1608年7月，他在河岸一处收窄的峭壁下搭起木石营寨，当地原住民称此为魁北克，义取狭路；头一个冬天死于坏血病者甚众，遂与蒙特、阿尔冈昆诸族结盟，以火器助其相争，把据点营成皮毛贸易码头，1613年回法募民再建。", "impact": "此为法国在北美第一处长期居留地，新法兰西由此起；1629年为英人所夺、1632年归还后成传教与毛皮之枢纽，直至1759年亚伯拉罕平原之役易手于英国。加拿大法语区的地理边界由此定下。", "figures": ["萨缪尔·尚普朗"], "place": "圣劳伦斯河魁北克（今加拿大魁北克省）", "state": "法兰西王国（新法兰西）", "sources": ["尚普朗《游记》（1613年初刊、1632年增订）", "《新法兰西耶稣会年报》", "魁北克省立档案馆早期殖民记录"], "tags": ["新法兰西", "魁北克", "毛皮贸易", "北美殖民"]}, "related": ["world--1535--x01", "world--1609--x01"]},
  {"id": "world--1609--s01", "track": "world", "year": 1609, "yearApprox": false, "dim": "science", "weight": 5, "title": "伽利略用望远镜测天", "summary": "移镜指月，月有山谷，木星旁有四颗小星。", "detail": {"background": "荷兰眼镜匠1608年以组合镜片献于海牙，做法不久传遍欧洲；伽利略时在帕多瓦讲学，听到这说法，自磨镜片并加倍数。", "process": "1609年夏，以厚薄不一的玻璃叠成管，自三倍递至三十倍；秋夜指月，见月面有山谷与环形坑，又见数不清的大量恒星。1610年1月7日夜记四颗小星绕木星运行，一个多月后定其为绕木星之天体；又见金星有盈亏、日斑西移。1610年3月在威尼斯刊行《星际信使》，薄薄几页纸载月面图与木卫之名。", "impact": "四颗星自行绕木星转，可见天体不止一个中心，地球不动的老说法失去依据；望远镜从此成为天文学的眼睛。罗马献镜之初几乎得教廷赞誉，但1616年圣座神学家判日心说为虚妄，路就此分开，到1633年便有审讯。学者论科学革命，多以1609、1610两年为标志。", "figures": ["伽利略·伽利雷", "（献镜于海牙者）荷兰米德尔堡之眼镜匠", "（其刊书者）威尼斯之刻工"], "place": "帕多瓦、威尼斯", "state": "威尼斯共和国、帕多瓦（属威尼斯）", "sources": ["伽利略1609—1610年之手稿与测记、《星际信使》1610年原本", "费诺基亚罗《伽利略之文献》、德雷克《伽利略传》"], "tags": ["望远镜", "天文学", "实证"]}, "related": []},
  {"id": "world--1609--c01", "track": "world", "year": 1609, "yearApprox": false, "dim": "culture", "weight": 3, "title": "《海洋自由论》刊于莱顿", "summary": "为公司作一纸辩解，遂开海上公法之端。", "detail": {"background": "荷兰东印度公司东航得手，与伊比利亚的航路垄断相冲；1603年其船于圣加略夺葡船，公司上下须自讲其理。时年二十岁的格劳秀斯受公司委托，以旧撰《捕获法》残稿另行裁断成篇。", "process": "1609年在莱顿匿名刊行《海洋自由论》，小册不满几页，断言海与洋路不能为任何君侯私产，贸易当向各国一同开放；矛头虽指东方，其理则涉欧洲诸邦之争。1610年以后此书屡遭禁刻又再版。", "impact": "教皇划界与葡、西专利的说法自此有公开论敌；英国人塞尔登1635年作《海闭论》相答，两说并立直到十九世纪。此书亦为公司权力与主权之别立底，后世论早期全球法者皆本于此。", "figures": ["雨果·格劳秀斯", "（公司之督）东印度公司十七人董事会", "（其说之敌）约翰·塞尔登"], "place": "莱顿", "state": "荷兰联省", "sources": ["《海洋自由论》1609年原本、格劳秀斯1608年为东印度贸易所作之辩护", "《剑桥近代早期欧洲史》与其近代国际法之研究"], "tags": ["国际法", "航路", "东印度公司"]}, "related": []},
  {"id": "world--1609--x01", "track": "world", "year": 1609, "yearApprox": false, "dim": "explore", "weight": 2, "title": "哈德逊溯北美大河", "summary": "一船沿河而上，荷兰据点因之而兴。", "detail": {"background": "英国东印度公司招人寻绕北航路，舵工哈德逊三次都没能前进；1609年受联省雇，乘小船「半月」号西渡。", "process": "1609年9月入今纽约外湾，沿大河北上至约六百公里内陆（水已淡仍寻不到海），误以为或者通太平洋；归国后联省以当地毛皮利厚而占地。1610年英国公司再遣其东航寻西北道，入今天的巨湾、在冰中过冬，第二年夏船上人杀之。", "impact": "此行实新尼德兰之开端：1614年当地始有地图，1624—1626年阿姆斯特丹人与公司至曼哈顿定居；河与湾皆留其名。求北路之愿历明清而未断，英国人一百五十年后（1845年富兰克林的船）仍然覆没在冰里。", "figures": ["亨利·哈德逊", "（半月号之记）舟员朱厄特之报", "（雇之者）联省之东印度公司"], "place": "北美东岸之大河与巨湾（今纽约、哈德逊湾）", "state": "荷兰联省、英格兰王国", "sources": ["1609—1610年之航海记与联省之委书（后人所辑）、普莱斯的《哈德逊探查志》", "《剑桥北美早期史》"], "tags": ["探查", "毛皮", "新尼德兰"]}, "related": []},
  {"id": "world--1610--p01", "track": "world", "year": 1610, "yearApprox": false, "dim": "politics", "weight": 3, "title": "亨利四世遇刺于巴黎", "summary": "一刀及国王，幼主即位，王后摄政。", "detail": {"background": "南特敕令后王国始复，田赋稍定，巴黎百姓忧1610年春国王的病；国王方谋北渡莱茵河与哈布斯堡相争。行刺者拉瓦亚克出旧耶稣会学塾，同学中多传刺杀君主的议论。", "process": "1610年5月14日傍晚，王车为圣奥诺雷街的运货车所阻，拉瓦亚克自车门入，一刀刺中胸口，次日清晨国王去世，年五十七。太子九岁即位，王后玛丽·德·美第奇称摄政；耶稣会士以不肯宣誓，是年逐去两千余人。", "impact": "亲哈布斯堡的党派与摄政太后之权互相倾轧，1614年三级会议无结果而散；黎塞留由此入太后谋划，1624年为首席大臣，法国政策转反哈布斯堡。南特教民虽仍受敕令保护，朝中势力从此孤立。", "figures": ["亨利四世（纳瓦拉之亨利）", "（弑者）弗朗索瓦·拉瓦亚克", "（摄后者）奥地利的玛丽·德·美第奇"], "place": "巴黎", "state": "法兰西王国", "sources": ["巴黎高等议会之笔录、审讯之档与1610年之邸报", "《剑桥法国史》、比亚尔《弑君之案与拉瓦亚克》"], "tags": ["弑君", "摄政", "宗教之争"]}, "related": []},
  {"id": "world--1615--i01", "track": "world", "year": 1615, "yearApprox": false, "dim": "institution", "weight": 3, "title": "武家诸法度与一国一城之令", "summary": "定诸大名城池数目与人臣礼数，幕藩体制以固。", "detail": {"background": "关原、大阪两役之后，德川氏有天下，而各家封地、城守与众多浪人未及收束；江户的老中谋为制度规格，京都的朝廷亦须有约束。", "process": "1615年（庆长二十年）七月，以《武家诸法度》数条颁示大名：修城、嫁娶、结党皆须听幕府之命，由京都所司代监之；同年七月又令各家毁本城以外的支城（一说此令无专文存下，出后人辑记，学界尚在辩）。本年又定《禁中并公家诸法度》，朝廷授官与学艺皆归其范围。", "impact": "大名的城从数百减到数十，军费与守备之权归江户；1635年重订法度，增列参勤交代与造船禁令，浪人户籍渐定。幕藩之制（将军、藩、旗本三直）以此二法为骨干，直至1868年。", "figures": ["德川秀忠", "（其谋臣）以心崇传（金地禅悦）", "（成其法者）土井利胜、本多正纯"], "place": "江户、京都、大阪", "state": "江户幕府", "sources": ["《武家诸法度》庆长本与宽定本、《禁中并公家诸法度》、《德川实纪》", "《近世日本之成立》与幕藩制之研究"], "tags": ["幕藩体制", "法令", "德川"]}, "related": []},
  {"id": "world--1618--p01", "track": "world", "year": 1618, "yearApprox": false, "dim": "politics", "weight": 4, "title": "布拉格掷窗事件，波希米亚反叛", "summary": "两个自窗坠下不死，三十年战火由此点燃。", "detail": {"background": "1609年鲁道夫二世诏书许波希米亚等级信教之权；马蒂亚斯即位后，其弟斐迪南（后来的斐迪南二世）急推天主教的政事于波希米亚，夺其礼拜之堂，等级上诉朝廷而不得公正。", "process": "1618年5月23日，新教等级聚于布拉格城厅，责问两名钦差与一名书记，随即自约二十米高的窗口将其掷下；三人不死，耶稣会士谓落于粪堆，等级则言天使接住。事传开，等级废效忠之礼，设三十人执政；1619年拒斐迪南为王，不久拥立普法尔茨的腓特烈为波希米亚王。", "impact": "1620年白山战败，27名首领受刑于布拉格老城广场，流亡的人以千计；斐迪南二世以1629年归还敕令取回新教之堂，萨克森与丹麦、瑞典接着参战，此祸至1648年才定。史家多以为三十年战争的起点。", "figures": ["（等级之长）图恩伯爵", "（被掷者）马丁尼茨与斯利乌克", "（其敌之君）斐迪南二世"], "place": "布拉格", "state": "波希米亚王国（哈布斯堡领）、神圣罗马帝国", "sources": ["1618年等级之书与两造之报、掷窗之铜刻与图说", "《剑桥三十年战争史》、威尔逊《威斯特伐利亚之乱》"], "tags": ["掷窗", "三十年战争", "等级政治"]}, "related": []},
  {"id": "world--1619--e01", "track": "world", "year": 1619, "yearApprox": false, "dim": "economy", "weight": 3, "title": "非洲人首次被卖至弗吉尼亚", "summary": "二十多人自一条船上岸，役法渐为世袭之奴。", "detail": {"background": "弗吉尼亚公司招白人契约奴而苦人数不足，烟草的种植方兴，田土需劳力；1619年西班牙与葡属安哥拉的非洲人已由加勒比转卖而来，北美移民亦入此市。", "process": "1619年8月末，一艘自西印度来的船运来二十多个非洲人，售与詹姆斯敦垦户，其人多出安哥拉金贝杜一带，途中遭劫掠、转手了好几重。同年7月弗吉尼亚市民议会初次开会，为北美代议权力之开端；这二十多人初依契约奴惯例安置，1620年代已有人获释自营。", "impact": "劳役身份渐由「寄工」转为世袭奴籍：1640年有鞭笞奴隶判例，1662年定子女随母籍为奴，1667年定受洗亦不免劳役。学界估计16—19世纪横渡大西洋运走的非洲人约一千一二百万，开首的船实即如此小船，非一处可算清。", "figures": ["1619年至詹姆斯敦之非洲人（多安哥拉之金贝杜者）", "（其买主）弗吉尼亚之垦户", "（纪其事者）伦敦之公司通信"], "place": "詹姆斯敦（今美国弗吉尼亚）", "state": "英格兰弗吉尼亚公司殖民地", "sources": ["1619—1624年弗吉尼亚之函件与户口册、1624年《殖民地产状之记》", "《剑桥美国早期史》第一卷、德国尔达《切萨皮克与奴隶制之起》"], "tags": ["大西洋奴隶贸易", "烟草", "议会"]}, "related": []},
  {"id": "world--1620--m01", "track": "world", "year": 1620, "yearApprox": false, "dim": "military", "weight": 3, "title": "白山之战，波希米亚平定", "summary": "一日而决胜负，一邦选举权与信仰随之俱变。", "detail": {"background": "等级军与皇帝军在波希米亚西部对峙；巴伐利亚马克西米利安与萨克森选帝侯入皇帝一方，腓特烈五世的援兵不至，布拉格守军之心已散。", "process": "1620年11月8日，战于城西白山（白塔）之下：皇帝军与天主教联盟军二万余，当等级军万三千，中有农人；布奎瓦的骑兵自侧翼包抄冲击，新教军自乱，两天后布拉格开门。1621年6月21日，27名等级首领与将士在老城广场受刑，其头悬于桥塔示众十年。", "impact": "1621年邦法尽改，选王之权归于世袭，波希米亚由等级之邦变为哈布斯堡的一省；流亡数千户（所谓「大迁移」）北走萨克森、东入波兰，其教会产业归耶稣会。德语与天主教在此邦推行一百六十年，至1781年的宽容诏才缓和。", "figures": ["斐迪南二世", "（其将）布奎瓦、蒂利", "（败者）冬王腓德烈五世"], "place": "白山（布拉格西郊）", "state": "波希米亚王国、哈布斯堡君主国", "sources": ["1621年布拉格刑讯与斩首之纪、比良之等级史稿（后世传本）", "《剑桥三十年战争史》、《波希米亚之白色山研究》"], "tags": ["战役", "流亡", "反改革"]}, "related": []},
  {"id": "world--1626--d01", "track": "world", "year": 1626, "yearApprox": false, "dim": "disaster", "weight": 3, "title": "京师王恭厂灾", "summary": "雷火发于药局，举城几尽失衣。", "detail": {"background": "京师西南的王恭厂为工部的火药局，多次受灾多次迁徙；天启大造时工匠杂处，储药数万石于民房旁边。", "process": "天启六年五月初六日巳时（1626年6月17日），厂一带震动如雷，声从西南传东北，自顺成门至朝天宫、租房之街约二里多；木石人畜抛空复坠，死者有「二万余」之说见于邸报，然其数出自传闻，学界认为数千到万余较为接近。官私记载皆言所遇仆役与死者多半失了衣带。", "impact": "工部与厂官议罪，匠役调补；朝野以「天心之谴」约束议论，魏忠贤借此排斥异己，言官的章疏纷纷而上。此灾成因后世或以火药爆炸为主说，或兼及地气、雷火的异常，迄无定论；其为明末京师三大案之一。", "figures": ["明熹宗（天启帝）", "（其权）魏忠贤", "（奏报之官）工部与科道之臣"], "place": "京师（今北京）西南", "state": "明", "sources": ["《天变邸抄》、《明熹宗实录》天启六年五月之条与当时疏稿", "《中国历代自然灾害年表》、邓拓《王恭厂的爆炸》"], "tags": ["爆炸", "京师", "灾异"]}, "related": ["cn--1626--d01"]},
  {"id": "world--1628--s01", "track": "world", "year": 1628, "yearApprox": false, "dim": "science", "weight": 3, "title": "哈维论心与血之运动", "summary": "以计量定心为泵，血液循环之说自兹始。", "detail": {"background": "医家自盖伦以来说血由肝制造、随脉消耗，两套管道各走各路；帕多瓦人法布里修斯验出静脉瓣膜像开关之门，其弟子哈维在帕多瓦学解剖，后回伦敦做御医。", "process": "1628年法兰克福刊行《动物之心之运动与血液之论》，短得不到一百页：以结扎验出脉血只往一个方向走，以瓣膜定其流向，视心室收缩为推送的力量；又计量一次收缩的容量和次数，推出一个时辰心送出的血远超全身所有，遂断定血自心出、沿脉走、再归于经，乃圆形循环。", "impact": "生命之学自此用数量和实验判断；他未见脉与经末梢相连，至1661年马尔比基用望远镜看到微细的管，此说才完备。书刊行后医家争了几十年，英国内战时御医随国王走，其学也因此东传荷兰莱顿。", "figures": ["威廉·哈维", "（其师）法布里修斯·希尔达努斯", "（其护主）查理一世"], "place": "伦敦；法兰克福刊书", "state": "英格兰王国", "sources": ["1628年法兰克福原本与哈维之手稿、讲录", "《哈维与循环之学说》（伍利特等校释）、《剑桥科学史》"], "tags": ["生理", "循环", "计量"]}, "related": []},
  {"id": "world--1633--c01", "track": "world", "year": 1633, "yearApprox": false, "dim": "culture", "weight": 3, "title": "伽利略受审于罗马", "summary": "《对话》刊行之后，跪而收回己说。", "detail": {"background": "1616年圣座已判日心说为虚妄，告诫伽利略不得「持与辩护」；后来他在佛罗伦萨用意大利语写成三人四日的讨论，1632年刊行《关于两世界之对话》，得到审查许可，同时又讥讽旧说迟钝。", "process": "1633年4月至6月，异端裁判所开庭多次审讯，加「持妄说、疑其不诚」罪名；6月22日在罗马密涅瓦寺前跪读悔过的言辞，随后改判软禁，1634年起居限于阿恰约宅中。1633年后其书进《禁书目录》，1638年《新对话》在莱顿私刊，晚年幽居（1642年去世，1737年遗骨移佛罗伦萨圣殿）。", "impact": "此案令天主教界谈天的人避开「地动」名称，照用其算法，耶稣会天文学遂专心做观测与术数；史家自十九世纪以来争这桩案子，有人说教会与个人冲突，有人说教宗乌尔班八世怨气与欧洲战事（1631年马格德堡屠城、1630年瑞典入德）交织所致，至1979—1992年教宗又重新讨论过。", "figures": ["伽利略·伽利雷", "乌尔班八世（巴贝里尼）", "（审之者）裁判所之枢机"], "place": "罗马、阿恰约", "state": "教宗国、托斯卡纳大公国", "sources": ["1633年审案记录（19世纪后辑刊）、悔过辞与1632年《对话》原本", "费诺基亚罗《伽利略受审文件》、比安卡·阿夫扎利《伽利略之狱与教廷之政》"], "tags": ["裁判", "日心说", "禁书"]}, "related": []},
  {"id": "world--1639--i01", "track": "world", "year": 1639, "yearApprox": false, "dim": "institution", "weight": 3, "title": "最后一次锁国令定于长崎", "summary": "葡国船拒于海门之外，通商港口仅余一隅。", "detail": {"background": "宽永十四至十五年的岛原、天草反叛（1637—1638，教民与失业农人一起起事）震动江户，幕府认为西洋宗教为祸乱之本；长崎出岛已经筑成，葡商屡次请求再来。", "process": "1639年（宽永十六年）七月下达第五次锁国令，葡船自此不许入港，当地葡人及混血者数千人或被逐或遇害；1641年荷兰商馆自平户迁往出岛，唐人船也限定在长崎，只许定额船数。对马朝鲜、萨摩琉球、松前虾夷三个口子仍各自守着自己的市场。", "impact": "「四口之制」由此形成：幕府独占外交与商报，欧洲人不得进入国内，船进来就焚其帆锚为记（1639—1854）。荷兰商馆日志与「风说书」成一道情报的门，医学、算学由长崎传入（兰学），18世纪中叶以后国内知欧洲的人都走这条路。", "figures": ["德川家光", "（其老中）土井利胜、水野忠清", "（长崎之司）长崎奉行"], "place": "长崎、出岛、江户", "state": "江户幕府", "sources": ["宽永十六年之幕府令文、《德川实纪》与《外国事始文档》", "荷兰商馆之日志（后辑本）、《锁国之制与兰学》"], "tags": ["锁国", "长崎", "出岛"]}, "related": []},
  {"id": "world--1640--p01", "track": "world", "year": 1640, "yearApprox": false, "dim": "politics", "weight": 3, "title": "葡萄牙复国，布拉干萨公爵称王", "summary": "六十年共一君，一朝断绝，巴西局面随之改变。", "detail": {"background": "1580年后葡萄牙的王冠归到西班牙菲利佩二世那里，此种共治以兵费与赋税相催逼；1640年加泰罗尼亚也反，马德里的军队两头顾不上，里斯本等级与商人、下级贵族谋划自立。", "process": "1640年12月1日，四十人的贵族党入利维亚德尔宫，杀王后近臣秘书巴斯孔塞洛斯；八天后拥立布拉干萨公爵若昂为王，称若昂四世。1641年与法国结盟，同年压服北地党羽；耶稣会士因为不肯宣誓，1641年被逐出葡萄牙境内。", "impact": "葡、西之争至1668年里斯本条约始定；其间荷兰人占据巴西东北部（1630—1654）为葡人复取，1654年累西腓降时许其犹太居民离开。布拉干萨王朝因1661年英国婚姻得孟买与锡兰的利益，巴西的糖与后来的金遂为王国支柱。", "figures": ["若昂四世", "（其杀者）钦差秘书巴斯孔塞洛斯", "（其谋）托伊德与四十人之党"], "place": "里斯本", "state": "葡萄牙王国、西班牙君主国", "sources": ["1640—1641年之记事与盟约文本、《里斯本编年之续》", "《剑桥拉丁美洲史》第二卷、《葡萄牙复国之战争研究》"], "tags": ["复国", "共主之乱", "盟约"]}, "related": []},
  {"id": "world--1642--m01", "track": "world", "year": 1642, "yearApprox": false, "dim": "military", "weight": 3, "title": "英吉利内战开始", "summary": "国王竖旗于诺丁汉，议会军自伦敦起。", "detail": {"background": "1629至1640年国王不召议会独自统治，船钱征到内陆；1640年短期、长期议会相继而起，1641年处死斯特拉福德、爱尔兰的乱事起来，这年冬天《大抗议书》呈上。1642年1月国王带兵进下院要抓五个议员却没抓到，就离开京师。", "process": "1642年6月议会提出《十九项提议》，要求兵权与官职的同意权，国王拒绝；8月22日建旗于诺丁汉，10月23日埃奇希尔一战两军各自说胜，王后的军队得牛津。议会不久任埃塞克斯为将，1643年苏格兰、英格兰盟约成。", "impact": "内战三起（1642—1646、1648、1649—1651），1645年纳斯比的胜利、新军制度建立、1649年1月国王被杀、1653年护政府，都由此路而来；这场争执又定下后来英国王权与议会的界线，1689年《权利法案》即其结局。", "figures": ["查理一世", "（其敌之将）第二埃塞克斯伯爵", "（五议员之一）皮姆"], "place": "诺丁汉、埃奇希尔、牛津", "state": "英格兰王国", "sources": ["《长期议会之议事录》、1642年之王与议会之文告与新闻书", "《剑桥英国内战史》、里斯《三王国之战争》"], "tags": ["内战", "议会", "王权"]}, "related": []},
  {"id": "world--1642--x01", "track": "world", "year": 1642, "yearApprox": false, "dim": "explore", "weight": 2, "title": "塔斯曼环行南方海域", "summary": "两条船南行，见新地未能登岸。", "detail": {"background": "巴达维亚总督与议会替公司提出「未知南方大陆」之问；1642年8月，令塔斯曼带两艘小船南行，去找传闻中的南方土地与可能的商货。", "process": "1642年11月24日见一大岛，名之「范迪门之地」（今塔斯马尼亚）；东行经其南之海，12月13日见一长岛西岸（今新西兰南岛），18日入一海湾（今黄金湾）遇当地人，船上四人被杀而退，未能取名，只写上「窃贼之湾」。1644年再航，绕其北岸画出范迪门与澳洲间的海。", "impact": "两次航行切断南方大陆与新西兰相连之说，定下澳洲南岸与北岸的大致形状；公司因所见无商货之利，遂止探查，荷兰海图留其形状，英国人则晚来一个世纪。塔斯曼之名留在这些地方、这片海与诸岛上。", "figures": ["阿贝尔·扬松·塔斯曼", "（其副）维姆贝森", "（命其行者）总督范迪门"], "place": "范迪门之地、新西兰、南大洋", "state": "荷兰东印度公司（巴达维亚）", "sources": ["塔斯曼航海日志与1644年之图（海牙国家档案）、公司之决议录", "《荷兰之澳洲探查志》、锐克特《塔斯曼之航》"], "tags": ["探查", "海图", "南大洋"]}, "related": []},
  {"id": "world--1644--p01", "track": "world", "year": 1644, "yearApprox": false, "dim": "politics", "weight": 5, "title": "明亡与清军入关", "summary": "京师一破，三百年明朝告终，山海关同时洞开。", "detail": {"background": "崇祯年间，内部乱事与辽东战事同时紧迫，辽饷、剿饷、练饷加在北方百姓身上，小冰期的旱灾蝗灾连年不断；1642—1643年松锦之战明军主力尽丧，关外只剩宁远一座城。", "process": "1644年（崇祯十七年）三月十九日李自成入京师，庄烈帝缢于煤山，在位十七年；山海关的吴三桂先降顺，接着向摄政王多尔衮求援。四月二十二日一片石之战，顺军溃，李自成向西走，五月清军入京师，八月移其先帝牌位于太庙，即位礼成。剃发令下（1645年六月），江阴、嘉定围城屠杀遂起。", "impact": "南明诸王（弘光、隆武、绍武、永历）与夔东、三藩抵抗延至1683年才结束。明清交替时兵灾、瘟疫与饥荒并起，学界估计人口损失在千万等级，可两朝户口数字不全，诸说出入极大。清朝承明制度（内阁、六部、科举），又加旗地、逃人法与文字狱；欧洲来者（汤若望等）在顺治朝参与修历，西学因此有了一道门。", "figures": ["明思宗（崇祯帝）", "李自成", "吴三桂", "（清之摄政）和硕睿亲王多尔衮"], "place": "京师、山海关", "state": "明、大顺、清", "sources": ["《明史》与《明季北略》、《世祖章皇帝实录》、吴伟业之纪事", "《剑桥中国明代史》下卷、《剑桥中国清代史》上卷前编、顾诚《南明史》"], "tags": ["鼎革", "入关", "小冰期"]}, "related": ["cn--1644--p01", "cn--1644--m01", "cn--1643--p01"]},
  {"id": "world--1645--m01", "track": "world", "year": 1645, "yearApprox": false, "dim": "military", "weight": 3, "title": "扬州屠城与南都倾覆", "summary": "一城连日流血，弘光朝廷就此终结。", "detail": {"background": "1644年五月清军入京师，弘光即位于南京，江北四镇的军队骄横，且互相攻击，马士英与史可法谋划不合，江防已空。", "process": "1645年四月，豫亲王多铎以红夷炮攻城，二十四日扬州陷，守督史可法不屈而死；自此城里兵士「许自由之」，屠杀连日。五月下剃发令，江阴、嘉定因抗令被围；十五日南京开门降，弘光不久于芜湖被俘。", "impact": "《扬州十日记》（王秀楚）记八日事，所说的数十万，学界多认为数字夸大，今人用城中户籍与焚尸数字推算，认为应当按万来算，可出入终究定不下来。自此南明只剩浙、闽、粤几个小朝廷；江南士人拿文字狱互相告诫，清初考据的谨慎有不得已处。", "figures": ["史可法", "（攻者之将）豫亲王多铎", "（纪事者）王秀楚"], "place": "扬州、江阴、嘉定、南京", "state": "清、南明弘光", "sources": ["《明季南略》、《扬州十日记》与《清世祖实录》顺治二年之条", "《剑桥中国清代史》、顾诚《南明史》"], "tags": ["屠城", "剃发", "南明"]}, "related": ["cn--1645--m01"]},
  {"id": "world--1648--p01", "track": "world", "year": 1648, "yearApprox": false, "dim": "politics", "weight": 5, "title": "威斯特伐利亚和约", "summary": "两城同时议事，三十年战乱至此而定，各邦权力始有界。", "detail": {"background": "自1618年布拉格掷窗，战火在德意志延烧三十年，城邑成为废墟；1641年才有和议之声，其后法国、瑞典各凭自己的胜利取地，商议因此长期停滞，与会的人又经数年才定。", "process": "1648年10月24日交换明斯特与奥斯纳布吕克两城条约（合称威斯特伐利亚之和）：定加尔文教与路德教同受1555年奥格斯堡条约保护，教会财产的判定以1624年为准；诸侯得领土权与结盟权，帝国议会、永久选举与帝国法庭制度因此定下；瑞典得西波美拉尼亚等地，法国得梅斯、图勒、凡尔登与阿尔萨斯的权利。同年明斯特条约中，西班牙承认荷兰联省自立，八十年战争亦终。", "impact": "这个条约是近代欧洲国际秩序的起点：常驻使节、条约按文义约束、用会议划定疆界，都由此立例；后世所说「主权国家互不统属」的制度，学者多追溯到它，也有人认为此说夸大实际。德意志长期分裂、法兰西霸权与瑞典北向观望，都在这次定下格局。", "figures": ["（帝之使）特劳特曼松", "（法之使）阿瓦勒公爵", "（瑞之使）勒克尔尤"], "place": "明斯特、奥斯纳布吕克", "state": "神圣罗马帝国、法兰西、瑞典、荷兰联省", "sources": ["1648年二约之文本（后辑刊为和议文书集）、诸使之关系书与日记", "《剑桥三十年战争史》、威尔逊《1648年：三十年战争与威斯特伐利亚的欧洲》"], "tags": ["和约", "主权", "宗教并立"]}, "related": []},
  {"id": "world--1648--m01", "track": "world", "year": 1648, "yearApprox": false, "dim": "military", "weight": 3, "title": "哥萨克反叛与基辅归俄", "summary": "军队起于第聂伯，东欧边界因而重划。", "detail": {"background": "波兰统治乌克兰，以租佃与教会财产相逼迫，哥萨克因为不得户籍、权力被削而怨恨，泽波罗基寨子自成一伙；基辅东正教兄弟会又厌恶1596年布列斯特的合并。", "process": "1648年春，赫梅尔尼茨基率哥萨克在扎波罗热起事，夏天在若夫尼水与科尔松连败波兰军，克里米亚鞑靼做他的援军；1649年兹博里夫之约答应给他三万哥萨克户籍，1651年贝列斯特奇科战败后形势又紧。1654年1月佩列亚斯拉夫议会受沙皇保护，俄军于是进入；战事延到1667年安德鲁索沃之约，左岸与基辅归俄，1686年俄波「永久和平」再次确认。", "impact": "这次反叛打开东欧三百年的局面：波兰自此失去东南边界，哥萨克寨子成为俄、波、土、鞑靼争夺之地；第聂伯东西两岸分为二，定下后来乌克兰族群界线。学界估计1648—1657年间兵、屠与疫亡数十万，数字至今还在争。", "figures": ["（其长）博赫丹·赫梅尔尼茨基", "（其敌之君）王扬二世卡齐米日", "（其所依）沙皇阿列克谢"], "place": "第聂伯河流域、基辅、佩列亚斯拉夫", "state": "波兰王冠领、哥萨克之军、俄罗斯之国", "sources": ["1648—1659年之军报与哥萨克之编年记、1654年之约文", "《剑桥乌克兰史》、亚伯拉罕姆森《赫梅尔尼茨基之反》"], "tags": ["哥萨克", "边地", "东欧"]}, "related": []},
  {"id": "world--1651--e01", "track": "world", "year": 1651, "yearApprox": false, "dim": "economy", "weight": 3, "title": "英吉利航海条例", "summary": "一纸文书闭其港口，荷兰海权自此动摇。", "detail": {"background": "内战之后，议会中有人想振兴本国航运与渔税；北美烟、糖多由荷兰船转运，伦敦与朴次茅斯船主不满。1651年3月荷兰议会自废既往的航海禁令，正以自由为利，英国条例随即下来。", "process": "1651年10月9日下达航海条例：凡亚、非、美货物不用英国船不得进入英吉利和其殖民地，欧洲的货也要原产国或英国船；1660、1663年重订并推广到种植园，糖、烟和后来的货必须先运回本国。荷兰人损失最重，1652—1654、1665—1667、1672—1674三次与英国争海。", "impact": "这个条例不只是商法：它以殖民地为供原料、收货物的圈子，行了两百年；三次战争后荷兰海权渐分给英国，1664年英人取新阿姆斯特丹（改名纽约）实由此路而来。学者论「重商」之制，多拿这道条例做例子。", "figures": ["（其时之主政）奥利弗·克伦威尔", "（其议之倡）伦敦之船主与东印度之商", "（其敌）荷兰之提督特隆普"], "place": "伦敦、威斯敏斯特", "state": "英格兰共和国、荷兰联省", "sources": ["1651年10月之国会案文与1660、1663年之续案、荷兰议会之决议录", "《剑桥英帝国史》第一卷、《航海法与英荷之争研究》"], "tags": ["重商", "海权", "殖民贸易"]}, "related": []},
  {"id": "world--1662--m01", "track": "world", "year": 1662, "yearApprox": false, "dim": "military", "weight": 4, "title": "郑成功取大员，荷人退走", "summary": "围城九个月，东岸荷兰一城失守。", "detail": {"background": "荷兰人以大员（今台南）作北岸转口贸易的市场，换中国来的丝、糖和鹿皮，向垦户征税；1650年代郑氏以金门、厦门为基地，与日本、吕宋通商，同公司互为仇敌，军费靠海商。1661年定计取台湾作根本之地。", "process": "1661年四月二十九日郑军自鹿耳门水浅的地方入台江，围普罗文西亚城，断其水源；荷兰守将揆一等盼巴达维亚的援兵不至，1662年二月一日献热兰遮城降，荷兰官民三百余人乘船东归。五月郑氏去世，其子郑经代之。", "impact": "此为欧洲人在东亚拓土的首次大退却，公司图籍自此舍福尔摩沙而专注爪哇；明郑以台湾为军府，贩糖、鹿皮与丝至日本、爪哇，闽南开垦者随之东渡（人数学界难定）。1683年施琅取澎湖，郑克塽降，清朝始设台湾府，隶福建省。", "figures": ["郑成功（朱成功）", "（荷之守将）揆一", "（其后之取台者）施琅"], "place": "大员、赤崁、热兰遮（今台湾台南）", "state": "明郑、荷兰东印度公司", "sources": ["揆一《被围之福尔摩沙》（1662年后刊）与公司之决议录、《先王实录》与郑氏之档", "《剑桥中国清代史》、《荷兰人在台湾》之译本与近人研究"], "tags": ["台湾", "热兰遮", "海商"]}, "related": []},
  {"id": "world--1665--d01", "track": "world", "year": 1665, "yearApprox": false, "dim": "disaster", "weight": 3, "title": "伦敦大疫与第二年大火", "summary": "一年瘟疫，全城死者三四成，翌年大火尽毁旧城。", "detail": {"background": "瘟疫自1603年后在伦敦多次发作，教区死亡表每年记下人数；1664年冬起于圣贾尔斯堂市，医家和富人都无准备，城中法令只到焚香与闭门查验为止。", "process": "1665年3月起瘟疫大行，夏秋至极点，到1666年2月始息；据当时死亡表与近人校勘，都城与附近城镇死了约六万八千到十万人，几乎占全城的三四成（学界估计，户籍不全故出入很大）。国王与议会避往牛津，大学停课（牛顿因此回伍尔索普两年）。1666年9月2日至5日，布丁巷的火延烧四天，城中住屋二万余、教堂八十九座与圣保罗座堂一并烧毁，而登册死者极少。", "impact": "瘟疫与火灾连着改变伦敦的形貌：雷恩新街道与圣保罗新堂、砖石之禁与街道加宽，都于1666年后的法令中完成；商人东迁，这一带后来成为1694年后金融区的底子。笛福《大疫年之记》成为后世写灾难的文字，可其中数字出自事后追记，不能全信。", "figures": ["（其时之王）查理二世", "（记其事）塞缪尔·佩皮斯", "（绘新城者）克里斯托弗·雷恩"], "place": "伦敦、牛津", "state": "英格兰王国", "sources": ["伦敦教区之死亡表（后世辑刊本）、佩皮斯之日记与市之案牍", "《大疫年之记》与其近人之校释、斯马威《伦敦之火与疫》"], "tags": ["瘟疫", "火灾", "都市重建"]}, "related": []},
  {"id": "world--1673--p01", "track": "world", "year": 1673, "yearApprox": false, "dim": "politics", "weight": 3, "title": "三藩反叛与清朝长期用兵", "summary": "一令撤藩，引出八年战争，南方再困。", "detail": {"background": "清初让吴三桂、尚可喜、耿精忠分镇云南、广东、福建，汉军兵费依靠南方赋税；康熙亲政后议论撤藩，朝臣意见不一，不安的局面就显出来了。", "process": "1673年（康熙十二年）冬，吴三桂在云南反，称「天下都招讨兵马大元帅」；1674年耿精忠在福建响应，尚可喜子尚之信继反，陕西王辅臣亦叛，势最大时几至半壁天下。清朝以八旗与绿营分路进兵，1676年陕西、福建稍定，1678年吴三桂称帝于衡州，不久死，1681年清军入昆明，乱始平。", "impact": "八年战事，湖南、四川、江西百姓再遭殃，学界认为兵、疫与饥荒的死亡难以合计，只知日后清廷减免湖广、四川赋税以招垦。三藩平定后，清朝取云南而改土归流的议论渐行；1683年因平定台湾，海禁稍松，闽、粤商船遂兴。", "figures": ["吴三桂", "（清之君）康熙帝", "（其将）图海、赵良栋"], "place": "云南、湖南、福建、陕西", "state": "清", "sources": ["《清圣祖实录》康熙十二年至二十一年之条、《平定三逆方略》", "《剑桥中国清代史》上卷、近人《三藩之役研究》"], "tags": ["三藩", "削藩", "清初兵事"]}, "related": ["cn--1673--p01", "cn--1678--p01"]},
  {"id": "world--1676--s01", "track": "world", "year": 1676, "yearApprox": false, "dim": "science", "weight": 2, "title": "微生物见于单片镜下", "summary": "一个商人磨镜片，肉眼不见之微生物始见天日。", "detail": {"background": "雷文虎克是代尔夫特布商兼看门小吏，自1660年代起磨单片镜消遣；那时复式镜尚不精，学者多以其高倍率为无用的巧技。", "process": "1674年起他用单镜看池水里微小的动东西，称之为「微物」；1676年9月至1677年陆续写信给伦敦皇家学会，说牙垢中动虫、精虫与红血的形状，镜放大到二百倍以上。1684年学会遣人至代尔夫特验其器具与本人，方始相信。", "impact": "自此生物的微小世界得入生命科学；其说长期只算玩物巧技，未成致病之论，至十九世纪巴斯德、科赫门徒以镜与实验相接方有用处。雷文虎克一生寄信数百封，多在学会档案中。", "figures": ["安东尼·雷文虎克", "（验之者）皇家学会之使", "（其书之受）伦敦之秘书"], "place": "代尔夫特", "state": "荷兰联省", "sources": ["雷文虎克寄皇家学会之书札（《哲学汇刊》十七世纪后期载其文）、学会之验录", "多布德尔《雷文虎克与其微物世界》、《显微术之史》"], "tags": ["显微", "博物", "皇家学会"]}, "related": []},
  {"id": "world--1683--m01", "track": "world", "year": 1683, "yearApprox": false, "dim": "military", "weight": 5, "title": "维也纳围攻与奥斯曼退却", "summary": "围城九个月，一战而大势逆转。", "detail": {"background": "1683年春，大维齐尔卡拉·穆斯塔法巴夏率军自阿德里安堡北行，号称十余万（这个数出自获胜方的报告，学界认为过高，实际在十万上下）；奥皇利奥波德一世与波兰王扬三世先约定互援，维也纳守军只有一万余，加上市民群众。", "process": "1683年7月7日至9月12日围攻维也纳：城墙多次被破而围军不得入城，9月12日洛林的卡尔与波兰翼骑兵自卡伦贝格山下冲其营寨，获辎重、炮与金帐乃回师。自此「神圣同盟」连取布达（1686）、贝尔格莱德（1688），1699年卡尔洛维茨之约，奥斯曼始弃匈牙利、斯拉沃尼亚与特兰西瓦尼亚。", "impact": "此为奥斯曼陆权向西扩张的止点，亦哈布斯堡转向多瑙河腹地的开端：此后一百五十年，奥、俄、土格局由维也纳政策决定，巴尔干百姓因此屡起屡败。维也纳咖啡馆相传兴起于围城之后，学者以为后世的附会。", "figures": ["（围城之帅）卡拉·穆斯塔法巴夏", "（援军之帅）洛林的卡尔五世", "（其盟）波兰王扬三世索别斯基"], "place": "维也纳、卡伦贝格", "state": "哈布斯堡君主国、奥斯曼帝国、波兰立陶宛、俄罗斯", "sources": ["1683年之城守记与军报、营中所得之书（后辑刊）、1699年约文", "《剑桥奥斯曼史》、近人《维也纳之围与1683年之局》"], "tags": ["围城", "奥斯曼", "哈布斯堡"]}, "related": []},
  {"id": "world--1685--c01", "track": "world", "year": 1685, "yearApprox": false, "dim": "culture", "weight": 4, "title": "南特敕令撤销，教民出逃", "summary": "一诏废百年敕令，工匠学者北迁。", "detail": {"background": "路易十四晚年以敬虔自任，曼特农夫人和她的礼臣影响着他；1681年起驻兵进教民家（所谓「驻兵之暴」），拆掉他们的教堂、禁止其行业，教民户籍年年削减。", "process": "1685年10月18日下枫丹白露诏，尽撤1598年南特敕令：不许礼拜，教堂或拆或归天主教会，传教士限四个月内离国，百姓出走亦有禁令；可禁令虽严，沿海百姓仍在夜里出来渡海。学界估计1685—1700年出亡十五万到二十五万（常引的数字约二十万），其中多织工、针匠、书商与兵。", "impact": "勃兰登堡选帝侯在柏林「法国街」接纳来者，当地织业因此兴起；英、荷与德意志诸邦得其工匠手艺，好望角亦受其农人（1688年的船）。塞文内山1702—1704年的卡米萨尔之乱即为后患。一百年后1787年宽容诏始许其有民事户籍，1789年后方完全恢复权利。", "figures": ["路易十四", "（其谋之臣）卢福瓦侯爵与其子沙特拉", "（受其民者）勃兰登堡选帝腓特烈三世"], "place": "枫丹白露、巴黎；柏林、伦敦、开普", "state": "法兰西王国", "sources": ["1685年10月之诏文本、各省之执行文书与出亡之档", "《剑桥近代早期欧洲史》、近人《南特之敕的撤与教民出走研究》"], "tags": ["撤敕", "出亡", "手工业迁徙"]}, "related": []},
  {"id": "world--1687--s01", "track": "world", "year": 1687, "yearApprox": false, "dim": "science", "weight": 5, "title": "牛顿《自然原理》刊于伦敦", "summary": "三卷定后，天地运动归于一套算法。", "detail": {"background": "1679至1684年间，惠更斯、胡克与雷恩等已在伦敦讨论引力反比；1684年哈雷到剑桥问「在引力之下线是什么形状」，牛顿答以椭圆，遂写成三篇稿并续为大著。", "process": "1687年7月5日皇家学会付印《自然之哲学之数学原理》三卷，哈雷时任秘书，主持校勘与刻资：先定义量、时、空间与力，立运动三律，以几何法证开普勒的比例，推广为万有引力说；并测地球偏扁、潮汐的由来、月球之差，附彗星轨道。其完整解答至1713年二版、1726年三版方备。", "impact": "自此天算与力学合为一门学问，欧陆诸大学自1690年代后分头接受（法国、意大利以笛卡尔涡说相抗，1730年代后牛顿的学问才定下来）；其法亦供航海需要与后来之用。至于引力何以存在，牛顿自己说「不作虚构的假设」，莱布尼茨责其以隐秘性质解释，争论延到十八世纪。", "figures": ["艾萨克·牛顿", "（其刊书之助）埃德蒙·哈雷", "（其诤敌）莱布尼茨"], "place": "伦敦、剑桥", "state": "英格兰王国", "sources": ["1687年原本与哈雷、牛顿之通信、皇家学会之议事录", "科恩与惠特曼校译《原理》、韦斯特福尔《永不安息的天才》"], "tags": ["力学", "引力", "皇家学会"]}, "related": []},
  {"id": "world--1689--p01", "track": "world", "year": 1689, "yearApprox": false, "dim": "politics", "weight": 5, "title": "权利法案成于伦敦", "summary": "不流血而废一王，王权自此受议会条款约束。", "detail": {"background": "1687至1688年雅各布二世用天主教官员与「赦免之诏」触怒国教及两党，七位主教下狱而审判无罪；诺丁汉等七人的请求书北上至海牙，奥伦治的妻子玛丽也继承她的地位。", "process": "1688年11月5日威廉的船进托贝，雅各布兵溃散不战，12月11日国王弃玺印出逃；1689年2月议会按「王位虚悬」之义立威廉与玛丽共同主政，4月一同加冠。12月16日《权利宣言》写入法律（即权利法案）：国王不得停止法律、不得免议会定的税、平时不得养常备兵，臣民有请愿和持兵器的权利，议员有讨论事务的言论自由，亦不许复罗马教会旧状。", "impact": "这个法案与1694年「三年议会之法」、1701年「王位传承之法」共建立宪体制：政事渐归阁臣手中，财权归下院，英格兰银行的设立（1694）与国债制度因而立；对法九十年兵争（1689—1763）也由此开局。爱尔兰经1689—1691年战事（博因河与利默里克围城）另成一局，北美殖民地因此逐去其官。", "figures": ["（其新王）奥伦治之威廉三世与玛丽二世", "（其废者）雅各布二世", "（草其宣言）哈尔法克斯"], "place": "伦敦、威斯敏斯特、托贝", "state": "英格兰王国（后为大不列颠）", "sources": ["1689年《权利令》文本与两院之议事录、1688—1689年之通信集", "《剑桥近代早期欧洲史》、米勒《光荣之革与不列颠之变》"], "tags": ["光荣之革", "议会", "立宪"]}, "related": []},
  {"id": "world--1689--i01", "track": "world", "year": 1689, "yearApprox": false, "dim": "institution", "weight": 4, "title": "尼布楚条约与中俄定界", "summary": "一约定外兴安岭之界，两国始以文书划界。", "detail": {"background": "自1640年代俄人东进至雅克萨、尼布楚，向阿尔巴津索贡；清朝连年征讨并围雅克萨（1685、1686）抵挡，俄方遣使东来说界，当时噶尔丹正在北边兴起。", "process": "1689年9月7日（康熙二十八年七月二十四日）在尼布楚城，索额图率清使与戈洛文带俄使划定边界：以格尔必齐河、外兴安岭为界，雅克萨的屯垦拆毁，越界打猎与逃人皆有禁令；约文以拉丁文为正，另有满、汉文本，立界碑事议定后再行。1727年恰克图条约续定中段边界。", "impact": "此为清朝与欧洲国家第一次用条约定界：约文和后来立的碑是两百年间交涉的依据；拉丁本与满、汉文本字义差别，学界至今还在争其「不改」真意。北边安定之后，清朝能专心对付噶尔丹，喀尔喀归附与乌兰布通之战（1690）都顺这条路向南。", "figures": ["（清之使）索额图", "（俄之使）费奥多尔·戈洛文", "（其间之译）耶稣会士张诚、徐日升"], "place": "尼布楚（今俄罗斯涅尔琴斯克）", "state": "清、俄罗斯国", "sources": ["拉丁文约文原件（俄档）、《清圣祖实录》康熙二十八年之条与满文本", "近人《中俄尼布楚条约研究》、《早期中俄之交涉》"], "tags": ["条约", "北界", "使节"]}, "related": ["cn--1689--p01"]},
  {"id": "world--1690--m01", "track": "world", "year": 1690, "yearApprox": false, "dim": "military", "weight": 3, "title": "博因河之役与威廉定爱尔兰", "summary": "河上一日定北岛之归属，废王出走，新教之治由此。", "detail": {"background": "1689年雅各布二世到爱尔兰，恃法国的兵与天主教诸城之力，四月至七月围都柏林不克。", "process": "1690年8月12日（旧历7月1日）两军遇于德罗赫达南的博因河，威廉以三万余人渡河陷阵，雅各布的兵溃，当夜走法国。1691年9月利默里克以《礼费特之约》降，其兵万余随船赴法，谓之野鸭之飞。", "impact": "战后爱尔兰议会行罚没之令，土地多归新教徒，1695年后连颁《刑法》以限天主教徒；博因河与奥赫里姆两役遂为北岛新治之基。海上比奇角一役法国胜之，威廉的兵力仍分于大陆。", "figures": ["（其新王）奥伦治之威廉三世", "（其废者）雅各布二世", "（法之将）拉乌克斯坦因"], "place": "博因河（今爱尔兰劳斯郡，德罗赫达南）", "state": "英格兰王国、爱尔兰", "sources": ["1690年之军报与刊于伦敦的《博因河之役记》、礼费特约文之抄本", "《剑桥爱尔兰史》第四卷、近人《威廉三世之战》"], "tags": ["爱尔兰", "王位之争", "战役"]}, "related": ["world--1689--p01"]},
  {"id": "world--1694--i01", "track": "world", "year": 1694, "yearApprox": false, "dim": "institution", "weight": 5, "title": "英格兰银行特许与战争借款", "summary": "合股献款于王，票与国债自此同行，财权重归下院。", "detail": {"background": "九年战争（1689—1697）岁费数百万，1693年的百万借款以终身之息招股，国债骤长而信用未立；帕特森与孟塔古议以合股之银献于官。", "process": "1694年7月27日凭《船税之法》发出特许状：认股百二十万镑，官岁给息八厘、费四千镑，其票可行有司之支付；其期原定十年，1708年展换。", "impact": "自此政府的短欠化为以灶税、酒税拨底的长年国债，债券可读可质，市面遂成一路；议会的岁察与同年《三年议会之法》相挟，财权归在下院。论者以英格兰与法兰西百年胜负分于此等财政之制。", "figures": ["（其议之臣）查尔斯·孟塔古", "（其谋）威廉·帕特森", "（同时之理财）尼古拉斯·巴本"], "place": "伦敦（初借商会之厅，后入尼德街）", "state": "英格兰王国", "sources": ["1694年特许状之文本与两院之议事录", "克拉珀姆《英格兰银行史》第一卷、《剑桥欧洲经济史》"], "tags": ["英格兰银行", "国债", "财政之革"]}, "related": ["world--1689--p01"]},
  {"id": "world--1696--e01", "track": "world", "year": 1696, "yearApprox": false, "dim": "economy", "weight": 2, "title": "英国重铸银币与剪边之弊", "summary": "旧钱回炉而新钱加齿，币稍定而市先困。", "detail": {"background": "复币以来用槌打的银钱，边沿易被剪削，1690年代市上之钱十去其重二三；兵费与歉岁相激，物价、汇兑与税入皆乱。", "process": "1696年1月下院报剪边的情况，议会遂定重铸令：旧钱分限交出，新钱机制加齿，布里斯托、约克、诺里季等处立分局赶造；铸币厂起用牛顿为督办，1699年升局长，兼察私剪之罪。", "impact": "洛克执不宜改色名的说法，与朗蒂斯辈相辩；重铸之期钱少而市困，1698年后币稍定，乃有以应国债与票用之需。1717年牛顿请减几尼价而不行，银币渐出，后世视为金本之渐。", "figures": ["（铸币厂）艾萨克·牛顿", "（其争之文）约翰·洛克", "（请改币值者）威廉·朗蒂斯"], "place": "伦敦、威斯敏斯特与诸分局之城", "state": "英格兰王国", "sources": ["1696年重铸之法与铸币局之案册", "洛克《论降低利息与增高银价》、《剑桥欧洲经济史》"], "tags": ["币制", "重铸", "剪边"]}, "related": ["world--1694--i01"]},
  {"id": "world--1697--p01", "track": "world", "year": 1697, "yearApprox": false, "dim": "politics", "weight": 4, "title": "里斯维克和约与九年战事收束", "summary": "一约认新王而拆要塞，大战暂息，继统之议未决。", "detail": {"background": "1689年起英、荷与帝国同法兰西相争，双方在尼德兰攻城相持而岁凶；法国财诎，盟国又以萨伏伊与法另约为忧，俱欲休兵。", "process": "1697年9月20日在里斯维克签成：法兰西认威廉为三国之王，允不复扶雅各布，归洛林与所占西属尼德兰诸城，拆菲利普斯堡等要塞，阿尔萨斯与斯特拉斯堡仍之；帝国的附约继成于其冬。", "impact": "此约只是暂息九年之战，西班牙继统之议由1698、1700年两度私分而来，1701年复燃；法国由攻转守，英格兰因兵费立银行、定土地税，财政之制即此战催成。", "figures": ["（法王）路易十四", "（盟主）奥伦治之威廉三世", "（其议约之使）卡尔耶尔"], "place": "里斯维克（今荷兰海牙之西）", "state": "法兰西王国、英格兰、荷兰、帝国、西班牙", "sources": ["1697年约文之抄本与使节之通信", "《剑桥近代史》、卡尔耶尔《谈判之术》"], "tags": ["条约", "九年之战", "继统"]}, "related": ["world--1689--p01", "world--1694--i01"]},
  {"id": "world--1698--s01", "track": "world", "year": 1698, "yearApprox": false, "dim": "science", "weight": 2, "title": "塞维里蒸汽提水机专利", "summary": "以汽缩而水上行，矿工自此借火为力。", "detail": {"background": "煤矿渐深而车马、水力不能及，1690年代英格兰已有人议以火蒸而取水；塞维里在军械署任督工，往来矿场与工匠之间。", "process": "1698年6月14日得「新法之火机，可引水而行船」的专利，其期十四年，后凭议会之法展之（展期之年有1699、1715两说，学界未一）。其法以蒸汽入筒，外淋冷水使缩为虚，赖空气之重逼水而上。", "impact": "此机省力于马而费于火，用处有限，然其名为后来纽科门与瓦特诸机的张本，专利之累延到十八世纪中。气重推水的说法，自此由试验入工器。", "figures": ["（其请之者）托马斯·塞维里", "（其前之议）丹尼斯·帕潘"], "place": "伦敦", "state": "英格兰王国", "sources": ["1698年专利之文本与塞维里《矿友》之说明（1702年刊）", "《剑桥欧洲经济史》、近人《蒸汽机之来源考》"], "tags": ["蒸汽", "矿工", "专利"]}, "related": []},
  {"id": "world--1699--p01", "track": "world", "year": 1699, "yearApprox": false, "dim": "politics", "weight": 3, "title": "卡尔洛维茨和约与奥斯曼让地", "summary": "二十年之约一次画出东界，土师不可胜之说由此变。", "detail": {"background": "维也纳解后帝国连岁东胜，1697年9月欧根伯森塔大捷；威尼斯取摩里亚，俄国两攻亚速（1695、1696），法兰西居间代议。", "process": "1699年1月26日在卡尔洛维茨定二十年之约：帝国得北匈牙利、斯拉沃尼亚与特兰西瓦尼亚，波兰得波多里亚，威尼斯得摩里亚；俄国之约别成于1700年夏君士坦丁堡，停战三十年而亚速归之。", "impact": "这是奥斯曼第一次以条约向同盟大邦连片让地，「土师不可胜」的成见一变，哈布斯堡的多瑙河诸省由此成形；其东界延到1718年帕萨罗维茨之约。", "figures": ["（其将）萨伏伊之欧根亲王", "（土王）穆斯塔法二世"], "place": "卡尔洛维茨（今塞尔维亚斯雷姆斯基卡尔洛维茨）", "state": "奥斯曼国、哈布斯堡、波兰、威尼斯、俄罗斯国", "sources": ["1699年约文之拉丁本与土文本", "《剑桥奥斯曼史》晚期卷、肖《奥斯曼帝国史》"], "tags": ["条约", "割地", "东界"]}, "related": ["world--1683--m01"]},
  {"id": "world--1700--m01", "track": "world", "year": 1700, "yearApprox": false, "dim": "military", "weight": 3, "title": "纳尔瓦：瑞典以少击破俄军", "summary": "风雪里一日击溃围城之众，北方之战由此开局。", "detail": {"background": "彼得一世用1697年大使团西行，回来练兵、造船；1699年秋丹麦、萨克森与俄结成北方同盟，趁瑞典新君初立要夺回波罗的海东岸。", "process": "1700年8月俄军围纳尔瓦，11月30日查理十二以八千余冒风雪来援，一击而溃围城之众（其死与被虏之数各方记载差异较大，册籍自二万至三万五千不等），俄国的炮兵与辎重尽失。", "impact": "此败几乎倾掉彼得初练之兵，却催成其后的征兵、铸炮与军制之改；瑞典回师波兰与萨克森，八年后才再向东北，1709年波尔塔瓦为其续。", "figures": ["（瑞典新君）卡尔十二", "（俄君）彼得一世", "（其前敌之将）戈洛夫金"], "place": "纳尔瓦（今爱沙尼亚东北境）", "state": "瑞典王国、俄罗斯国", "sources": ["1700年之瑞军战报与被获俄将之供状", "林德奎斯特《大北方之战》、《剑桥俄国史》第一卷"], "tags": ["北方之战", "纳尔瓦", "以少击众"]}, "related": ["world--1721--p01"]},
  {"id": "world--1701--p01", "track": "world", "year": 1701, "yearApprox": false, "dim": "politics", "weight": 4, "title": "西班牙继统之争与大同盟成", "summary": "一纸遗诏以西班牙付波旁，海牙盟约起八年之战。", "detail": {"background": "卡洛斯二世无嗣而病笃，英、荷与法两次私分其地；1699年巴伐利亚的候选者死，遗诏遂归安茹的腓力。", "process": "1700年11月1日王死，马德里诸省奉腓力为菲利普五世；1701年法军入西属尼德兰换戍，9月7日海牙定第二大同盟，1702年5月宣战，帝国与萨伏伊随后。", "impact": "大战延到1713年乌得勒支与1714年拉斯塔特之约，西班牙的欧洲属地剖分；路易十四认雅各布之子为王（1701年9月），是英格兰入战的直接因，北美「安妮王后之战」亦由此起。", "figures": ["（法王）路易十四", "（其孙）菲利普五世", "（其将）萨伏伊之欧根亲王"], "place": "马德里、海牙、尼德兰与莱茵河", "state": "法兰西王国、西班牙、英格兰、荷兰、帝国", "sources": ["1700年之遗诏与1701年大同盟之约文", "《西班牙王位继承战争史》、《剑桥近代史》"], "tags": ["继统之战", "大同盟", "条约"]}, "related": ["world--1697--p01", "world--1701--i01"]},
  {"id": "world--1701--i01", "track": "world", "year": 1701, "yearApprox": false, "dim": "institution", "weight": 5, "title": "英国《王位继承法》定继统", "summary": "王冠先定于议会所选新教之亲，法官之位不属王。", "detail": {"background": "1700年7月格洛斯特公爵威廉死，安妮的子女一个不留；议会忧法国的雅各布之子承统，故预为王冠之限。", "process": "1701年6月12日《王位继承之法》成：安妮无后之后王冠归索菲亚（詹姆士一世之外孙女）及其新教之嗣，与罗马教会相通、信天主者皆不许；又定法官在职守无亏者非两院请罢不退，国王为非其国之地的兵争须先取议会之可。", "impact": "此法与1689年《权利之法》、1694年《三年议会之法》共成立宪之实：继统、职任与兵权归于议会，1714年汉诺威之家由是入主。", "figures": ["（其时之王）安妮女王", "（次及之亲）汉诺威之索菲亚", "（其争者）在法之雅各布之子"], "place": "伦敦、威斯敏斯特", "state": "英格兰王国", "sources": ["1701年之法文与两院之议事录", "《剑桥英国史》、《剑桥近代早期欧洲史》"], "tags": ["立宪", "继统", "议会"]}, "related": ["world--1689--p01", "world--1707--p01"]},
  {"id": "world--1704--s01", "track": "world", "year": 1704, "yearApprox": false, "dim": "science", "weight": 3, "title": "牛顿《光学》刊于伦敦", "summary": "棱镜分出七色，光学自此有试验之书。", "detail": {"background": "1666年后牛顿以棱镜分光为七色，1672年在《哲学汇刊》首说光色之论，与胡克及说绕射者相辩多年；《原理》成后哈雷催其出书。", "process": "1704年刊行《光学》三卷：以棱镜与「素板」诸验定七色之性，说明薄膜之色（后世所谓牛顿环），断光为极小之体，附「疑问」数条论气与微细之因；1706年出拉丁本。", "impact": "它将《原理》的几何法接上试验的门径，粒说与惠更斯波说由此分途，到十九世纪干涉之验才再变；透镜、仪器与色的学问皆得其用，「疑问」诸条为后续两百年光论之题单。", "figures": ["艾萨克·牛顿", "（其刊书之助）埃德蒙·哈雷", "（其诤敌）胡克"], "place": "伦敦", "state": "英格兰王国（皇家学会之学）", "sources": ["1704年《光学》原本与1706年拉丁本", "科恩校释《牛顿〈光学〉》、韦斯特福尔《永不安息的天才》"], "tags": ["光学", "棱镜", "试验之学"]}, "related": ["world--1687--s01"]},
  {"id": "world--1707--p01", "track": "world", "year": 1707, "yearApprox": false, "dim": "politics", "weight": 3, "title": "合并法案与大不列颠王国成", "summary": "两国议会合为一处，税与币同行，法律各守其旧。", "detail": {"background": "1603年以来共主而各有议会；1701年《继承之法》定新教之继，苏格兰恐其别择而在1704年颁《安保之法》，英格兰以外国船税之令相胁。", "process": "1706年议定条目，苏格兰议会于1707年1月以百一十对六十七通过，5月1日两国之法并行：共一议会、共一币与税则，十六贵族、四十五下院，而苏格兰保有自己的法律、法庭与国教。", "impact": "王国一体后，苏格兰的麻、煤与殖民地贸易皆入英格兰的市场；1715、1745年的詹姆士党举事皆不成，「大不列颠」自此入约文与铸币。", "figures": ["（其时之王）安妮女王", "（苏格兰之反对者）汉密尔顿公爵", "（其议约者）两国议会之选委"], "place": "伦敦、威斯敏斯特、爱丁堡", "state": "英格兰王国、苏格兰王国（合为大不列颠）", "sources": ["1707年两国之法文与苏格兰议会之表决册、安妮之谕旨", "《剑桥英国史》、关于合并条款之两国异文（条目之数与表决之目有异说）"], "tags": ["合并", "议会", "大不列颠"]}, "related": ["world--1701--i01"]},
  {"id": "world--1709--m01", "track": "world", "year": 1709, "yearApprox": false, "dim": "military", "weight": 4, "title": "波尔塔瓦之役与瑞师之溃", "summary": "围城反遭击溃，瑞典常胜之名至此而尽。", "detail": {"background": "1708年查理十二入乌克兰，彼得坚壁清野，大寒与轻骑断其粮；盖特曼马泽帕同年秋投瑞典，与瑞军同围波尔塔瓦。", "process": "1709年6月27日（俄历，即新历7月8日）彼得以四万余人临阵解围，瑞军大溃（其死与被虏之数各方记载差异较大，册籍以数千至万余不等），查理十二与马泽帕带千人南逃入奥斯曼，炮营尽失。", "impact": "此役后北方战争转为俄国的进取，汉诺威、普鲁士与丹麦相继再入盟，1721年尼斯塔德定局；马泽帕的名字在乌克兰史论中是两造之争，亦为后世画题与碑志所本。", "figures": ["彼得一世", "（瑞典王）卡尔十二", "（乌克兰之盖特曼）马泽帕"], "place": "波尔塔瓦（今乌克兰中部）", "state": "俄罗斯国、瑞典王国、哥萨克", "sources": ["1709年之俄军战报与瑞典被获将校之供", "《剑桥俄国史》第一卷、林德奎斯特《大北方之战》"], "tags": ["北方之战", "波尔塔瓦", "决定性之役"]}, "related": ["world--1700--m01", "world--1721--p01"]},
  {"id": "world--1715--f01", "track": "world", "year": 1715, "yearApprox": false, "dim": "figure", "weight": 3, "title": "路易十四去世与幼主继位", "summary": "为君七十二年，一朝终结，摄政之局始。", "detail": {"background": "1715年法国新经西班牙继承之战（1701—1714），兵役与饥荒两面困扰百姓，国债与粮税俱急迫；国王晚年死了继承人与孙辈，只余五岁的曾孙，宫廷、教会与财政弊病一起到来。", "process": "1715年9月1日路易十四死于凡尔赛，年七十七，在位七十二年（1643—1715）；遗嘱命私生子主持要紧事务，为巴黎高等议会所废，摄政归奥尔良公爵腓力二世（1715—1723）。以部院「合议」代替国务大臣制，财政担子交约翰·劳。", "impact": "摄政朝廷用密西西比股票与银行钞票造出虚富局面，1720年全部崩溃，影响一直到1789年的债务；1723年路易十五亲政后恢复旧制。凡尔赛礼仪与宫乐（拉莫、库普兰的弟子）也在这一时期成为欧洲各宫廷的样子，这套制度延到法国大革命。", "figures": ["路易十四", "（其摄政）奥尔良公爵腓力二世", "（其财臣）约翰·劳"], "place": "凡尔赛、巴黎", "state": "法兰西王国", "sources": ["圣西门《回忆录》与其朝之档册、1715年之遗嘱与议会之录", "《路易十四之朝》（布卢瓦等）、近人《约翰·劳与密西西比之倾》"], "tags": ["绝对主义", "摄政", "财政"]}, "related": []},
  {"id": "world--1716--i01", "track": "world", "year": 1716, "yearApprox": false, "dim": "institution", "weight": 3, "title": "享保改革与幕府理财", "summary": "纪州侯爵至江户主事，以米与户籍整顿财政。", "detail": {"background": "元禄以来，幕府府库空了，旗本、御家人多数贫穷，浪人多与米价上涨互相推动；六代、七代政事没有成就，诸臣请求贤能的侯出来主持。1716年吉宗以纪州藩主身份接任第八代将军，年三十四。", "process": "1716年（享保元年）行上米令，要求各大名按石高献米以实幕府仓；1717年立「足高之制」，破格用人；1721年设町会所，囤米以平抑米价，禁止奢侈，劝人种棉、漆与蚕；1720年放松西洋书禁令（天主教书籍仍然严禁），由荷兰传入的学问从此有了门路；1742年编成《御定律目》，辑一代法式。这一时期又兴新田、招百姓开垦关东野地。", "impact": "改革稍振幕府府库却不能止它下行的趋势：米价控制行于江户，困住产米之地；1732年西国凶年与虫疫，西日本死者，学界按数十万计，旧说百万被认为过高。但贤侯政务成为后来宽政、天保两次改革的模型；放松书禁使医学、算学、炮术由荷兰传入不断，十八世纪中叶就有兰学的家数。", "figures": ["德川吉宗", "（其谋臣）水野忠之、安藤正信", "（董米市者）町会所之商人"], "place": "江户、京都、纪州", "state": "江户幕府", "sources": ["《德川实纪·吉宗成纪》与幕府法令集《御定律目》、町会所之账册", "近人《享保之改革研究》、《德川财政与国家经费》"], "tags": ["享保", "财政", "兰学之门"]}, "related": []},
  {"id": "world--1721--p01", "track": "world", "year": 1721, "yearApprox": false, "dim": "politics", "weight": 3, "title": "尼斯塔德条约与俄国称帝国", "summary": "北方战争二十年毕，波罗的海东岸归俄国。", "detail": {"background": "彼得一世以1697年大使团西行游历，归国后改服色、建船队；1700年纳尔瓦之败几乎丢光他的兵，此后取得涅瓦河口，1703年筑圣彼得堡，1709年波尔塔瓦一战打碎瑞典王师，查理十二逃到奥斯曼。", "process": "1721年9月10日定尼斯塔德条约：俄国得爱斯兰、利夫兰、英格里亚与卡累利阿的一半，还芬兰于瑞典，瑞典北方霸权自此结束。同年11月2日元老院给彼得加上「大帝」与「帝国」称号，此后俄国外交自居帝国。又申明它在波兰的「常驻之护」，这一名分成为后来三次瓜分的底子。", "impact": "俄国得波罗的海港口与商路，圣彼得堡自1712、1714年迁都后成为面向欧洲的窗口；元老院、省制与官品表（1722）都因北方战争需要而成。学者论北方格局，以此作瑞典变小、俄国变大的分界；此后一百年欧洲大陆形势，一以俄国向背为准。", "figures": ["彼得一世", "（其将兵之臣）缅希科夫", "（瑞之王）查理十二"], "place": "尼斯塔德（今芬兰南西岸）、圣彼得堡", "state": "俄罗斯帝国、瑞典王国", "sources": ["1721年约文之瑞典文本与俄本、彼得之谕与元老院之案", "《剑桥俄国史》第一卷、林德奎斯特《大北方之战》"], "tags": ["北方之战", "帝国", "波罗的海"]}, "related": []},
  {"id": "world--1732--c01", "track": "world", "year": 1732, "yearApprox": false, "dim": "culture", "weight": 2, "title": "《穷理查年鉴》费城首刊", "summary": "一册历书杂以谚语，市井之言自此年年印行。", "detail": {"background": "1729年富兰克林与休梅尔合办《宾夕法尼亚报》；他以「理查·桑德斯」假名自印历书，意在省资而广其说。", "process": "1732年12月19日首册在费城印出（题为1733年之用），以星占、农时与道里之表杂以谚语问答，每年一册，行二十余年；1758年他辑其谚语为《致富之术》一序。", "impact": "它以市井之言教人勤、俭、信，为殖民地识字与印刷业的标本，后世历书与期刊多沿其体；富兰克林由此得印刷与公益之资，1731年的借款图书馆与1751年的医院皆其续。", "figures": ["本杰明·富兰克林", "（其合营之伴）戴维·休梅尔", "（其假名）理查·桑德斯"], "place": "费城（今美国宾夕法尼亚州）", "state": "北美宾夕法尼亚殖民地", "sources": ["1732—1758年历书之原本与富兰克林《自传》", "《剑桥美国史》第一卷、关于殖民地印刷之研究"], "tags": ["历书", "印刷", "费城"]}, "related": ["world--1776--p01"]},
  {"id": "world--1733--p01", "track": "world", "year": 1733, "yearApprox": false, "dim": "politics", "weight": 3, "title": "奥古斯特二世死与波兰选王之争", "summary": "一场选举成两国之王，外国之兵因此入其地。", "detail": {"background": "奥古斯特二世以萨克森选侯得波兰之冠；1730年代初俄、奥约以萨克森为请，法国则求外戚斯坦尼斯瓦夫的再立。", "process": "1733年2月1日奥古斯特死于德累斯顿，9月12日华沙近郊的选举众立斯坦尼斯瓦夫，10月初俄军护送的少数另立奥古斯特三世；法军于其秋渡莱茵，战事分在两路。", "impact": "1735年初定、1738年成约：斯坦尼斯瓦夫得洛林，其死（1766年）后归法国，弗兰茨·斯特凡转得托斯卡纳；此役见俄、奥以「自由选王」为质而实制其国，为1772年后三次分割之渐。", "figures": ["斯坦尼斯瓦夫·莱什琴斯基", "（萨克森之主）奥古斯特三世", "（其援者）法王路易十五"], "place": "华沙、克拉科夫、莱茵兰与意大利", "state": "波兰—立陶宛、萨克森、法兰西、俄罗斯国、奥地利", "sources": ["1733年两选举之册与1738年维也纳之约文", "《剑桥波兰史》、近人关于波兰王位继承战争之研究"], "tags": ["继统之战", "自由选王", "分割之渐"]}, "related": []},
  {"id": "world--1736--p01", "track": "world", "year": 1736, "yearApprox": false, "dim": "politics", "weight": 3, "title": "纳迪尔称沙于穆干草原", "summary": "草原大会废萨法维之统，新朝以军兴。", "detail": {"background": "1722年阿富汗人取伊斯法罕而萨法维之权尽，纳迪尔以呼拉桑的军阀拥立太子，1729年破阿什拉夫于穆拉德里卜。", "process": "1736年初（3月间）大会诸侯与将帅于穆干草原，废阿巴斯三世而自立，号沙，其礼仿帖木儿与蒙古旧制；随后整军、定税，以西境与奥斯曼连岁相争，东向则图莫卧儿之资。", "impact": "萨法维之统遂绝而为阿夫沙尔之朝；他把军费与教争都归于一人之手，1739年取德里之役与后来的西征皆资于此，1747年被刺之后财尽散而波斯复分。", "figures": ["纳迪尔·沙阿", "（其所废）萨法维之阿巴斯三世", "（其旧敌）阿什拉夫·霍塔克"], "place": "穆干草原（今阿拉斯河北一带）、大不里士", "state": "波斯（阿夫沙尔朝）", "sources": ["1736年加冕之诏与穆干之会的记载（月份有正月、三月两说）", "《伊朗通史》近代卷、近人《纳迪尔沙之朝》"], "tags": ["波斯", "篡立", "军制"]}, "related": ["world--1739--m01"]},
  {"id": "world--1736--i01", "track": "world", "year": 1736, "yearApprox": false, "dim": "institution", "weight": 2, "title": "英国《杜松子酒法》与照验之令", "summary": "五十镑照验金欲止狂饮，令下而市怨。", "detail": {"background": "1720年代麦价低而酿酒用麦，伦敦贫民以杜松子酒代食，与济贫之担相激；1728、1729年已有加税与零售之禁。", "process": "1736年，在主教论说与下院请愿之下，由当政的财政大臣主持颁《饮酒之令》：零售者纳五十镑照验金，又限煎熬与批发；令下而市大怨，1737年伦敦有聚众之事，1738年其令多弛而税与照验相沿。", "impact": "此案开以营业许可与税则管民间嗜好的路，1751年的再限与霍加斯的两图（同年）成禁、税两道之例；它也露出济贫、工场与酒利之争。", "figures": ["（主其令之臣）罗伯特·沃波尔", "（后图其弊者）威廉·霍加斯"], "place": "伦敦、威斯敏斯特", "state": "大不列颠王国", "sources": ["1736年《饮酒之令》原文与下院之请愿册", "《剑桥英国史》、关于十八世纪酒类之法令的研究"], "tags": ["酒令", "许可与税", "风俗之议"]}, "related": []},
  {"id": "world--1738--s01", "track": "world", "year": 1738, "yearApprox": false, "dim": "science", "weight": 3, "title": "丹尼尔·伯努利《水力学》刊成", "summary": "速加则压减，活力之争落于可测之水工。", "detail": {"background": "十七世纪末莱布尼茨与「活力」之说相争，约翰·伯努利于巴塞尔传其算法；丹尼尔·伯努利（1700—1782）在其门下测水的压力与速度，1725至1733年任彼得堡科学院讲席。", "process": "1738年在斯特拉斯堡刊成《水力学》：定水由孔出之速与其面之比，推言速加则压减，以之论虹管、水磨与活塞；又论气之压力起于微体之撞，为后世气体动论之前列。", "impact": "「活力」的争论由此落到可测的水工上，欧拉继之以方程，十九世纪管道、翼面与水机皆用其说；书名遂为流体力学之祖。", "figures": ["丹尼尔·伯努利", "（其师）约翰·伯努利", "（其继者）莱昂哈德·欧拉"], "place": "巴塞尔、斯特拉斯堡", "state": "瑞士诸邦（巴塞尔）、俄罗斯科学院之学", "sources": ["1738年《水力学》原本", "《剑桥科学史》、近代流体力学之源流研究"], "tags": ["水力", "气压", "伯努利之理"]}, "related": ["world--1687--s01"]},
  {"id": "world--1739--m01", "track": "world", "year": 1739, "yearApprox": false, "dim": "military", "weight": 4, "title": "纳迪尔破莫卧儿而取德里", "summary": "卡尔纳尔一战而莫卧儿请和，府库与宝座东迁。", "detail": {"background": "纳迪尔既取坎大哈（1738），莫卧儿朝收留其敌，成为入印度的口实；奥朗则布死后诸省离心，兵与府库都不足恃。", "process": "1739年2月13日卡尔纳尔之役以寡击众（莫卧儿之兵各方记载差异较大，自三万至数十万不等），穆罕默德沙屈膝请和；3月下旬入德里，取府库与孔雀之座，因城中乱而屠之，印度河以西之地与连岁的贡尽归其手。", "impact": "莫卧儿的体面由此尽失，此后诸省世侯、马拉塔与阿富汗人相继取其地，1757年普拉西之役皆趁其空；纳迪尔以此资营其都，1747年被刺而财尽散。", "figures": ["纳迪尔·沙阿", "（莫卧儿主）穆罕默德沙"], "place": "卡尔纳尔、德里（今印度北部）", "state": "波斯（阿夫沙尔朝）、莫卧儿帝国", "sources": ["1739年之波斯军报与莫卧儿朝之纪载（其数互异）", "《剑桥印度史》第一卷、近人《纳迪尔沙之朝》"], "tags": ["德里之劫", "孔雀之座", "莫卧儿之衰"]}, "related": ["world--1736--p01", "world--1757--m01"]},
  {"id": "world--1740--p01", "track": "world", "year": 1740, "yearApprox": false, "dim": "politics", "weight": 3, "title": "巴达维亚华人大屠杀", "summary": "一城疑心，三天流血，海上市集政令遂改。", "detail": {"background": "公司以巴达维亚为东方贸易首府，华工与华商杂住城内，业糖、鱼与零售；1740年荷兰人担心爪哇乱事与华人响应，城防议论纷纷，华人须挂居留凭证，被赶出城的人怨声不断。", "process": "1740年10月9日至12日，城内华人被抢掠杀害：兵与安波那人、土民进华人家中，抛尸首入河。时人与后世据档册推算死者五千到上万不等，学界至今没有定数，最多的说法出自传闻。这年冬天，公司以「他往」名义把活下来的人赶上船东送，路上死的层层相枕；1741至1743年爪哇乱事接着起来，马都拉与各土邦兵同攻公司属地，平定后又重定华人住处。", "impact": "这次屠杀与爪哇战事一并耗尽公司财力，爪哇北岸税与土地自此由土邦臣属改为公司自领；华人商网因此转向马来半岛、安南与暹罗港口，闽南、粤东出海的人逐年增加。1740年后公司以防华为常规，「甲必丹」管华人的权越来越重，这套制度延到十九世纪。", "figures": ["（公司之督）瓦尔肯尼尔·洛奥斯", "（城之刑名官）其议罪之有司", "（纪其事者）城之商馆与传教之报"], "place": "巴达维亚（今雅加达）、爪哇北岸", "state": "荷兰东印度公司、爪哇诸土邦", "sources": ["1740—1743年之会议记录、日记与公司档册（今存海牙与雅加达）", "近人《巴达维亚1740年之屠》（据荷兰档案之校勘）、《华人下南洋》之研究"], "tags": ["巴达维亚", "华民", "公司之治"]}, "related": []},
  {"id": "world--1751--c01", "track": "world", "year": 1751, "yearApprox": false, "dim": "culture", "weight": 3, "title": "《百科之编》第一函刊于巴黎", "summary": "一书既出，工匠与算学同登学问人之席。", "detail": {"background": "1745年巴黎商人把英国《科艺之库》的法译当作自己的事，请狄德罗与达朗贝尔主持；两人反客为主，另立凡例，用知识大系统互相贯通，稿件积了五六年才完成。", "process": "1751年第一函在巴黎刊行，文函至1765年成十七函，图函至1772年始毕，共几千条目与铜版图像；数学、工艺、医、矿与机巧技术并列，将工匠的操作画出并加说明。此书两次受官府禁令（1752、1759），靠私市与各省发行没有断；1752年达朗贝尔的「日内瓦诸条」又激起宗教与剧场之争。", "impact": "全书格式成为后来欧洲书坊样式（十八世纪末苏格兰《不列颠百科》由它变化出来）；它将技术列为学问门目与编排方法，为后来技术书与算学表开路，狄德罗《梦》与达朗贝尔界说也为唯物论调打下底子。学界统计它的条目约六万到七万余，数字因统计方法而不同。", "figures": ["德尼·狄德罗", "让·勒朗·达朗贝尔", "（其刊主）勒·布雷东"], "place": "巴黎", "state": "法兰西王国", "sources": ["1751年初函与1772年终函之原本、其〈凡例〉与禁行之案", "近人《狄德罗与百科之编》、《启蒙之出版研究》"], "tags": ["启蒙", "出版", "工艺"]}, "related": []},
  {"id": "world--1755--d01", "track": "world", "year": 1755, "yearApprox": false, "dim": "disaster", "weight": 3, "title": "里斯本地震与海啸", "summary": "万圣节清晨地裂，火与潮同及都城。", "detail": {"background": "里斯本下城临特茹河口，聚商家、教堂与府库；这地方受大西洋裂缝挤压，累百年无大震，城里的人听到11月1日清晨的钟声去行礼。", "process": "1755年11月1日早晨约九时四十分连震几次，城塌一半；灶火延烧三天，下城烧尽；不久海退又涌上来，潮高从二米多到十几米（学界据海岸痕迹推算，出入很大）。死亡人数时报从一万到五万，学界多取二万到四万（当时户口约十万到二十万，户籍不能齐全）。1759年因塔沃尔拉案判罪旧族，随即赶走耶稣会。", "impact": "庞巴尔侯爵以「葬死者而抚生者」主持这次重建：下城方格、临河广场与笼架砌墙成了新样式，商馆与海关一并移到河边。这次地震也震动欧洲大陆思想：伏尔泰《诗论灾异》与《老实人》、卢梭说灾祸由于人在城里聚居、康德论震源（1756年三篇）都拿它作例；「一切之善」的说法自此很难在欧洲人嘴里立住。", "figures": ["（其政主）庞巴尔侯爵", "（其时之王）若泽一世", "（其诘者）伏尔泰、康德"], "place": "里斯本、特茹河口、阿尔加维", "state": "葡萄牙王国", "sources": ["1755—1757年王室遍问诸教区之问询册（今存葡萄牙国家档案）、英荷之关系书", "近人《里斯本1755年之震与庞巴尔之筑》、《灾异之思想史》"], "tags": ["地震", "海溢", "灾异之思"]}, "related": []},
  {"id": "world--1757--m01", "track": "world", "year": 1757, "yearApprox": false, "dim": "military", "weight": 3, "title": "普拉西之战与公司取孟加拉", "summary": "一日阵仗，富庶行省易主，商人执掌印信。", "detail": {"background": "公司给加尔各答堡添炮，纳布·沙阿卜恼它侵占；1756年他的军队取加尔各答，围堡夜里不少欧洲人死于狭小屋里（黑牢的说法，学界认为记载人数与屋子大小不合，或说过头）。莫卧儿朝廷自1739年纳迪尔进德里、拿走孔雀宝座与府库以后，已不能节制自己的省督。", "process": "1757年6月23日，克莱夫率欧兵数百、土兵二千余于普拉西抵挡纳布人众（当时报告称数万，学界认为是胜方夸大）；他的将领米尔·贾法尔按兵不动、临阵倒戈，一天之内纳布军溃散。接着令贾法尔为省督，公司得军费与两县的田；1765年又取迪瓦尼，即收田赋之权。自此商人掌仓库与印信，土邦兵税出自它手中。", "impact": "孟加拉的田赋供公司货物与兵，伦敦股票因此上涨；1772、1773年议会立法设总督职位与督办之院，公司政务渐归国家监督；它「两立之政」的弊病自此显露。省督废立、土邦吞并与附属同盟条约（1798至1805年间多次施行）都照这例子，这局面到1858年改由国王直接统辖。", "figures": ["（其将）克莱夫", "（败者）纳布·沙阿卜", "（内应之将）米尔·贾法尔"], "place": "普拉西（今印度西孟加拉邦）", "state": "英国东印度公司、孟加拉省督府、莫卧儿帝国", "sources": ["1756—1757年之公司议事录、克莱夫之信札、省督府之纪", "《剑桥印度史》第二卷、近人《普拉西之役与公司之取孟加拉》"], "tags": ["普拉西", "田赋", "公司之政"]}, "related": []},
  {"id": "world--1763--p01", "track": "world", "year": 1763, "yearApprox": false, "dim": "politics", "weight": 4, "title": "巴黎条约与胡贝图斯堡条约", "summary": "两份条约并出而九年战争告终，海权归于英国。", "detail": {"background": "1756年后普鲁士与法国、奥地利换盟开战，兵事延及德意志、北美、印度与海路；1759年基伯龙湾之败让法国不能渡海侵英，1762年西班牙参战而哈瓦那、马尼拉随即被英国夺走，各方都被财政困住。", "process": "1763年2月10日巴黎条约：法国把加拿大与新法兰西让给英国（路易斯安那一半前一年已暗中让给西班牙），西班牙以佛罗里达让与英国，英国归还古巴与马尼拉；同年2月15日胡贝图斯堡条约复1748年格局，普鲁士保住西里西亚。同年10月英国国王下令禁殖民者西越阿拉巴钦岭，以安抚印第安各部；这一年蓬蒂亚克的兵在西北堡垒起事。", "impact": "这条约是第一次「世界之战」的结局：英国得北大西洋与印度海口，法国拓土只剩渔场，西属美洲门户向私市开放。英国战债较旧时多几倍，1764、1765年糖税与印花税因此而起，北美反抗顺此路而行；法国、奥地利受辱想报复，就开启1792年后二十年战事。学者以1763年为不列颠世纪的开端，也当作本世纪欧陆战局的转折点。", "figures": ["（法之外臣）贝尔尼斯", "（英之相）比特与乔治三世之朝", "（普之王）腓特烈二世"], "place": "巴黎、胡贝图斯堡（今德国萨克森）", "state": "法兰西、西班牙、大不列颠、普鲁士、奥地利", "sources": ["1763年二约之文本与两国之使报、英王10月之公告", "《剑桥近代早期欧洲史》之末叶、安德森《海权与1763年之局》"], "tags": ["七年之战", "海权", "税与殖民"]}, "related": []},
  {"id": "world--1770--d01", "track": "world", "year": 1770, "yearApprox": false, "dim": "disaster", "weight": 3, "title": "孟加拉大饥荒", "summary": "雨不按时，税额不改，一省百姓几乎损失三分之一。", "detail": {"background": "1765年公司取迪瓦尼，田赋每年定额增加，也由自己领收；1768、1769年两省雨不按时，1769年冬稻子不熟，仓中积存被商人和兵先取走，河路运不到缺粮处。", "process": "1770年春饥荒大闹孟加拉、比哈尔与奥里萨，米价至平时五六倍；公司不减免额数，还令官吏催缴，百姓食草木与虫，路上饿死的人接连可见；天花与痢疫随饥荒同起。死的人数，当时的报告与近人校勘从五百万到一千万（学界多认为约当全省户口三分之一弱，因户籍不全没有定论）。1771年雨恢复，田地稍微开辟。", "impact": "饥荒与「公司之富并世所无」的议论上报伦敦，1772、1773年议会立法设总督职位与督办院，公司政务渐归国家监督；此后半个世纪，印度饥荒总与粮食出口、铁路未通与定额的税互相牵连，论者都拿1770年做例子。省内匠人与农民东迁比哈尔、西走马拉塔，行业就此分散。", "figures": ["（其时之总督）沃伦·黑斯廷斯（1772年任）", "（省之旧督）纳吉布·乌德—道拉", "（纪其事者）省之绅与报书"], "place": "孟加拉、比哈尔、奥里萨", "state": "英国东印度公司", "sources": ["1770—1774年公司之报与议会之询（东印度案卷）、省志与田赋之册", "《剑桥印度史》第二卷、戴维斯《晚近之饥与殖民之政》"], "tags": ["饥荒", "田赋", "孟加拉"]}, "related": []},
  {"id": "world--1776--s01", "track": "world", "year": 1776, "yearApprox": false, "dim": "science", "weight": 3, "title": "瓦特分置凝器", "summary": "另器分冷凝之水，煤耗大省，机器始可用。", "detail": {"background": "纽科门蒸汽机自1712年用在矿井，汽筒要冷却所以费煤，好处限于产煤处；瓦特为格拉斯哥大学仪器匠，1763年修模型时知道热损失的原因，于是另立一具冷凝水的器。", "process": "1769年瓦特得分离凝器专利，它的筒保持热，水在别器中冷凝；1775年与伯明翰博尔顿合伙，专利延到1800年；1776年第一架营业用机器造于斯塔福德郡炼炉与磨坊，以蒸汽推柱鼓风炉，省煤自三分之一到三分之二（按当时报告，学界认为这数出厂主自家告知，或有水分）。1781、1782年接着做成旋转与双动两法，1783年威尔金森的汽锤方能应用。", "impact": "动力自此不受水力与产煤地限制，工厂得以离河聚于煤铁与海口，曼彻斯特、伯明翰的局面因此形成；此机又供矿井加深、运河补短与后来的舟车用。博尔顿以「凡求动力者此处供之」为口号，学者视1776年前后为工业动力转机；不过它普遍见效于纺织与舟车，那已到十九世纪中叶。", "figures": ["詹姆斯·瓦特", "马修·博尔顿", "（其钻筒者）约翰·威尔金森"], "place": "格拉斯哥、伯明翰（索霍之厂）、斯塔福德郡", "state": "大不列颠", "sources": ["瓦特之专利书（1769、1775年展本）与博尔顿—瓦特之账册（伯明翰档案）、威尔金森之约", "近人《瓦特与蒸汽之机》、《不列颠之工业与煤》"], "tags": ["蒸汽", "专利", "工业动力"]}, "related": []},
  {"id": "world--1776--p01", "track": "world", "year": 1776, "yearApprox": false, "dim": "politics", "weight": 5, "title": "十三州告天下文告", "summary": "一纸言人生而平等，奴隶与边地皆不入其文。", "detail": {"background": "1775年4月列克星敦枪声已起，5月议会还请申理；同年8月国王宣布殖民地全在反叛，而潘恩的《常理》（1776年1月刊行）在各市风行，说和好已不可能恢复。", "process": "1776年6月7日弗吉尼亚的李提议独立，11日委任五人起草文告（杰弗逊主笔，富兰克林、阿丹斯、李、舍曼协助）；7月2日十三州会议决定独立，4日发布《宣告之文》，8月2日签署。这篇文告以「人创造而生来平等，享有生命、自由与追求幸福的权利」作纲，列出国王罪状二十多条，并指责买卖非洲人为「逆法」。", "impact": "这话开出后来独立文告的惯例（1789年法兰西人权宣言、拉丁美洲各国告谕）；但那时黑人奴役与边疆印第安人不在「民」的名单里，1777至1783年战争须借法国、荷兰、西班牙相助才取胜。1783年凡尔赛条约承认他们自立，1787年宪法与1791年权利条款成其国体；它没有兑现的平等之说，到十九世纪内战与二十世纪民权之役还没有做完。同年英国也派向东使节向清朝求商（此人1793年到热河，所请都被旧例挡住）。", "figures": ["（主笔）托玛斯·杰弗逊", "（其议之倡）理查德·李", "（其说之助）托马斯·潘恩"], "place": "费城", "state": "北美十三殖民地", "sources": ["1776年《宣告之文》之草与订本、大陆会议之议事录、潘恩《常理》原本", "《剑桥美国革命之史》、贝林《美国创建之文》"], "tags": ["独立", "人权之文", "奴隶之悖"]}, "related": []},
  {"id": "world--1789--p01", "track": "world", "year": 1789, "yearApprox": false, "dim": "politics", "weight": 5, "title": "法兰西革命：议会与巴士底", "summary": "三级会议一变而为国民议会，一座监狱陷落，旧权解散。", "detail": {"background": "1788年歉收与严冬使面包价格到夏天涨到极点，穷人每日须以半工资换吃的；国债与美洲战事费用相加，1788年的「贵族庭」与1789年税议互相激荡，第三等级请求加倍名额并按人头记名表决。", "process": "1789年5月5日三级会议开于凡尔赛（教士二百九十一、贵族二百七十、第三等级五百七十八）；6月17日第三等级自组国民议会，20日在弹球局宣誓不写出宪法就不解散，7月9日改称制议会。11日国王罢免内克尔，12日京师乱起，14日巴士底狱陷落（狱中只有七人，守将被杀），7、8月「大恐」延到各省；8月4日夜里废除封建的特权，26日完成《人权与民权之宣言》；10月5、6日王族自凡尔赛进入巴黎。", "impact": "自此旧邦的骨架（特权、教产、行会、领税）连年被拆：1790年教士宣誓条约、1791年宪法与6月瓦尔内出逃、1792年8月废王与9月共和国、1793年1月处死路易十六、1793至1794年安全委员会的政事（断头台与狱中死者，学界按万六千到四万来算，统计方法不同）、1795年督府、1799年11月执政府。它的主张与军队延到全欧洲，直到1815年；海地与拉丁美洲独立都趁此空隙。", "figures": ["（第三级之口）奥诺雷·米拉波", "（其文之草）西耶士", "（其时之王）路易十六"], "place": "凡尔赛、巴黎", "state": "法兰西王国（后为共和国）", "sources": ["1789年之陈情书（诸教区之汇编）、会议之议事录与《人权宣言》文本", "《剑桥近代欧洲史》、道伊尔《法兰西之革与旧邦之终》"], "tags": ["革命", "人权宣言", "旧邦之解"]}, "related": []},
  {"id": "world--1791--p01", "track": "world", "year": 1791, "yearApprox": false, "dim": "politics", "weight": 3, "title": "圣多明各黑奴反叛", "summary": "一岛蔗田起火，其糖与废奴之令相互激荡。", "detail": {"background": "这岛是法国产糖与咖啡的园子，岛上户口：白人数万、混血与自由黑人二十余万、为奴者超过四十万（学界据1789年册子推定），其糖供欧洲市场大半；1789年以后巴黎关于权利的争论没有落到这岛奴隶身上。", "process": "1791年8月22日夜里北部省种植场一起起事，烧蔗田、占堡，杀掉庄主；1792年巴黎派特使，1793年8月、10月两位特使先后颁解放令；西班牙党派与英兵各趁空隙，杜桑—卢维杜尔自西边回来，1794年2月法兰西大会决定各属地废除买卖人口与蓄奴制度；1798年杜桑驱英人到山南，1799年总揽全岛政务。", "impact": "这次反叛倾覆全岛糖业（其产量到十八世纪末不足旧额一半，依种植场荒废与战事破坏计算），古巴、爪哇与路易斯安那的糖因此兴起；第一共和国废奴令由此颁行（1802年拿破仑在几个岛恢复奴役制度，1848年才全部废除）。白人死数千、为奴者的死（战、疫与饥）以数万到十余万计，学界因户籍不全而争论。论者说这反叛是对「人权之宣」的真实检验，也是大西洋奴隶制度终局的开始。", "figures": ["（其起之众首）布克曼与苏克里", "杜桑—卢维杜尔", "（法之特派）桑托纳克斯、波尔维埃尔"], "place": "圣多明各（今海地与多米尼加）", "state": "法兰西、西班牙、大不列颠、岛之黑奴社会", "sources": ["1791—1794年之岛报、特派之使与议会之法令、杜桑之告与札", "《剑桥拉丁美洲史》第三卷、詹姆斯《黑色的雅各宾》、克拉克《杜桑—卢维杜尔》"], "tags": ["废奴", "糖业", "海地"]}, "related": []},
  {"id": "world--1798--x01", "track": "world", "year": 1798, "yearApprox": false, "dim": "explore", "weight": 3, "title": "法国取埃及与阿布基尔覆没", "summary": "一军入尼罗河口，舰队覆亡，东方学问由此兴。", "detail": {"background": "1797年坎波福尔米奥条约后奥地利势力西缩，督政府想断英国通红海之路，又欲显示它在东方的力量；1798年5月19日自土伦出航，6月取马耳他，7月2日进入开罗。", "process": "1798年7月21日吉萨（金字塔）大捷，马木路克骑兵溃散；8月1至2日阿布基尔湾中法国舰队几乎全部覆没在纳尔逊手里，东方陆军因此失去海上接应。1799年3月阿克尔围攻没攻下，5月拿破仑偷偷回去；这年7月兵士于罗塞塔得刻三种文字的石碑（前196年诏书，以古埃及字、民间体与希腊文并列）。随军学者一百多人设埃及学院，测它的古迹与博物，后来《埃及述》图籍刊至十九世纪二十年代。", "impact": "英国东印度路与奥斯曼东方自此成为欧洲大陆相争之地；1801年英国人赶走法军，1805年后穆罕默德·阿里在开罗当政。罗塞塔碑很快归英国人，商博良1822年读出它的古字，埃及学由此成立。学者论欧洲对东方的知识，以此番征伐与图籍为欧洲直接考察伊斯兰地区的开始，也为此后百年英、法东方较量的征兆。", "figures": ["拿破仑·波拿巴", "（其随军之博物）儒弗瓦·圣伊莱尔", "（其海之敌）霍雷肖·纳尔逊"], "place": "马耳他、开罗、吉萨、阿布基尔湾、罗塞塔", "state": "法兰西共和国、奥斯曼之埃及、大不列颠", "sources": ["随军学者之札记与《埃及述》之图版（1809年后刊）、拿破仑之通信与督府之令", "《剑桥奥斯曼史》之晚期、卡拉巴《拿破仑在埃及》"], "tags": ["埃及之征", "罗塞塔之碑", "东方之知"]}, "related": []},
  {"id": "world--1799--m01", "track": "world", "year": 1799, "yearApprox": false, "dim": "military", "weight": 3, "title": "塞林加帕坦陷落与迈索尔平定", "summary": "一城一王俱亡，南印度更无抵抗之人。", "detail": {"background": "提普·苏尔坦继承父亲海达尔旧业，占迈索尔并仿效他的军制、与法兰西和奥斯曼通使、结连马拉塔与尼扎姆抗公司；1790至1792年第一次战役后公司削去他一半土地，1798年法国进意大利而东方援救希望断绝，1799年初英国用尼扎姆军队合三道并进。", "process": "1799年5月4日总攻塞林加帕坦，工兵破坏土墙与暗道，提普死于城门边，府库、图籍与两个儿子都归英国；国土分作五份而公司取走土地与税。同年11月9日巴黎雾月执政府成立，公司在印度则对各邦推行附属同盟条约。", "impact": "自此南印度无能抗公司者，1803至1805年第二次马拉塔之役接续这势头，英国领有土地与税逐年扩大；棉、靛与后来的铁路都在公司与总督算计中。论印度近代史的人把1757年与1799年当作两个界限：一个取富庶行省，一个灭强敌，结果是十九世纪全印度的局面。", "figures": ["提普·苏尔坦", "（其敌之督）韦尔斯利侯爵", "（攻者之将）哈里斯"], "place": "塞林加帕坦（今印度卡纳塔克邦）", "state": "迈索尔王国、英国东印度公司、海德拉巴之尼扎姆", "sources": ["1799年之军报与围城之图、公司之档与塞林加帕坦府库之册", "《剑桥印度史》第二卷、近人《韦尔斯利之政与迈索尔之亡》"], "tags": ["迈索尔", "附属同盟", "公司之土"]}, "related": []}
];
